const fs=require('fs'),{chromium}=require('playwright');const out='.spomove-audit-stage2';
const modes=['Reactive Cognition','Visual Reaction','Simon Effect','Flanker Effect','Stroop Effect','Sequential Memory','Dive Mode'],widths=[320,360,390,430,768,1024,1280,1440,1920];
(async()=>{const b=await chromium.launch();try{const c=await b.newContext({serviceWorkers:'block',viewport:{width:1440,height:900}});const errors=[],blocked=[],rows=[],variants=[];await c.route('**/*',r=>{const u=new URL(r.request().url());if(u.hostname!=='127.0.0.1'||u.port!=='3119'){blocked.push(u.origin+u.pathname);return r.abort()}if(u.pathname==='/api/auth/check-admin')return r.fulfill({json:{admin:true,scope:'admin'}});if(u.pathname.startsWith('/mock-supabase/rest/')){const id=(u.searchParams.get('id')||'').replace('eq.',''),row=id.includes('variant')?{id,assets_json:{paths:Array.from({length:16},(_,i)=>'audit-local/slot-'+i+'.svg')}}:null;return r.fulfill({json:r.request().headers().accept?.includes('vnd.pgrst.object')?row:row?[row]:[]})}if(u.pathname.includes('/storage/'))return r.fulfill({contentType:'image/svg+xml',body:fs.readFileSync(out+'/assets/slot-0.svg')});if(u.pathname.startsWith('/api/'))return r.fulfill({status:503,json:{error:'AUDIT_OFFLINE'}});if(!['GET','HEAD'].includes(r.request().method()))return r.abort();return r.continue()});const p=await c.newPage();p.on('pageerror',e=>errors.push(e.message));const url='http://127.0.0.1:3119/admin/spomove/training';
async function measure(){return p.evaluate(()=>{const el=document.querySelector('.settings-body'),theme=document.querySelector('.theme-options'),buttons=[...el.querySelectorAll('button')].filter(e=>e.getBoundingClientRect().width>0);return{header:el.previousElementSibling.innerText,compact:el.classList.contains('compact-menu'),themeDisplay:getComputedStyle(theme).display,themeColumns:getComputedStyle(theme).gridTemplateColumns,overflow:document.documentElement.scrollWidth>innerWidth,small:buttons.filter(e=>e.getBoundingClientRect().height<43.5).map(e=>({text:e.innerText,height:e.getBoundingClientRect().height})),overlap:buttons.filter(e=>{const r=e.getBoundingClientRect();if(r.top<50||r.bottom>innerHeight)return false;const hit=document.elementFromPoint(r.x+r.width/2,r.y+r.height/2);return hit&&!e.contains(hit)}).map(e=>e.innerText)}})}
for(const mode of modes){await p.goto(url,{waitUntil:'domcontentloaded',timeout:120000});await p.getByRole('button').filter({hasText:mode}).click({timeout:120000});const themes=await p.locator('.theme-option').allTextContents();for(let i=0;i<themes.length;i++){if(themes[i].includes('부록'))continue;await p.locator('.theme-option').nth(i).click();for(const w of [...widths,844]){const h=w===844?390:900;await p.setViewportSize({width:w,height:h});await p.waitForTimeout(350);rows.push({mode,theme:themes[i],w,h,...await measure()})}if(mode==='Simon Effect'&&i>=3){await p.setViewportSize({width:390,height:900});await p.waitForTimeout(400);await p.evaluate(()=>scrollTo(0,0));await p.screenshot({path:`${out}/admin-simon-${i+1}-390.png`,fullPage:true})}const sections=await p.locator('.settings-column section').evaluateAll(ss=>ss.map((s,i)=>({i,label:s.querySelector('label')?.innerText,buttons:[...s.querySelectorAll('button:not(.theme-option)')].map(b=>b.innerText)})).filter(s=>s.label&&s.buttons.length&&!s.buttons.some(b=>/부록|프리셋|시작|삭제/.test(b))));for(const section of sections)for(let j=0;j<section.buttons.length;j++){const button=p.locator('.settings-column section').nth(section.i).locator('button:not(.theme-option)').nth(j);if(!(await button.count()))continue;await button.click({timeout:5000});for(const w of [390,1440]){await p.setViewportSize({width:w,height:900});await p.waitForTimeout(350);variants.push({mode,theme:themes[i],group:section.label,option:section.buttons[j],w,...await measure()})}}fs.writeFileSync(out+'/admin-matrix.json',JSON.stringify({rows,variants,errors,blocked:[...new Set(blocked)]},null,2))}console.log(mode+' matrix done')}await c.close()}finally{await b.close()}})().catch(e=>{console.error(e);process.exitCode=1});

﻿const fs=require('fs'),{chromium}=require('playwright');const out='.spomove-audit-stage2';
const modes=['Reactive Cognition','Visual Reaction','Simon Effect','Flanker Effect','Stroop Effect','Sequential Memory','Dive Mode'],widths=[320,360,390,430,768,1024,1280,1440,1920];
(async()=>{const b=await chromium.launch();try{const c=await b.newContext({serviceWorkers:'block',viewport:{width:1440,height:900}});const errors=[],blocked=[],rows=[],variants=[];await c.route('**/*',r=>{const u=new URL(r.request().url());if(u.hostname!=='127.0.0.1'||u.port!=='3118'){blocked.push(u.origin+u.pathname);return r.abort()}if(u.pathname==='/api/auth/check-admin')return r.fulfill({json:{admin:true,scope:'admin'}});if(u.pathname.startsWith('/mock-supabase/rest/')){const id=(u.searchParams.get('id')||'').replace('eq.',''),row=id.includes('variant')?{id,assets_json:{paths:Array.from({length:16},(_,i)=>'audit-local/slot-'+i+'.svg')}}:null;return r.fulfill({json:r.request().headers().accept?.includes('vnd.pgrst.object')?row:row?[row]:[]})}if(u.pathname.includes('/storage/'))return r.fulfill({contentType:'image/svg+xml',body:fs.readFileSync(out+'/assets/slot-0.svg')});if(u.pathname.startsWith('/api/'))return r.fulfill({status:503,json:{error:'AUDIT_OFFLINE'}});if(!['GET','HEAD'].includes(r.request().method()))return r.abort();return r.continue()});const p=await c.newPage();p.on('pageerror',e=>errors.push(e.message));const url='http://127.0.0.1:3118/audit?surface=admin';
async function measure(){return p.evaluate(()=>{const el=document.querySelector('.settings-body'),theme=document.querySelector('.theme-options'),buttons=[...el.querySelectorAll('button')].filter(e=>e.getBoundingClientRect().width>0);return{header:el.previousElementSibling.innerText,compact:el.classList.contains('compact-menu'),themeDisplay:getComputedStyle(theme).display,themeColumns:getComputedStyle(theme).gridTemplateColumns,overflow:document.documentElement.scrollWidth>innerWidth,small:buttons.filter(e=>e.getBoundingClientRect().height<43.5).map(e=>({text:e.innerText,height:e.getBoundingClientRect().height})),overlap:buttons.filter(e=>{const r=e.getBoundingClientRect();if(r.top<50||r.bottom>innerHeight)return false;const hit=document.elementFromPoint(r.x+r.width/2,r.y+r.height/2);return hit&&!e.contains(hit)}).map(e=>e.innerText)}})}
for(const mode of modes){await p.goto(url,{waitUntil:'domcontentloaded',timeout:120000});await p.waitForFunction(()=>!!window.auditCatalog,{timeout:60000});await p.locator('button.spmt-card').filter({hasText:mode}).click({timeout:30000});const themes=await p.locator('.theme-option').allTextContents();for(let i=0;i<themes.length;i++){if(themes[i].includes('부록'))continue;await p.locator('.theme-option').nth(i).click();for(const w of [...widths,844]){const h=w===844?390:900;await p.setViewportSize({width:w,height:h});await p.waitForTimeout(350);rows.push({mode,theme:themes[i],w,h,...await measure()})}if(mode==='Simon Effect'&&i>=3){await p.setViewportSize({width:390,height:900});await p.waitForTimeout(400);await p.evaluate(()=>scrollTo(0,0));await p.screenshot({path:`${out}/admin-simon-${i+1}-390.png`,fullPage:true})}const sections=await p.locator('.settings-column section').evaluateAll(ss=>ss.map((s,i)=>({i,label:s.querySelector('label')?.innerText,buttons:[...s.querySelectorAll('button:not(.theme-option)')].map(b=>b.innerText)})).filter(s=>s.label&&s.buttons.length&&!s.buttons.some(b=>/부록|프리셋|시작|삭제/.test(b))));for(const section of sections)for(let j=0;j<section.buttons.length;j++){const button=p.locator('.settings-column section').nth(section.i).locator('button:not(.theme-option)').nth(j);if(!(await button.count()))continue;await button.click({timeout:5000});for(const w of [390,1440]){await p.setViewportSize({width:w,height:900});await p.waitForTimeout(350);variants.push({mode,theme:themes[i],group:section.label,option:section.buttons[j],w,...await measure()})}}fs.writeFileSync(out+'/admin-state-harness.json',JSON.stringify({rows,variants,errors,blocked:[...new Set(blocked)]},null,2))}console.log(mode+' matrix done')}await c.close()}finally{await b.close()}})().catch(e=>{console.error(e);process.exitCode=1});

﻿const fs=require('fs'),path=require('path'),cp=require('child_process');
const root=process.cwd(),dest=path.resolve(root,'.spomove-audit-stage2/build-workspace');if(!dest.startsWith(root+path.sep))throw Error('invalid audit build destination');fs.mkdirSync(dest,{recursive:true});
const list=cp.execFileSync('git',['ls-files','-z'],{encoding:'utf8'}).split('\0').filter(Boolean);let copied=0;
for(const f of list){if(!fs.existsSync(f)||f.startsWith('.env')||f.startsWith('.git')||f.startsWith('.spomove-audit')||/\.(zip|log|png|jpg|jpeg|webp|mp4|mp3|glb|gltf|unityweb|wasm|br|gz)$/i.test(f)&&!f.startsWith('public/'))continue;if(!fs.statSync(f).isFile())continue;const target=path.join(dest,f);fs.mkdirSync(path.dirname(target),{recursive:true});fs.copyFileSync(f,target);copied++;}
for(const f of ['next-env.d.ts'])if(fs.existsSync(f))fs.copyFileSync(f,path.join(dest,f));
if(!fs.existsSync(path.join(dest,'node_modules')))fs.symlinkSync(path.join(root,'node_modules'),path.join(dest,'node_modules'),'junction');
const env={};for(const k of ['PATH','Path','SystemRoot','TEMP','TMP','COMSPEC','WINDIR','USERPROFILE','LOCALAPPDATA','APPDATA','NUMBER_OF_PROCESSORS','PROCESSOR_ARCHITECTURE'])if(process.env[k])env[k]=process.env[k];Object.assign(env,{NODE_ENV:'production',NEXT_TELEMETRY_DISABLED:'1',NEXT_PUBLIC_SUPABASE_URL:'http://127.0.0.1:9',NEXT_PUBLIC_SUPABASE_ANON_KEY:'audit-only-not-real',NODE_OPTIONS:'--require '+JSON.stringify(path.join(root,'.spomove-audit-stage2/network-guard.cjs'))});
fs.writeFileSync('.spomove-audit-stage2/build-metadata.json',JSON.stringify({copied,destination:dest,usesEnvLocal:false,externalNetwork:'blocked',source:'current tracked working files; unrelated homepage changes included'},null,2));
const log=fs.openSync('.spomove-audit-stage2/production-build.log','w');const child=cp.spawn(process.execPath,[path.join(root,'node_modules/next/dist/bin/next'),'build','--webpack'],{cwd:dest,env,stdio:['ignore',log,log],windowsHide:true});child.on('exit',(code,signal)=>{fs.closeSync(log);fs.writeFileSync('.spomove-audit-stage2/production-build-result.json',JSON.stringify({code,signal,copied},null,2));console.log('Production build exit '+code);process.exitCode=code||0});

const fs=require('fs'),path=require('path'),crypto=require('crypto');const dir='.spomove-audit-stage2';
const lines=['id,status,evidence,setup,run,stop_result,natural_result,return'];for(const x of JSON.parse(fs.readFileSync(dir+'/official-selected-evidence.json'))){const s=x.steps||{};lines.push([x.id,x.status,x.evidence||'',!!s.setup,!!s.running,!!x.stopResult,!!x.natural?.completed,!!s.returned].join(','))}fs.writeFileSync(dir+'/official-coverage.csv',lines.join('\n'));
const t=['id,status,evidence,stop_result,natural_result,return,return_body_overflow'];for(const x of JSON.parse(fs.readFileSync(dir+'/teacher-selected-evidence.json'))){t.push([x.id,x.status,x.evidence||'',!!x.stopResult,!!x.natural?.completed,!!x.steps?.returned,x.steps?.returned?.bodyOverflow||''].join(','))}fs.writeFileSync(dir+'/teacher-coverage.csv',t.join('\n'));
fs.writeFileSync(dir+'/render-attempts.json',JSON.stringify({nextAdmin:[{script:'admin-matrix.cjs',status:'UNVERIFIED',error:'page.goto timeout 120000ms'},{script:'next-repro.cjs',status:'UNVERIFIED',error:'page.goto timeout 180000ms'}],harnessAdmin:{script:'admin-state-harness.cjs',status:'UNVERIFIED',errors:['initial card locator timeout','subsequent auditCatalog initialization timeout']},browsers:{executed:['Playwright Chromium on Windows'],notExecuted:['Firefox','WebKit','real iOS Safari','real Android browser']},audio:'muted MASTER and no BGM fixture; Teacher beep path not auditory-validated'},null,2));
const manifest=[];function walk(d){for(const e of fs.readdirSync(d,{withFileTypes:true})){if(e.name==='build-workspace'||e.name==='evidence-manifest.json')continue;const f=path.join(d,e.name);if(e.isDirectory())walk(f);else{const data=fs.readFileSync(f);manifest.push({path:f.replaceAll('\\','/'),bytes:data.length,sha256:crypto.createHash('sha256').update(data).digest('hex')})}}}walk(dir);fs.writeFileSync(dir+'/evidence-manifest.json',JSON.stringify(manifest,null,2));
const reports=['SPOMOVE_FORENSIC_AUDIT_STAGE2.md','SPOMOVE_FIX_PLAN.md'];const missing=[];for(const file of reports){const text=fs.readFileSync(file,'utf8');for(const m of text.matchAll(/\]\(([^)]+)\)/g))if(!m[1].startsWith('http')&&!fs.existsSync(m[1]))missing.push({report:file,path:m[1]})}console.log(JSON.stringify({evidenceFiles:manifest.length,evidenceBytes:manifest.reduce((n,f)=>n+f.bytes,0),missingReportLinks:missing}));

﻿import React,{useState} from 'react';import {createRoot} from 'react-dom/client';
import SessionPage from '../app/spokedu-master/spomove/session/page';
import TeacherPage from '../app/teacher/spomove/page';
import AdminPage from '../app/admin/spomove/training/page';
import {MasterAccessProvider} from '../app/spokedu-master/access/MasterAccessProvider';
import {OFFICIAL_SPOMOVE_LIBRARY} from '../app/spokedu-master/spomove/officialSpomovePresets';
import {TEACHER_SPOMOVE_WEEKS,buildTeacherAutoLaunch} from '../app/teacher/spomove/teacherSpomoveCurriculum';
import * as clock from '../app/admin/spomove/training/_player/lib/runtimeClock';
import * as locks from '../app/admin/spomove/training/_player/lib/lockViewportScroll';
import {useMasterStore} from '../app/spokedu-master/store';
import './harness.css';
const w=window as any;w.auditNavigations=[];w.auditCatalog={official:OFFICIAL_SPOMOVE_LIBRARY,teacher:TEACHER_SPOMOVE_WEEKS.map(week=>({...week,programs:week.programs.map(p=>({...p,launch:buildTeacherAutoLaunch(p)}))}))};w.auditClock=clock;w.auditLocks=locks;w.auditStore=useMasterStore;
const root=createRoot(document.getElementById('root')!);w.auditUnmount=()=>root.render(<div data-audit-return>returned</div>);
const surface=new URLSearchParams(location.search).get('surface');
const snapshot:any={canUseSpomove:true,isAdmin:true,plan:'premium',subscriptionStatus:'active',canUseRecords:true,canUseLibrary:true};
root.render(surface==='teacher'?<TeacherPage/>:surface==='admin'?<AdminPage/>:<MasterAccessProvider snapshot={snapshot}><SessionPage/></MasterAccessProvider>);

const deny=u=>{const s=String(u?.href||u?.hostname||u);if(!/^https?:\/\/(127\.0\.0\.1|localhost)(:|\/|$)/.test(s))throw new Error('AUDIT_EXTERNAL_NETWORK_BLOCKED');};
const realFetch=globalThis.fetch;globalThis.fetch=(u,o)=>{deny(typeof u==='string'||u instanceof URL?u:u.url);return realFetch(u,o)};
for(const protocol of ['http','https']){const m=require(protocol);for(const key of ['request','get']){const original=m[key];m[key]=function(u,...args){deny(typeof u==='object'&&!(u instanceof URL)?protocol+'://'+(u.hostname||u.host||''):u);return original.call(this,u,...args)}}}

﻿const fs=require('fs'),{chromium}=require('playwright');
const out='.spomove-audit-stage2';
async function context(browser,width=1440){const c=await browser.newContext({viewport:{width,height:900},serviceWorkers:'block'});c.audit={errors:[],blocked:[],writes:[]};await c.route('**/*',r=>{const req=r.request(),u=new URL(req.url());if(u.hostname!=='127.0.0.1'){c.audit.blocked.push(u.origin+u.pathname);return r.abort()}if(!['GET','HEAD'].includes(req.method())){c.audit.writes.push({method:req.method(),path:u.pathname});return r.fulfill({status:503,json:{error:'AUDIT_WRITE_BLOCKED'}})}if(u.pathname.startsWith('/api/'))return r.fulfill({json:{ok:true,data:[]}});return r.continue()});return c}
async function open(c,url){const p=await c.newPage();p.on('pageerror',e=>c.audit.errors.push(e.message));await p.clock.install();await p.goto(url,{waitUntil:'domcontentloaded',timeout:120000});await p.waitForFunction(()=>!!window.auditCatalog,{timeout:60000});await p.clock.runFor(500);return p}
async function metrics(p){return p.evaluate(()=>({text:document.body.innerText,htmlOverflow:document.documentElement.style.overflow,bodyOverflow:document.body.style.overflow,overflow:document.documentElement.scrollWidth>innerWidth,buttons:[...document.querySelectorAll('button')].filter(b=>b.getBoundingClientRect().width>0).map(b=>({text:b.innerText.slice(0,70),height:b.getBoundingClientRect().height})),navigations:window.auditNavigations,receipts:sessionStorage.getItem('spokedu-master:spomove-terminal-receipt:v1'),active:sessionStorage.getItem('spokedu-master:spomove-active-run:v1'),recent:window.auditStore?.getState().recentProgramActivities}))}
async function stop(p){for(const selector of ['.vrt-stop','.bw-stop','.sc-stop','button:has-text("STOP")','button:has-text("훈련 종료")','button[aria-label="나가기"]']){const l=p.locator(selector).filter({visible:true});if(await l.count()){await l.first().click({force:true});await p.clock.runFor(100);return selector}}throw Error('NO_STOP_CONTROL')}
async function advance(p,ms){let timer;try{return await Promise.race([p.clock.fastForward(ms),new Promise((_,reject)=>{timer=setTimeout(()=>reject(Error('AUDIT_CLOCK_COMMAND_TIMEOUT')),20000)})])}finally{clearTimeout(timer)}}
async function untilResult(p,limit=360000){let reveals=0;for(let ms=0;ms<limit;ms+=10000){if(await p.locator('.tr-result-root').count())return {completed:true,virtualMs:ms,reveals};const action=p.getByRole('button').filter({hasText:/^(정답 공개|정답 목록 보기|결과 보기|질문 시작|다음 \(|▶ 다음|🎉 완료|훈련 완료|전체 정답 목록)/}).filter({visible:true});if(await action.count()){await action.first().click({force:true});reveals++}else if(/스페이스바|Space\/Enter|클릭 · 스페이스/.test(await p.locator('body').innerText())){await p.locator('body').click({position:{x:5,y:innerSafeY(p)}}).catch(()=>{});await p.keyboard.press('Space');reveals++}for(let tick=0;tick<20;tick++)await advance(p,500);await p.waitForTimeout(5)}return {completed:!!(await p.locator('.tr-result-root').count()),virtualMs:limit,reveals}}
function innerSafeY(p){return 200}
async function setup(p){await p.getByRole('button',{name:'수업 시작',exact:true}).waitFor({timeout:30000});const mute=p.getByRole('button',{name:'무음',exact:true});if(await mute.count())await mute.click({force:true});return metrics(p)}
async function ready(p){for(let i=0;i<40;i++){await p.waitForTimeout(150);await p.clock.fastForward(500);const has=await p.locator('button').evaluateAll(bs=>bs.some(b=>b.getBoundingClientRect().width>0&&/STOP|종료|중지/.test(b.innerText)));if(has){for(let j=0;j<10;j++)await p.clock.fastForward(500);await p.waitForTimeout(150);return true}}return false}
async function official(browser,ids){const rows=[];for(const item of ids){const row={surface:'master-client',clockMode:'fastForward500ms',id:item.id,engine:item.engine,steps:{}};let c,p;try{c=await context(browser);p=await open(c,`http://127.0.0.1:3118/spokedu-lab/spomove/session?preset=${encodeURIComponent(item.id)}&entry=settings&mode=mobile&sound=off`);row.steps.setup=await setup(p);await p.getByRole('button',{name:'수업 시작',exact:true}).click({force:true});row.ready=await ready(p);row.steps.running=await metrics(p);row.stopControl=await stop(p);await p.waitForTimeout(100);row.steps.stopped=await metrics(p);row.stopResult=!!await p.locator('.tr-result-root').count();if(!row.stopResult)throw Error('NO_STOP_RESULT');const retry=p.getByRole('button',{name:'같은 설정으로 다시 준비',exact:true});await retry.first().click({force:true});await p.clock.runFor(500);row.steps.retrySetup=await setup(p);await p.getByRole('button',{name:'수업 시작',exact:true}).click({force:true});await ready(p);row.natural=await untilResult(p);row.steps.naturalResult=await metrics(p);if(row.natural.completed){await p.screenshot({path:`${out}/official-${item.id}.png`});const back=p.getByRole('link',{name:'활동 목록으로',exact:true});if(await back.count())await back.click({force:true});else await p.getByRole('button',{name:'목록',exact:true}).first().click({force:true});await p.clock.runFor(100);row.steps.returned=await metrics(p)}row.status=row.natural.completed?'EXECUTED':'UNVERIFIED_TIMEOUT';}catch(e){row.status='FAILED_OR_BLOCKED';row.error=e.message;if(p){row.failure=await metrics(p).catch(()=>null);await p.screenshot({path:`${out}/failure-${item.id}.png`}).catch(()=>{})}}finally{if(c){row.transport=c.audit;await c.close()}}rows.push(row);fs.writeFileSync(`${out}/official-results${process.env.AUDIT_SHARD ? '-shard'+process.env.AUDIT_SHARD : ''}.json`,JSON.stringify(rows,null,2));console.log(`${rows.length}/${ids.length} ${item.id}: ${row.status} ${row.error||''}`)}return rows}
module.exports={context,open,metrics,stop,untilResult,setup,ready,official};
if(require.main===module)(async()=>{const browser=await chromium.launch({args:['--enable-unsafe-swiftshader']});try{const c=await context(browser);const p=await open(c,'http://127.0.0.1:3118/audit?preset=reaction-cognition-space-direction-01&entry=settings');const catalog=await p.evaluate(()=>window.auditCatalog);fs.writeFileSync(`${out}/catalog.json`,JSON.stringify(catalog,null,2));await c.close();let ids=catalog.official;if(process.env.AUDIT_SHARD)ids=ids.filter((_,i)=>i%3===Number(process.env.AUDIT_SHARD)-1);if(process.env.AUDIT_FROM)ids=ids.slice(Number(process.env.AUDIT_FROM));if(process.env.AUDIT_ONLY)ids=ids.filter(p=>process.env.AUDIT_ONLY.split(',').includes(p.id));if(process.env.AUDIT_LIMIT)ids=ids.slice(0,Number(process.env.AUDIT_LIMIT));await official(browser,ids)}finally{await browser.close()}})().catch(e=>{console.error(e);process.exitCode=1});

const fs=require('fs'),crypto=require('crypto'),path=require('path');
const out='.spomove-audit-stage2';fs.mkdirSync(out,{recursive:true});
fs.copyFileSync('SPOMOVE_FORENSIC_AUDIT.md',out+'/stage1-report-preserved.md');
const roots=['app','docs','lib','types'];const files=[];function walk(d){for(const e of fs.readdirSync(d,{withFileTypes:true})){const p=path.join(d,e.name);if(e.isDirectory())walk(p);else files.push(p.replaceAll('\\','/'));}}for(const r of roots)if(fs.existsSync(r))walk(r);for(const p of ['AGENTS.md','package.json','package-lock.json','next.config.ts','tsconfig.json','next-env.d.ts','proxy.ts'])if(fs.existsSync(p))files.push(p);
const hashes=Object.fromEntries(files.map(p=>[p,crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex')]));fs.writeFileSync(out+'/start-source-hashes.json',JSON.stringify(hashes,null,2));console.log('Preserved report; hashed '+files.length+' source files');

