'use client';
import { useViewportScrollLock } from '../lib/lockViewportScroll';

import { useCallback, useEffect, useState } from 'react';
import { createPortal } from 'react-dom';
import { StudentModal } from './StudentModal';
import { StudentManageScreen } from './StudentManageScreen';
import { useStudents } from '../hooks/useStudents';

const SPOKEDU_PROMO_BANNERS = [
  '/spokedu/spokedu-promo-banner-1.png',
  '/spokedu/spokedu-promo-banner.png',
] as const;

const HERO_ANIM_CSS = `
@keyframes spomoveCatalogHeroFadeUp {
  from { opacity: 0; transform: translateY(14px); }
  to { opacity: 1; transform: translateY(0); }
}
.spomove-catalog-hero-fadein {
  animation: spomoveCatalogHeroFadeUp 0.55s cubic-bezier(0.22,1,0.36,1) both;
}
@media (prefers-reduced-motion: reduce) {
  .spomove-catalog-hero-fadein { animation: none; opacity: 1; transform: none; }
}
`;

/**
 * MemoryGameApp 홈 상단과 동일한 브랜딩·학생 선택·PLAY/THINK/FLOW·헤드라인 블록.
 * SPOMOVE Training 카탈로그(/admin/spomove/training) 상단에서 사용.
 */
export function SpomoveCatalogHero() {
  const { students, add: addStudent, remove: removeStudent, rename: renameStudent } = useStudents();
  const [selectedStudentId, setSelectedStudentId] = useState<string | null>(null);
  const [showStudentModal, setShowStudentModal] = useState(false);
  const [showStudentManage, setShowStudentManage] = useState(false);
  const [bannerLightboxOpen, setBannerLightboxOpen] = useState(false);
  const [bannerMounted, setBannerMounted] = useState(false);
  const [activeBannerIndex, setActiveBannerIndex] = useState(0);
  const [theme] = useState(() =>
    typeof window !== 'undefined' ? localStorage.getItem('spokedu_theme') || 'light' : 'light',
  );

  useEffect(() => {
    setBannerMounted(true);
  }, []);

  const closeBannerLightbox = useCallback(() => setBannerLightboxOpen(false), []);
  const activeBannerSrc = SPOKEDU_PROMO_BANNERS[activeBannerIndex];
  const showPreviousBanner = () => {
    setActiveBannerIndex((current) => (current - 1 + SPOKEDU_PROMO_BANNERS.length) % SPOKEDU_PROMO_BANNERS.length);
  };
  const showNextBanner = () => {
    setActiveBannerIndex((current) => (current + 1) % SPOKEDU_PROMO_BANNERS.length);
  };

  useViewportScrollLock(bannerLightboxOpen);
  useEffect(() => {
    if (!bannerLightboxOpen) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') closeBannerLightbox();
    };
    window.addEventListener('keydown', onKey);
    return () => {
      window.removeEventListener('keydown', onKey);
    };
  }, [bannerLightboxOpen, closeBannerLightbox]);

  useEffect(() => {
    if (typeof window !== 'undefined') localStorage.setItem('spokedu_theme', theme);
  }, [theme]);

  return (
    <div
      data-theme={theme}
      style={{
        position: 'relative',
        overflow: 'hidden',
        background: '#080C14',
        fontFamily: 'var(--spm-font-body)',
        color: '#fff',
        borderBottom: '1px solid rgba(255,255,255,0.08)',
      }}
    >
      <style>{HERO_ANIM_CSS}</style>
      <div
        aria-hidden
        style={{
          position: 'absolute',
          top: '-25%',
          left: '-8%',
          width: 'min(55vw, 520px)',
          height: 'min(55vw, 520px)',
          borderRadius: '50%',
          background: 'radial-gradient(circle, rgba(249,115,22,0.10) 0%, transparent 70%)',
          pointerEvents: 'none',
        }}
      />
      <div
        aria-hidden
        style={{
          position: 'absolute',
          bottom: '-20%',
          right: '-12%',
          width: 'min(50vw, 480px)',
          height: 'min(50vw, 480px)',
          borderRadius: '50%',
          background: 'radial-gradient(circle, rgba(59,130,246,0.08) 0%, transparent 70%)',
          pointerEvents: 'none',
        }}
      />
      <div
        style={{
          maxWidth: 960,
          margin: '0 auto',
          padding: 'clamp(1.25rem,4vw,2rem) clamp(1rem,4vw,1.5rem) clamp(1.35rem,4vw,1.85rem)',
          position: 'relative',
          boxSizing: 'border-box',
        }}
      >
        <div
          className="spomove-catalog-hero-fadein"
          style={{
            margin: '0 auto',
            width: '100%',
            maxWidth: 1120,
            padding: 'clamp(1.1rem,3vw,1.5rem) clamp(1rem,3vw,1.4rem)',
            borderRadius: 18,
            border: '1px solid rgba(255,255,255,0.09)',
            background: 'linear-gradient(180deg, rgba(249,115,22,0.11) 0%, rgba(255,255,255,0.03) 24%, rgba(255,255,255,0.01) 100%)',
            boxShadow: '0 10px 28px rgba(0,0,0,0.35)',
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            textAlign: 'center',
            gap: 'clamp(0.45rem,1.6vw,0.7rem)',
          }}
        >
          <div
            style={{
              position: 'relative',
              margin: 0,
              padding: 0,
              width: '100%',
              maxWidth: 'min(100%, 920px)',
              borderRadius: 12,
              overflow: 'hidden',
              lineHeight: 0,
              boxShadow: '0 8px 24px rgba(0,0,0,0.4)',
            }}
          >
            <button
              type="button"
              onClick={() => setBannerLightboxOpen(true)}
              aria-label={`${activeBannerIndex + 1}번 SPOKEDU 배너 전체 화면으로 보기`}
              style={{
                margin: 0,
                padding: 0,
                border: 'none',
                background: 'transparent',
                cursor: 'zoom-in',
                width: '100%',
                display: 'block',
                lineHeight: 0,
              }}
            >
              <img
                src={activeBannerSrc}
                alt={`${activeBannerIndex + 1}번 SPOKEDU 홍보 배너`}
                width={1600}
                height={900}
                style={{ width: '100%', height: 'auto', display: 'block' }}
                loading="eager"
                decoding="async"
              />
            </button>
            <button type="button" onClick={showPreviousBanner} aria-label="이전 배너" style={bannerArrowStyle('left')}>
              ‹
            </button>
            <button type="button" onClick={showNextBanner} aria-label="다음 배너" style={bannerArrowStyle('right')}>
              ›
            </button>
          </div>
          <div aria-label="배너 선택" style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
            {SPOKEDU_PROMO_BANNERS.map((src, index) => (
              <button
                key={src}
                type="button"
                onClick={() => setActiveBannerIndex(index)}
                aria-label={`${index + 1}번 배너 보기`}
                aria-current={activeBannerIndex === index ? 'true' : undefined}
                style={{
                  width: activeBannerIndex === index ? 22 : 8,
                  height: 8,
                  padding: 0,
                  border: 0,
                  borderRadius: 999,
                  background: activeBannerIndex === index ? '#F97316' : 'rgba(255,255,255,0.28)',
                  cursor: 'pointer',
                  transition: 'width 160ms ease, background 160ms ease',
                }}
              />
            ))}
          </div>
        </div>
      </div>

      {showStudentModal && (
        <StudentModal
          students={students}
          selectedId={selectedStudentId}
          onSelect={(id) => {
            setSelectedStudentId(id);
            setShowStudentModal(false);
          }}
          onClose={() => setShowStudentModal(false)}
          onManage={() => {
            setShowStudentModal(false);
            setShowStudentManage(true);
          }}
        />
      )}
      {showStudentManage && (
        <div
          style={{
            position: 'fixed',
            inset: 0,
            zIndex: 250,
            overflow: 'auto',
            background: '#080C14',
          }}
        >
          <StudentManageScreen
            students={students}
            onAdd={addStudent}
            onRemove={removeStudent}
            onRename={renameStudent}
            onBack={() => setShowStudentManage(false)}
          />
        </div>
      )}

      {bannerMounted && bannerLightboxOpen
        ? createPortal(
            <div
              role="dialog"
              aria-modal="true"
              aria-label="SPOKEDU 배너 전체 화면 — 화면을 누르거나 Esc로 닫기"
              style={{
                position: 'fixed',
                inset: 0,
                zIndex: 200000,
                margin: 0,
                padding: 0,
                boxSizing: 'border-box',
                width: '100vw',
                height: '100dvh',
                maxWidth: '100vw',
                maxHeight: '100dvh',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                background: '#020617',
                cursor: 'zoom-out',
              }}
              onClick={closeBannerLightbox}
            >
              <img
                src={activeBannerSrc}
                alt=""
                width={1600}
                height={900}
                style={{
                  width: '100vw',
                  height: '100dvh',
                  maxWidth: '100vw',
                  maxHeight: '100dvh',
                  objectFit: 'contain',
                  objectPosition: 'center',
                  display: 'block',
                  pointerEvents: 'none',
                  userSelect: 'none',
                }}
                loading="eager"
                decoding="async"
                draggable={false}
              />
            </div>,
            document.body,
          )
        : null}
    </div>
  );
}

function bannerArrowStyle(side: 'left' | 'right') {
  return {
    position: 'absolute' as const,
    top: '50%',
    [side]: 12,
    transform: 'translateY(-50%)',
    width: 42,
    height: 42,
    padding: 0,
    border: '1px solid rgba(255,255,255,0.32)',
    borderRadius: '50%',
    background: 'rgba(2,6,23,0.62)',
    color: '#fff',
    fontSize: 31,
    lineHeight: '36px',
    cursor: 'pointer',
    backdropFilter: 'blur(6px)',
  };
}

'use client';
import { useViewportScrollLock } from '../lib/lockViewportScroll';

import { useState, useEffect, useRef } from 'react';
import { createPortal } from 'react-dom';
import { getSupabaseBrowserClient } from '@/app/lib/supabase/browser';
import { useSpomoveVariantSlidesForTraining } from '../hooks/useSpomoveVariantFruitSlidesForTraining';
import {
  SPOMOVE_COLOR_THEME_LABELS,
  SPOMOVE_THEMED_PACK_BY_THEME,
  type SpomoveColorThemeId,
} from '../lib/spomoveVariantThemeConfig';
import { VARIANT_FRUIT_SLOT_LABELS, SPOMOVE_VARIANT_PACK_ID } from '../lib/variantFruitAssets';

const BG = '#0b0b0b';
const CARD = '#181818';
const BORDER = 'rgba(255,255,255,0.09)';
const TEXT = 'rgba(255,255,255,0.88)';
const MUTED = 'rgba(255,255,255,0.38)';
const ACCENT = '#3B82F6';

type AppendixTheme = Exclude<SpomoveColorThemeId, 'color' | 'mix'>;
const APPENDIX_THEMES: AppendixTheme[] = ['fruit', 'animal', 'food', 'nature', 'vehicle'];

function getDefaultLabels(theme: AppendixTheme): string[] {
  if (theme === 'fruit') return [...VARIANT_FRUIT_SLOT_LABELS];
  return [...SPOMOVE_THEMED_PACK_BY_THEME[theme].slotLabels];
}

function getPackId(theme: AppendixTheme): string {
  if (theme === 'fruit') return SPOMOVE_VARIANT_PACK_ID;
  return SPOMOVE_THEMED_PACK_BY_THEME[theme].packId;
}

function getPackName(theme: AppendixTheme): string {
  if (theme === 'fruit') return 'SPOMOVE 연상 색지각 과일';
  return SPOMOVE_THEMED_PACK_BY_THEME[theme].packName;
}

async function loadStoredLabels(theme: AppendixTheme): Promise<string[] | null> {
  const supabase = getSupabaseBrowserClient();
  const { data } = await supabase
    .from('think_asset_packs')
    .select('assets_json')
    .eq('id', getPackId(theme))
    .maybeSingle();
  const raw = data?.assets_json as { slotLabels?: unknown } | null;
  const stored = raw?.slotLabels;
  if (Array.isArray(stored) && stored.length > 0 && stored.every((s) => typeof s === 'string')) {
    return stored as string[];
  }
  return null;
}

async function saveStoredLabels(theme: AppendixTheme, labels: string[]): Promise<string | null> {
  const packId = getPackId(theme);
  const supabase = getSupabaseBrowserClient();
  const { data: existing } = await supabase
    .from('think_asset_packs')
    .select('assets_json')
    .eq('id', packId)
    .maybeSingle();
  const existingJson = (existing?.assets_json ?? {}) as Record<string, unknown>;

  const res = await fetch('/api/admin/think-asset-pack', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    credentials: 'same-origin',
    body: JSON.stringify({
      id: packId,
      name: getPackName(theme),
      theme: 'iiwarmup',
      assets_json: { ...existingJson, slotLabels: labels },
    }),
  });
  const body = (await res.json().catch(() => ({}))) as { error?: string };
  if (!res.ok) return body.error ?? res.statusText;
  return null;
}

function CategoryContent({ theme }: { theme: AppendixTheme }) {
  const { slides, status } = useSpomoveVariantSlidesForTraining(theme);
  const [labels, setLabels] = useState<string[]>(() => getDefaultLabels(theme));
  const [editingIdx, setEditingIdx] = useState<number | null>(null);
  const [editValue, setEditValue] = useState('');
  const [saving, setSaving] = useState(false);
  const [saveMsg, setSaveMsg] = useState<string | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const userEditedRef = useRef(false);
  const loadGenRef = useRef(0);

  useEffect(() => {
    const gen = ++loadGenRef.current;
    userEditedRef.current = false;
    setEditingIdx(null);
    const defaults = getDefaultLabels(theme);
    void loadStoredLabels(theme).then((stored) => {
      if (loadGenRef.current !== gen || userEditedRef.current) return;
      setLabels(stored ? defaults.map((def, i) => stored[i] ?? def) : defaults);
    });
  }, [theme]);

  const startEdit = (i: number, currentLabel: string) => {
    setEditingIdx(i);
    setEditValue(currentLabel);
    setTimeout(() => inputRef.current?.select(), 0);
  };

  const commitEdit = () => {
    if (editingIdx === null) return;
    const next = [...labels];
    next[editingIdx] = editValue.trim() || (getDefaultLabels(theme)[editingIdx] ?? '');
    userEditedRef.current = true;
    setLabels(next);
    setEditingIdx(null);
  };

  const handleSave = async () => {
    const nextLabels =
      editingIdx === null
        ? labels
        : labels.map((label, i) =>
            i === editingIdx ? editValue.trim() || (getDefaultLabels(theme)[i] ?? label) : label,
          );
    if (editingIdx !== null) {
      userEditedRef.current = true;
      setLabels(nextLabels);
      setEditingIdx(null);
    }
    setSaving(true);
    setSaveMsg(null);
    const err = await saveStoredLabels(theme, nextLabels);
    setSaving(false);
    setSaveMsg(err ? `오류: ${err}` : '저장됨 ✓');
    setTimeout(() => setSaveMsg(null), 2500);
  };

  const items = labels
    .map((label, i) => ({ label, imageUrl: (slides[i]?.imageUrl ?? '').trim(), index: i }))
    .filter((item) => item.imageUrl);

  return (
    <>
      {/* 이미지 그리드 — 남은 공간 전부 */}
      <div style={{ flex: 1, minHeight: 0, padding: '1.5rem 2rem 0', overflow: 'hidden' }}>
        {status === 'loading' && (
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', height: '100%', color: MUTED, fontSize: '1rem' }}>
            로딩 중…
          </div>
        )}
        {status !== 'loading' && items.length === 0 && (
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', height: '100%', color: MUTED, fontSize: '1rem' }}>
            업로드된 이미지가 없습니다.
          </div>
        )}
        {items.length > 0 && (
          <div
            style={{
              display: 'grid',
              gridTemplateColumns: 'repeat(4, 1fr)',
              gridAutoRows: '1fr',
              gap: '1.5rem',
              height: '100%',
            }}
          >
            {items.map(({ label, imageUrl, index }) => (
              <div
                key={index}
                style={{
                  display: 'flex',
                  flexDirection: 'column',
                  alignItems: 'center',
                  gap: '0.65rem',
                  minHeight: 0,
                }}
              >
                {/* 이미지 — 셀 높이에서 이름 영역을 뺀 나머지 차지 */}
                <div
                  style={{
                    flex: 1,
                    minHeight: 0,
                    width: '100%',
                    borderRadius: '1.1rem',
                    overflow: 'hidden',
                    border: `1px solid ${BORDER}`,
                    background: CARD,
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                  }}
                >
                  <img
                    src={imageUrl}
                    alt={label}
                    style={{ width: '100%', height: '100%', objectFit: 'contain' }}
                  />
                </div>

                {/* 이름 */}
                {editingIdx === index ? (
                  <input
                    ref={inputRef}
                    value={editValue}
                    onChange={(e) => setEditValue(e.target.value)}
                    onBlur={commitEdit}
                    onKeyDown={(e) => {
                      if (e.key === 'Enter') commitEdit();
                      if (e.key === 'Escape') setEditingIdx(null);
                    }}
                    style={{
                      width: '100%',
                      padding: '0.45rem 0.65rem',
                      borderRadius: '0.55rem',
                      border: `1.5px solid ${ACCENT}`,
                      background: '#1e293b',
                      color: TEXT,
                      fontSize: '1.45rem',
                      fontWeight: 700,
                      fontFamily: 'inherit',
                      textAlign: 'center',
                      outline: 'none',
                      boxSizing: 'border-box',
                      flexShrink: 0,
                    }}
                    autoFocus
                  />
                ) : (
                  <button
                    type="button"
                    onClick={() => startEdit(index, label)}
                    title="클릭하여 이름 수정"
                    style={{
                      background: 'rgba(255,255,255,0.04)',
                      border: '1px solid transparent',
                      color: TEXT,
                      fontSize: '1.45rem',
                      fontWeight: 700,
                      cursor: 'pointer',
                      textAlign: 'center',
                      fontFamily: 'inherit',
                      padding: '0.3rem 0.65rem',
                      borderRadius: '0.5rem',
                      width: '100%',
                      flexShrink: 0,
                      lineHeight: 1.3,
                    }}
                    onMouseEnter={(e) => {
                      (e.currentTarget as HTMLButtonElement).style.borderColor = BORDER;
                      (e.currentTarget as HTMLButtonElement).style.background = 'rgba(255,255,255,0.07)';
                    }}
