}

/** Supabase 등 객체 에러의 message를 추출해 [object Object] 대신 읽을 수 있는 문자열 반환 */
function formatSaveError(err: unknown): string {
  if (err instanceof Error) return err.message;
  if (err != null && typeof err === 'object' && 'message' in err) {
    const m = (err as { message?: unknown }).message;
    if (typeof m === 'string') return m;
  }
  if (err != null && typeof err === 'object') return JSON.stringify(err);
  return String(err);
}

function formatCenterScheduleLabel(item: CurriculumItem) {
  if (item.month == null || item.week == null) return null;
  return `${item.month}월 · ${item.week}주`;
}

function curriculumTextLines(value: unknown): string[] {
  if (Array.isArray(value)) {
    return value
      .filter((line): line is string => typeof line === 'string')
      .map((line) => line.trim())
      .filter(Boolean);
  }
  if (typeof value === 'string' && value.trim()) return [value.trim()];
  return [];
}

function matchesCenterProgramSearch(item: CurriculumItem, query: string) {
  const title = (item.title ?? '').trim().toLowerCase();
  const idText = String(item.id);
  return title.includes(query) || idText.includes(query);
}

