    }
    // eslint-disable-next-line react-hooks/exhaustive-deps -- when center tab active
  }, [supabase, mainTab]);

  useEffect(() => {
    fetchPersonalItems();
    // eslint-disable-next-line react-hooks/exhaustive-deps -- run when supabase ready
  }, [supabase]);

  // 8회기(기존 1회기~8회기 + 링크2개) -> 16개(1-1~8-2) 자동 생성 (기존 데이터는 보존)
  useEffect(() => {
    const migrate8huiToRoutine16 = async () => {
      if (!supabase) return;
      try {
        const { data: authData, error: authError } = await supabase.auth.getUser();
        if (authError || !authData.user) return;
        const { data: me, error: meError } = await supabase
          .from('users')
          .select('role, is_admin')
          .eq('id', authData.user.id)
          .maybeSingle();
        if (meError || !me) return;
        const role = String((me as { role?: unknown }).role ?? '');
        const dbAdmin = (me as { is_admin?: unknown }).is_admin === true || role === 'admin' || role === 'master';
        if (!dbAdmin) return;

        const { data: existing16, error: e16 } = await supabase
          .from('personal_curriculum')
          .select('id, sub_tab')
          .eq('category', '신체 기능향상 8회기')
          .in('sub_tab', EIGHTH_SESSION_LABELS as unknown as string[]);
        if (e16) throw e16;
        if ((existing16 ?? []).length >= 16) return;

        const legacyLabels = ['1회기', '2회기', '3회기', '4회기', '5회기', '6회기', '7회기', '8회기'];
        const { data: legacy, error: eLegacy } = await supabase
          .from('personal_curriculum')
          .select('*')
          .eq('category', '신체 기능향상 8회기')
          .in('sub_tab', legacyLabels);
        if (eLegacy) throw eLegacy;

        const toInsert: Array<Record<string, unknown>> = [];

        for (const legacyRow of legacy ?? []) {
          const legacySub = String((legacyRow as { sub_tab?: unknown }).sub_tab ?? '');
          const sessionNum = legacyLabels.indexOf(legacySub) + 1;
          if (sessionNum <= 0) continue;

          const url1 = String((legacyRow as { url?: unknown }).url ?? '') || null;
          const detail1 = String((legacyRow as { detail_text?: unknown }).detail_text ?? '') || null;

          const url2 = String((legacyRow as { link_2?: unknown }).link_2 ?? '') || null;
          const detail2 = String((legacyRow as { detail_text_2?: unknown }).detail_text_2 ?? '') || null;

          const type1 = (legacyRow as { type?: unknown }).type;
          const typeValue = typeof type1 === 'string' && type1 ? type1 : 'youtube';

          toInsert.push({
            category: '신체 기능향상 8회기',
            sub_tab: `${sessionNum}-1`,
            title: `${sessionNum}-1`,
            url: url1,
            type: typeValue,
            thumbnail: (legacyRow as { thumbnail?: unknown }).thumbnail ?? null,
            expert_tip: detail1 || null,
            check_list: [],
            equipment: [],
            steps: [],
          });
          toInsert.push({
            category: '신체 기능향상 8회기',
            sub_tab: `${sessionNum}-2`,
            title: `${sessionNum}-2`,
            url: url2,
            type: typeValue,
            thumbnail: null,
            expert_tip: detail2 || null,
            check_list: [],
            equipment: [],
            steps: [],
          });
        }

        // legacy가 없더라도 16개는 만들어 두기(빈 항목)
        if (toInsert.length === 0) {
          for (const label of EIGHTH_SESSION_LABELS as unknown as string[]) {
            toInsert.push({
              category: '신체 기능향상 8회기',
              sub_tab: label,
              title: label,
              url: null,
              type: 'youtube',
              thumbnail: null,
              expert_tip: null,
              check_list: [],
              equipment: [],
              steps: [],
            });
          }
        }

        // 이미 존재하는 sub_tab은 제외
        const existingSet = new Set((existing16 ?? []).map((r: { sub_tab?: string }) => r.sub_tab));
        const uniqueInsert = toInsert.filter((r) => !existingSet.has(String(r.sub_tab)));
        if (uniqueInsert.length === 0) return;

        const { error: eIns } = await supabase.from('personal_curriculum').insert(uniqueInsert);
        if (eIns) throw eIns;

        await fetchPersonalItems();
      } catch (err) {
        const row = err && typeof err === 'object' ? (err as { message?: unknown; code?: unknown; details?: unknown }) : null;
        const code = String(row?.code ?? '');
        const message = String(row?.message ?? '');
        if (code === '42501' || /row-level security/i.test(message)) return;
        devLogger.error('8hui migrate failed:', [code, message, row?.details].filter(Boolean).join(' ') || err);
      }
    };
    void migrate8huiToRoutine16();
    // eslint-disable-next-line react-hooks/exhaustive-deps -- migrate once when supabase ready
  }, [supabase]);

  const filteredItems = useMemo(() => {
    const query = centerProgramSearch.trim().toLowerCase();
    let base: CurriculumItem[];
    if (centerIsSub) {
      base = items.filter((item) => item.is_sub === true);
    } else if (query) {
      base = items.filter((item) => !item.is_sub);
    } else {
      base = items.filter((item) => !item.is_sub && item.month === selectedMonth && item.week === selectedWeek);
    }
    const sorted = sortCenterCurriculumByDisplayOrder(base);
    let result = sorted;
    if (equipmentTagFilter !== null) {
      result = result.filter((item) =>
        Array.isArray(item.equipment_tag_numbers) && item.equipment_tag_numbers.includes(equipmentTagFilter),
      );
    }
    if (query) {
      result = result.filter((item) => matchesCenterProgramSearch(item, query));
    }
    return result;
  }, [items, selectedMonth, selectedWeek, centerIsSub, equipmentTagFilter, centerProgramSearch]);

  const centerProgramSearchActive = centerProgramSearch.trim().length > 0;

  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 8 } }),
    useSensor(TouchSensor, { activationConstraint: { delay: 200, tolerance: 5 } }),
  );

  const handleCenterCurriculumDragEnd = async (event: DragEndEvent) => {
    if (centerProgramSearchActive) return;
    const { active, over } = event;
    if (!over || active.id === over.id || !supabase) return;
    const activeId = Number(active.id);
    const overId = Number(over.id);
    // 드래그 가능한 전체 목록(필터 미적용)에서 순서 계산
    const draggableItems = sortCenterCurriculumByDisplayOrder(
      centerIsSub ? items.filter((i) => i.is_sub === true) : items.filter((i) => !i.is_sub && i.month === selectedMonth && i.week === selectedWeek),
    );
    const oldIndex = draggableItems.findIndex((i) => i.id === activeId);
    const newIndex = draggableItems.findIndex((i) => i.id === overId);
    if (oldIndex < 0 || newIndex < 0) return;
    const reordered = arrayMove(draggableItems, oldIndex, newIndex);
    setItems((prev) => {
      const orderMap = new Map(reordered.map((it, idx) => [it.id, idx]));
      return prev.map((it) => (orderMap.has(it.id) ? { ...it, display_order: orderMap.get(it.id)! } : it));
    });
    try {
      const response = await fetch('/api/admin/curriculum', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          reorder: reordered.map((it, index) => ({ id: it.id, display_order: index })),
        }),
      });
      const result = await response.json().catch(() => null) as { ok?: boolean; error?: string } | null;
      if (!response.ok || !result?.ok) {
        throw new Error(result?.error ?? '순서 저장 API 실패');
      }
      toast.success('순서가 저장되었습니다.');
    } catch (err: unknown) {
      toast.error('순서 저장 실패: ' + formatSaveError(err));
      await fetchItems();
    }
  };

  const filteredPersonalItems = useMemo(() => {
    return personalItems.filter((p: PersonalCurriculumItem) => p.category === categoryTab && p.sub_tab === subTab);
  }, [personalItems, categoryTab, subTab]);

  /** 신체 기능향상 8회기: 1~8회기 슬롯별 아이템 */
  const eighthSessionSlots = useMemo(() => {
    return EIGHTH_SESSION_LABELS.map((label) => {
      const item = personalItems.find((p: PersonalCurriculumItem) => p.category === '신체 기능향상 8회기' && p.sub_tab === label) ?? null;
      return { label, item };
    });
  }, [personalItems]);

  const yuaFixedSessionSlots = useMemo(() => {
    const labels = getSubTabsForCategory(YUA_CATEGORY);
    return buildYuaFixedSessionSlots(personalItems, labels);
  }, [personalItems]);

  const yuaLibraryItems = useMemo(() => getYuaLibraryItems(personalItems), [personalItems]);

  const currentEquipment = useMemo(() => {
    return centerEquipmentList.find((e) => e.number === selectedEquipmentNumber) ?? null;
  }, [centerEquipmentList, selectedEquipmentNumber]);

  /** 가이드라인 1~12번 칩에 표시할 교구명 (DB 미입력 시 N번 교구) */
  const equipmentGuideChipLabelByNumber = useMemo(() => {
    const map = new Map<number, string>();
    for (const num of EQUIPMENT_GUIDE_NUMBERS) {
      const row = centerEquipmentList.find((e) => e.number === num);
      const trimmed = String(row?.name ?? '').trim();
      map.set(num, trimmed.length > 0 ? trimmed : `${num}번 교구`);
    }
    return map;
  }, [centerEquipmentList]);

  const selectedEquipmentDisplayName = equipmentGuideChipLabelByNumber.get(selectedEquipmentNumber) ?? `${selectedEquipmentNumber}번 교구`;

  const filteredEquipmentItems = useMemo(() => {
    return equipmentGuideItems.filter((i) => i.number === selectedEquipmentNumber && i.step === selectedEquipmentStep);
  }, [equipmentGuideItems, selectedEquipmentNumber, selectedEquipmentStep]);

  const currentTheme = MONTHLY_THEMES[selectedMonth] || { 
    title: `${selectedMonth}월 집중 교육 목표`, 
    desc: '스포키듀와 함께 건강한 에너지를 발산해보세요!' 
  };

  const hasValidUrl = (url?: string) => {
    const u = url?.trim();
    if (!u || u === '#' || u === 'null' || u === 'undefined' || u.toLowerCase() === 'none') return false;
    return u.startsWith('http://') || u.startsWith('https://');
  };

  const getVideoLinks = (item: { url?: string; link2?: string; link3?: string; link4?: string }) =>
    [item.url, item.link2, item.link3, item.link4].filter((u): u is string => hasValidUrl(u));

  useEffect(() => {
    if (!isDetailModalOpen) return;
    setActiveVideoIndex(0);
  }, [isDetailModalOpen, selectedItem]);

  const getSafeThumbnailUrl = (item: { url?: string; thumbnail?: string }) => {
    const id = getYouTubeId(item.url ?? '');
    if (id) return `https://img.youtube.com/vi/${id}/hqdefault.jpg`;
    if (item.thumbnail?.includes('img.youtube.com')) {
      if (item.thumbnail.includes('vi/null')) return '';
      return item.thumbnail.replace('maxresdefault', 'hqdefault');
    }
    return item.thumbnail ?? '';
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!supabase) return;
    const videoId = getYouTubeId(newPost.url);
    const isInsta = newPost.url.includes('instagram.com');
    const type = isInsta ? 'instagram' : 'youtube';
    
    const equipment = splitTextareaLines(newPost.equipmentText);
    const steps = splitTextareaLines(newPost.stepsText);

    const isSub = postIsSub;
    const postDataBase = {
      title: newPost.title, 
      url: newPost.url, 
      month: isSub ? 1 : newPost.month,
      week: isSub ? 1 : newPost.week,
      equipment: equipment, 
      steps: steps, 
      type,
      thumbnail: isInsta ? '' : (videoId ? `https://img.youtube.com/vi/${videoId}/hqdefault.jpg` : ''),
      is_sub: isSub,
      equipment_tag_numbers: isSub ? (newPostEquipmentTags.length > 0 ? newPostEquipmentTags : null) : null,
    };
    
    try {
      let savedCurriculumId = editingId;
      if (editingId) {
        const response = await fetch('/api/admin/curriculum', {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ id: editingId, ...postDataBase }),
        });
        const result = await response.json().catch(() => null) as { ok?: boolean; error?: string } | null;
        if (!response.ok || !result?.ok) {
          throw new Error(result?.error ?? '커리큘럼 수정 API 실패');
        }
      } else {
        const sameGroup = isSub
          ? items.filter((i) => i.is_sub === true)
          : items.filter((i) => !i.is_sub && i.month === newPost.month && i.week === newPost.week);
        let nextOrder = 0;
        for (const i of sameGroup) {
          const o = typeof i.display_order === 'number' ? i.display_order : -1;
          if (o >= nextOrder) nextOrder = o + 1;
        }
        const response = await fetch('/api/admin/curriculum', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ ...postDataBase, display_order: nextOrder }),
        });
        const result = await response.json().catch(() => null) as { ok?: boolean; id?: number; error?: string } | null;
        if (!response.ok || !result?.ok || typeof result.id !== 'number') {
          throw new Error(result?.error ?? '커리큘럼 등록 API 실패');
        }
        savedCurriculumId = result.id;
      }

      if (!savedCurriculumId) throw new Error('저장된 커리큘럼 ID를 확인하지 못했습니다.');

      const metaTags = [
        ...mergeStrengthBodyFunctions(newPost.bodyFunctions).map((value) => taggedValue('신체 기능:', value)),
        ...newPost.movements.map((value) => taggedValue('움직임:', value)),
      ];
      const nextTags = setMasterParticipantFormatTag(metaTags, newPost.participantFormat);
      const metaPatch: Record<string, unknown> = {};
      const normalizedTheme = normalizeLessonTheme(newPost.theme);
      if (normalizedTheme) metaPatch.sm_theme = normalizedTheme;
      const serializedTarget = serializeMasterTags(parseMasterTargets(newPost.target));
      if (serializedTarget) metaPatch.sm_grade = serializedTarget;
      if (nextTags.length > 0) metaPatch.sm_tags = nextTags;
      const serializedSpace = serializeMasterTags(parseMasterSpaces(newPost.space));
      if (serializedSpace) metaPatch.sm_space = serializedSpace;
      if (newPost.coachScript.trim()) metaPatch.sm_coach_script = newPost.coachScript;
      if (newPost.briefingNotes.trim()) metaPatch.sm_briefing_notes = newPost.briefingNotes;
      if (newPost.variations.trim()) metaPatch.sm_variation_method = newPost.variations;
      const metaOverlayResponse = await fetch(`/api/admin/spokedu-master/programs?id=${savedCurriculumId}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          meta: metaPatch,
          overlay: {
            title: newPost.title,
            video_url: newPost.url,
            equipment: newPost.equipmentText,
            activity_method: newPost.stepsText,
            is_published: true,
          },
        }),
      });
      const metaOverlayResult = await metaOverlayResponse.json().catch(() => null) as { ok?: boolean; failedStage?: string } | null;
      if (!metaOverlayResponse.ok || metaOverlayResult?.ok !== true) {
        const stage = metaOverlayResult?.failedStage === 'overlay' ? '구독 기본 콘텐츠' : '구독 메타';
        toast.error(`기본 내용은 저장되었으나 ${stage} 저장에 실패했습니다. 입력값을 유지한 채 다시 시도해 주세요.`);
        return;
      }
      toast.success(editingId ? '수정되었습니다.' : '등록되었습니다.');

      await fetchItems();

      // fetchItems가 meta를 못 읽는 경우(RLS 등)를 대비해 저장한 값을 items에 직접 반영
      setItems(prev => prev.map(item => {
        if (item.id !== savedCurriculumId) return item;
        return {
          ...item,
          smTheme: normalizeLessonTheme(newPost.theme) || '',
          smGrade: serializeMasterTags(parseMasterTargets(newPost.target)),
          smTags: nextTags,
          smSpace: serializeMasterTags(parseMasterSpaces(newPost.space)),
          participantFormat: newPost.participantFormat,
          coachScript: newPost.coachScript,
          briefingNotes: newPost.briefingNotes,
          variations: newPost.variations,
        };
      }));

      if (!editingId) {
        const hadOverlay = !!(window.history.state as Record<string, unknown>)?.[CURRICULUM_ADMIN_HISTORY_KEY];
        if (hadOverlay) {
          popOverlayHistoryIfPresent(CURRICULUM_ADMIN_HISTORY_KEY);
        } else {
          closeInputModal();
        }
      }
    } catch (err: unknown) {
      toast.error('저장 중 오류 발생: ' + formatSaveError(err));
