    (async () => {
      const [lpRes, fbRes, lessonSess, photoByline, feedbackSess] = await Promise.all([
        row.lesson_plan_session_id ? supabase.from('lesson_plans').select('content').eq('session_id', row.lesson_plan_session_id).maybeSingle() : Promise.resolve({ data: null }),
        row.feedback_session_id ? supabase.from('sessions').select('feedback_fields, students_text, file_url, session_type').eq('id', row.feedback_session_id).maybeSingle() : Promise.resolve({ data: null }),
        row.lesson_plan_session_id ? supabase.from('sessions').select(SESSION_CREDIT_SELECT).eq('id', row.lesson_plan_session_id).maybeSingle() : Promise.resolve({ data: null }),
        fetchWeeklyBestPhotoByline(supabase, {
          photoSessionId: row.photo_session_id,
          photoUrls: row.photo_urls,
        }),
        row.feedback_session_id ? supabase.from('sessions').select(SESSION_CREDIT_SELECT).eq('id', row.feedback_session_id).maybeSingle() : Promise.resolve({ data: null }),
      ]);
      setDetailLesson(lpRes.data?.content ?? null);
      setDetailLessonByline(formatWeeklyBestBylineFromSession(lessonSess.data) || null);
      setDetailPhotoByline(photoByline);
      setDetailFeedback(
        formatWeeklyBestFeedbackText(row.feedback_note, fbRes.data as WbFeedbackSession | null),
      );
      setDetailFeedbackByline(formatWeeklyBestBylineFromSession(feedbackSess.data) || null);
    })();
  }, [supabase, isExpanded, row.id, row.lesson_plan_session_id, row.photo_session_id, row.photo_urls, row.feedback_session_id, row.feedback_note]);

  return (
    <WeeklyBestCard
      row={row}
      onDelete={onDelete}
      onEdit={onEdit}
      detailLesson={detailLesson}
      detailLessonByline={detailLessonByline}
      detailPhotoByline={detailPhotoByline}
      detailFeedback={detailFeedback}
      detailFeedbackByline={detailFeedbackByline}
      isExpanded={isExpanded}
      onToggle={() => setIsExpanded((v) => !v)}
    />
  );
}

export default function NoticePage() {
  const [supabase] = useState(() => (typeof window !== 'undefined' ? getSupabaseBrowserClient() : null));
  const [mainTab, setMainTab] = useState<MainTab>('notice');
  const [showWriteChoiceModal, setShowWriteChoiceModal] = useState(false);
  const [notices, setNotices] = useState<Notice[]>([]);
  const [weeklyBestList, setWeeklyBestList] = useState<WeeklyBest[]>([]);
  const [weeklyBestLoading, setWeeklyBestLoading] = useState(false);
  const [loading, setLoading] = useState(true);
  const [expandedId, setExpandedId] = useState<number | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<number | null>(null);
  const [activeTab, setActiveTab] = useState('ALL');

  const [form, setForm] = useState({
    title: '', content: '', category: 'general', is_pinned: false
  });
  const [uploadingImages, setUploadingImages] = useState(false);
  const editorRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [showWeeklyBestWizard, setShowWeeklyBestWizard] = useState(false);
  const [editingWeeklyBestId, setEditingWeeklyBestId] = useState<string | null>(null);
  const [wizardStep, setWizardStep] = useState(1);
  const [wizardOpenDate, setWizardOpenDate] = useState<Date>(() => new Date());
  const [wbForm, setWbForm] = useState<{
    title: string;
    content: string;
    lesson_plan_session_id: string;
    photo_urls: string[];
    photo_session_id: string;
    feedback_session_id: string;
    feedback_note: string;
  }>({
    title: '',
    content: '',
    lesson_plan_session_id: '',
    photo_urls: [],
    photo_session_id: '',
    feedback_session_id: '',
    feedback_note: '',
  });
  const [wbFeedbackScope, setWbFeedbackScope] = useState<WbFeedbackScope>('private');
  const [coaches, setCoaches] = useState<{ id: string; name: string }[]>([]);
  const [wbCoachFilter, setWbCoachFilter] = useState('all');
  const [lessonSessions, setLessonSessions] = useState<WbLessonSession[]>([]);
  const [photoSessions, setPhotoSessions] = useState<WbPhotoSession[]>([]);
  const [feedbackSessions, setFeedbackSessions] = useState<WbFeedbackSession[]>([]);
  const [wbStepLoading, setWbStepLoading] = useState(false);
  const [wbSaving, setWbSaving] = useState(false);
  const wbPhotoInputRef = useRef<HTMLInputElement>(null);

  const fetchNotices = useCallback(async () => {
    if (!supabase) return;
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from('notices')
        .select('*')
        .order('is_pinned', { ascending: false })
        .order('created_at', { ascending: false });
      if (error) throw error;
      if (data) setNotices(data as Notice[]);
    } catch (err) {
      devLogger.error('[notice] fetch notices error:', err);
      toast.error(err instanceof Error ? err.message : '공지 목록을 불러오지 못했습니다.');
    } finally {
      setLoading(false);
    }
  }, [supabase]);

  const fetchWeeklyBest = useCallback(async () => {
    if (!supabase) return;
    setWeeklyBestLoading(true);
    try {
      const { data, error } = await supabase
        .from('weekly_best')
        .select('*')
        .order('created_at', { ascending: false });
      if (error) throw error;
      if (data) setWeeklyBestList(data as WeeklyBest[]);
    } catch (err) {
      devLogger.error('[notice] fetch weekly best error:', err);
      toast.error(err instanceof Error ? err.message : '주간베스트 목록을 불러오지 못했습니다.');
    } finally {
      setWeeklyBestLoading(false);
    }
  }, [supabase]);

  const refreshAll = useCallback(() => {
    fetchNotices();
    fetchWeeklyBest();
  }, [fetchNotices, fetchWeeklyBest]);

  const unifiedList = useMemo(() => {
    const a = notices.map((n) => ({ type: 'notice' as const, id: String(n.id), created_at: n.created_at, data: n }));
    const b = weeklyBestList.map((w) => ({ type: 'weekly_best' as const, id: w.id, created_at: w.created_at, data: w }));
    return [...a, ...b].sort((x, y) => new Date(y.created_at).getTime() - new Date(x.created_at).getTime());
  }, [notices, weeklyBestList]);

  useEffect(() => { fetchNotices(); }, [fetchNotices]);
  useEffect(() => { fetchWeeklyBest(); }, [fetchWeeklyBest]);

  useEffect(() => {
    if (!isModalOpen || !editorRef.current) return;
    let html = form.content || '';
    if (!html.includes('<')) {
      html = html.replace(/\n/g, '<br>');
    }
    editorRef.current.innerHTML = html;
    wrapImagesWithDeleteButton(editorRef.current);
  }, [isModalOpen, form.content]);

  const getWeeklyBestDateRange = useCallback(() => {
    const start = new Date(wizardOpenDate);
    start.setDate(start.getDate() - 7);
    start.setHours(0, 0, 0, 0);
    const end = new Date(wizardOpenDate);
    end.setDate(end.getDate() - 1);
    end.setHours(23, 59, 59, 999);
    return { start, end };
  }, [wizardOpenDate]);

  const wbDateRangeLabel = useMemo(() => {
    const { start, end } = getWeeklyBestDateRange();
    return `${start.toLocaleDateString('ko-KR')} ~ ${end.toLocaleDateString('ko-KR')}`;
  }, [getWeeklyBestDateRange]);

  const fetchLessonCandidates = useCallback(async () => {
    if (!supabase) return;
    setWbStepLoading(true);
    try {
      const { start, end } = getWeeklyBestDateRange();
      let q = supabase
        .from('sessions')
        .select('id, title, start_at, created_by, lesson_plans(content), users:created_by(id, name)')
        .gte('start_at', start.toISOString())
        .lte('start_at', end.toISOString())
        .order('start_at', { ascending: false });
      if (wbCoachFilter !== 'all') q = q.eq('created_by', wbCoachFilter);
      const { data, error } = await q;
      if (error) throw error;
      const withPlan = ((data ?? []) as { lesson_plans?: { content?: string }[] | { content?: string } }[]).filter((s) => {
        const lp = s.lesson_plans;
        const content = Array.isArray(lp) ? lp[0]?.content : (lp as { content?: string } | null)?.content;
        return !!content;
      });
      setLessonSessions(withPlan as WbLessonSession[]);
    } catch (err) {
      devLogger.error('[notice] fetch lesson candidates error:', err);
      toast.error(err instanceof Error ? err.message : '수업안 후보를 불러오지 못했습니다.');
    } finally {
      setWbStepLoading(false);
    }
  }, [supabase, getWeeklyBestDateRange, wbCoachFilter]);

  const fetchFeedbackCandidates = useCallback(async () => {
    if (!supabase) return;
    setWbStepLoading(true);
    try {
      const { start, end } = getWeeklyBestDateRange();
      let q = supabase
        .from('sessions')
        .select('id, title, start_at, created_by, feedback_fields, students_text, file_url, session_type, users:created_by(id, name)')
        .gte('start_at', start.toISOString())
        .lte('start_at', end.toISOString())
        .order('start_at', { ascending: false });
      if (wbCoachFilter !== 'all') q = q.eq('created_by', wbCoachFilter);
      if (wbFeedbackScope === 'center') {
        q = q.in('session_type', [...CENTER_SESSION_TYPE_VALUES]);
      } else {
        q = q.in('session_type', [...PRIVATE_TUTORING_SESSION_TYPE_VALUES]);
      }
      const { data, error } = await q;
      if (error) throw error;
      const rows = (data ?? []) as WbFeedbackSession[];
      const withFeedback = rows.filter((s) => {
        if (wbFeedbackScope === 'center') return true;
        const fields = s.feedback_fields ?? parseTemplateToFields(s.students_text || '');
        return isFieldValid(fields.main_activity) || isFieldValid(fields.strengths) || isFieldValid(fields.next_goals);
      });
      setFeedbackSessions(withFeedback);
    } catch (err) {
      devLogger.error('[notice] fetch feedback candidates error:', err);
      toast.error(err instanceof Error ? err.message : '피드백 후보를 불러오지 못했습니다.');
    } finally {
      setWbStepLoading(false);
    }
  }, [supabase, getWeeklyBestDateRange, wbCoachFilter, wbFeedbackScope]);

  const fetchPhotoCandidates = useCallback(async () => {
    if (!supabase) return;
    setWbStepLoading(true);
    try {
      const { start, end } = getWeeklyBestDateRange();
      let q = supabase
        .from('sessions')
        .select('id, title, start_at, created_by, photo_url, users:created_by(id, name)')
        .gte('start_at', start.toISOString())
        .lte('start_at', end.toISOString())
        .order('start_at', { ascending: false });
      if (wbCoachFilter !== 'all') q = q.eq('created_by', wbCoachFilter);
      const { data, error } = await q;
      if (error) throw error;
      setPhotoSessions((data ?? []) as WbPhotoSession[]);
    } catch (err) {
      devLogger.error('[notice] fetch photo candidates error:', err);
      toast.error(err instanceof Error ? err.message : '포토 후보를 불러오지 못했습니다.');
    } finally {
      setWbStepLoading(false);
    }
  }, [supabase, getWeeklyBestDateRange, wbCoachFilter]);

  useEffect(() => {
    if (showWeeklyBestWizard && wizardStep === 1 && coaches.length === 0 && supabase) {
      supabase
        .from('users')
        .select('id, name')
        .eq('is_active', true)
        .order('name')
        .then(({ data, error }: { data: { id: string; name: string }[] | null; error: { message: string } | null }) => {
          if (error) throw error;
          if (data) setCoaches(data);
        })
        .catch((err: unknown) => {
          devLogger.error('[notice] fetch coaches error:', err);
          toast.error(err instanceof Error ? err.message : '강사 목록을 불러오지 못했습니다.');
        });
    }
  }, [showWeeklyBestWizard, wizardStep, coaches.length, supabase]);

  useEffect(() => {
    if (showWeeklyBestWizard && wizardStep === 2) fetchLessonCandidates();
  }, [showWeeklyBestWizard, wizardStep, fetchLessonCandidates]);

  useEffect(() => {
    if (showWeeklyBestWizard && wizardStep === 3) fetchPhotoCandidates();
  }, [showWeeklyBestWizard, wizardStep, fetchPhotoCandidates]);

  useEffect(() => {
    if (showWeeklyBestWizard && wizardStep === 4) fetchFeedbackCandidates();
  }, [showWeeklyBestWizard, wizardStep, fetchFeedbackCandidates]);

  const showCenterFeedbackNoteInput = wbFeedbackScope === 'center';

  const openNoticeForm = () => {
    setShowWriteChoiceModal(false);
    setEditingId(null);
    setForm({ title: '', content: '', category: 'general', is_pinned: false });
    setIsModalOpen(true);
  };

  const openWeeklyBestWizard = () => {
    setShowWriteChoiceModal(false);
    setEditingWeeklyBestId(null);
    setWizardOpenDate(new Date());
    setWizardStep(1);
    setWbFeedbackScope('private');
    setWbForm({
      title: '',
      content: '',
      lesson_plan_session_id: '',
      photo_urls: [],
      photo_session_id: '',
      feedback_session_id: '',
      feedback_note: '',
    });
    setShowWeeklyBestWizard(true);
  };

  const openWeeklyBestEdit = async (row: WeeklyBest) => {
    setShowWriteChoiceModal(false);
    let anchor = new Date();
    let feedbackScope: WbFeedbackScope = 'private';
    if (supabase) {
      const sid = row.lesson_plan_session_id || row.feedback_session_id;
      if (sid) {
        const { data } = await supabase.from('sessions').select('start_at, session_type').eq('id', sid).maybeSingle();
        if (data?.start_at) {
          const d = new Date(data.start_at);
          anchor = new Date(d.getFullYear(), d.getMonth(), d.getDate());
          anchor.setDate(anchor.getDate() + 1);
        } else {
          const c = new Date(row.created_at);
          anchor = new Date(c.getFullYear(), c.getMonth(), c.getDate());
        }
      } else {
        const c = new Date(row.created_at);
        anchor = new Date(c.getFullYear(), c.getMonth(), c.getDate());
      }
      if (row.feedback_session_id) {
        const { data: fbSession } = await supabase
          .from('sessions')
          .select('session_type')
          .eq('id', row.feedback_session_id)
          .maybeSingle();
        if (fbSession && isCenterSessionType(fbSession.session_type)) {
          feedbackScope = 'center';
        }
      }
    }
    setWizardOpenDate(anchor);
    setEditingWeeklyBestId(row.id);
    setWizardStep(1);
    setWbFeedbackScope(feedbackScope);
    setWbForm({
      title: row.title,
      content: row.content ?? '',
      lesson_plan_session_id: row.lesson_plan_session_id ?? '',
      photo_urls: [...(row.photo_urls ?? [])],
      photo_session_id: row.photo_session_id ?? '',
      feedback_session_id: row.feedback_session_id ?? '',
      feedback_note: row.feedback_note ?? '',
    });
    setWbCoachFilter('all');
    setShowWeeklyBestWizard(true);
  };

  const handleWbPhotoUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files ?? []);
    if (files.length === 0) return;
    const urls: string[] = [];
    try {
      for (let i = 0; i < files.length; i++) {
        const file = files[i];
        const safeName = (file.name || 'image')
          .normalize('NFD')
          .replace(/[\u0300-\u036f]/g, '')
          .replace(/[^a-zA-Z0-9_.-]/g, '_') || 'image';
        const baseName = safeName.replace(/\.[^/.]+$/, '') || 'image';

        // 원본이 커도 업로드 되도록 WebP 변환 + 리사이즈(비율 유지)
        const webp = await optimizeToWebP(file, { maxW: 1920, maxH: 1920, quality: 0.9 });
        const path = `weekly_best/${Date.now()}_${i}_${Math.random().toString(36).slice(2, 10)}_${baseName}.webp`;
        await uploadToStorageSigned(path, webp, 'image/webp');
        urls.push(getPublicUrl(path));
      }
      setWbForm((prev) => ({ ...prev, photo_urls: [...prev.photo_urls, ...urls] }));
    } catch (err) {
      devLogger.error('[weekly_best photo upload]', err);
      const msg = err instanceof Error ? err.message : '이미지 업로드 실패';
      toast.error(msg);
    } finally {
      e.target.value = '';
    }
  };

  const saveWeeklyBest = async () => {
    if (!supabase || !wbForm.title.trim()) {
      toast.error('제목을 입력해주세요.');
      return;
    }
    if (wbForm.photo_urls.length > 0 && !wbForm.photo_session_id) {
      toast.error('사진 강사(수업)를 선택해 주세요. 그래야 이름이 표시됩니다.');
      return;
    }
    if (wbFeedbackScope === 'center') {
      if (!wbForm.feedback_session_id) {
        toast.error('센터 수업을 선택해주세요.');
        return;
      }
      if (!wbForm.feedback_note.trim()) {
        toast.error('센터 피드백 내용을 입력해주세요.');
        return;
      }
    }
    setWbSaving(true);
    try {
      const payload = {
        title: wbForm.title,
        content: wbForm.content || null,
        lesson_plan_session_id: wbForm.lesson_plan_session_id || null,
        photo_urls: wbForm.photo_urls,
        photo_session_id: wbForm.photo_session_id || null,
        feedback_session_id: wbForm.feedback_session_id || null,
        feedback_note:
          wbFeedbackScope === 'center' && wbForm.feedback_note.trim()
            ? wbForm.feedback_note.trim()
            : null,
      };
      const res = await fetch('/api/admin/weekly-best', {
        method: editingWeeklyBestId ? 'PATCH' : 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(editingWeeklyBestId ? { id: editingWeeklyBestId, ...payload } : payload),
        credentials: 'same-origin',
      });
      if (!res.ok) {
        const body = (await res.json().catch(() => ({}))) as { error?: string };
        toast.error('저장 실패: ' + (body.error ?? res.statusText));
        return;
      }
      toast.success(editingWeeklyBestId ? '주간베스트가 수정되었습니다.' : '주간베스트가 등록되었습니다.');
      setShowWeeklyBestWizard(false);
      setEditingWeeklyBestId(null);
      fetchWeeklyBest();
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : (err && typeof err === 'object' && 'message' in err ? String((err as { message: unknown }).message) : '알 수 없는 오류');
      toast.error('저장 실패: ' + msg);
    } finally {
      setWbSaving(false);
    }
  };

  const uploadImages = async (files: File[]): Promise<string[]> => {
    if (files.length === 0) return [];
    setUploadingImages(true);
    const urls: string[] = [];
    try {
      for (let i = 0; i < files.length; i++) {
        const file = files[i];
        const safeName = (file.name || 'image')
          .normalize('NFD')
          .replace(/[\u0300-\u036f]/g, '')
          .replace(/[^a-zA-Z0-9_.-]/g, '_') || 'image';
        const baseName = safeName.replace(/\.[^/.]+$/, '') || 'image';

        // 공지 인라인 이미지도 원본 용량에 상관없이 올라가도록 WebP로 변환/리사이즈
        const webp = await optimizeToWebP(file, { maxW: 1920, maxH: 1920, quality: 0.9 });
        const path = `notices/${Date.now()}_${i}_${baseName}.webp`;
        await uploadToStorageSigned(path, webp, 'image/webp');
        urls.push(getPublicUrl(path));
      }
    } catch (err) {
      devLogger.error('이미지 업로드 오류:', err);
      const msg = err instanceof Error ? err.message : '이미지 업로드에 실패했습니다.';
      toast.error(msg);
    } finally {
      setUploadingImages(false);
    }
    return urls;
  };

  const insertImageAtCursor = (urls: string[]) => {
    const el = editorRef.current;
    if (!el) return;
    const placeholder = el.querySelector('[data-image-placeholder]');
    if (!placeholder) return;
    const fragment = document.createDocumentFragment();
    urls.forEach((url, i) => {
      const img = document.createElement('img');
      img.src = url;
      img.alt = '';
      img.className = 'max-w-full h-auto rounded-lg my-2 block';
      fragment.appendChild(img);
      if (i < urls.length - 1) fragment.appendChild(document.createElement('br'));
    });
    placeholder.replaceWith(fragment);
    wrapImagesWithDeleteButton(el);
  };

  const handleImageSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files ?? []);
    if (files.length === 0) return;
    const urls = await uploadImages(files);
    if (urls.length > 0) insertImageAtCursor(urls);
    e.target.value = '';
  };

  const triggerInsertImage = () => {
    const el = editorRef.current;
    if (!el) return;
    el.focus();
    const sel = window.getSelection();
    let range: Range | null = null;
    if (sel && sel.rangeCount > 0) {
      const r = sel.getRangeAt(0);
      if (el.contains(r.commonAncestorContainer)) range = r;
    }
    if (!range) {
      range = document.createRange();
      range.selectNodeContents(el);
      range.collapse(false);
      sel?.removeAllRanges();
      sel?.addRange(range);
    }
    const placeholder = document.createElement('span');
    placeholder.setAttribute('data-image-placeholder', 'true');
    placeholder.textContent = '\u200b';
    range.insertNode(placeholder);
    range.setStartAfter(placeholder);
    range.setEndAfter(placeholder);
    sel?.removeAllRanges();
    sel?.addRange(range);
    fileInputRef.current?.click();
  };

  const handleSave = async () => {
    const el = editorRef.current;
    const contentHtml = el ? getContentWithoutWrappers(el) : form.content;
    const textOnly = (el?.innerText ?? form.content).trim();
    if (!supabase || !form.title.trim() || !textOnly) return toast.error('제목과 내용을 입력해주세요.');

    try {
      const payload = {
        title: form.title,
        content: contentHtml,
        category: form.category,
        is_pinned: form.is_pinned,
        image_urls: null,
        inline_images: null,
      };
      if (editingId) {
        const res = await fetch('/api/admin/notices', {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ id: editingId, ...payload }),
          credentials: 'same-origin',
        });
        if (!res.ok) {
          const body = (await res.json().catch(() => ({}))) as { error?: string };
          throw new Error(body.error ?? res.statusText);
        }
        toast.success('수정되었습니다.');
      } else {
        const res = await fetch('/api/admin/notices', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload),
          credentials: 'same-origin',
        });
        if (!res.ok) {
          const body = (await res.json().catch(() => ({}))) as { error?: string };
          throw new Error(body.error ?? res.statusText);
        }
        toast.success('등록되었습니다.');
      }

      setIsModalOpen(false);
      setEditingId(null);
      setForm({ title: '', content: '', category: 'general', is_pinned: false });
      fetchNotices();
    } catch (e: unknown) {
      const msg = e instanceof Error ? e.message : String(e);
      toast.error('저장 실패: ' + msg);
    }
