                    items={photoSessions}
                    selectedId={wbForm.photo_session_id}
                    onSelect={(id) => {
                      const s = photoSessions.find((row) => row.id === id);
                      const photos = s ? normalizeSessionPhotoUrls(s.photo_url) : [];
                      setWbForm((p) => ({
                        ...p,
                        photo_session_id: id,
                        photo_urls: photos.length > 0 ? photos : id ? p.photo_urls : p.photo_urls,
                      }));
                    }}
                    loading={wbStepLoading}
                    emptyMessage="해당 기간에 수업이 없습니다."
                    coaches={coaches}
                    coachFilter={wbCoachFilter}
                    onCoachFilterChange={setWbCoachFilter}
                    anchorDate={wizardOpenDate}
                    onAnchorDateChange={setWizardOpenDate}
                    dateRangeLabel={wbDateRangeLabel}
                    getSearchText={(s) => `${s.title} ${nestedRecordName(s.users)}`}
                    getSummary={(s) => {
                      const n = normalizeSessionPhotoUrls(s.photo_url).length;
                      return n > 0 ? `사진 ${n}장` : '';
                    }}
                    renderPreview={(item) => {
                      if (!item) return null;
                      const photos = normalizeSessionPhotoUrls(item.photo_url);
                      if (photos.length === 0) return '— 사진 없음';
                      return (
                        <div className="flex flex-wrap gap-2">
                          {photos.map((url) => (
                            <img key={url} src={url} alt="" className="h-20 w-20 rounded-lg object-cover border border-slate-200" />
                          ))}
                        </div>
                      );
                    }}
                  />
                  <p className="text-[11px] text-slate-500">세션에 없는 사진을 추가로 올릴 수도 있습니다.</p>
                  <label
                    htmlFor="weekly-best-wizard-photo"
                    className="w-full min-h-[72px] border-2 border-dashed border-slate-200 rounded-2xl flex flex-col items-center justify-center gap-2 text-slate-500 hover:border-indigo-300 hover:bg-indigo-50/30 transition-all cursor-pointer touch-manipulation py-4"
                  >
                    <input
                      id="weekly-best-wizard-photo"
                      ref={wbPhotoInputRef}
                      type="file"
                      accept="image/*"
                      multiple
                      className="sr-only"
                      onChange={handleWbPhotoUpload}
                    />
                    <Camera size={24} />
                    <span className="text-sm font-bold">추가 사진 업로드</span>
                  </label>
                  {wbForm.photo_urls.length > 0 && (
                    <div className="flex flex-wrap gap-2">
                      {wbForm.photo_urls.map((url, i) => (
                        <div key={i} className="relative w-20 h-20 rounded-lg overflow-hidden border border-slate-200">
                          <img src={url} alt="" className="w-full h-full object-cover" />
                          <button
                            type="button"
                            onClick={() => setWbForm((p) => ({ ...p, photo_urls: p.photo_urls.filter((_, j) => j !== i) }))}
                            className="absolute top-0 right-0 w-6 h-6 bg-red-500 text-white rounded-bl text-xs font-bold flex items-center justify-center"
                          >×</button>
                        </div>
                      ))}
                    </div>
                  )}
                  <div className="flex gap-2">
                    <button type="button" onClick={() => setWizardStep(2)} className="flex-1 min-h-[48px] bg-slate-100 text-slate-700 rounded-2xl font-bold">이전</button>
                    <button
                      type="button"
                      onClick={() => {
                        if (wbForm.photo_urls.length > 0 && !wbForm.photo_session_id) {
                          toast.error('사진 강사(수업)를 선택해 주세요. 그래야 이름이 표시됩니다.');
                          return;
                        }
                        setWizardStep(4);
                      }}
                      className="flex-1 min-h-[48px] bg-slate-900 text-white rounded-2xl font-bold"
                    >
                      다음: 베스트 피드백 선택
                    </button>
                  </div>
                </>
              )}
              {wizardStep === 4 && (
                <>
                  <p className="text-[11px] text-slate-500">
                    {wbFeedbackScope === 'center'
                      ? '센터 피드백은 파일 첨부 형식입니다. 연결할 센터 수업을 고른 뒤, 주간베스트용 요약을 직접 작성하세요.'
                      : '작성 시점 기준 -7일 ~ -1일 세션 중 피드백이 있는 것만 표시됩니다.'}
                  </p>
                  <div className="flex gap-2 bg-slate-50 p-1 rounded-2xl border border-slate-200">
                    <button
                      type="button"
                      onClick={() => {
                        setWbFeedbackScope('private');
                        setWbForm((p) => ({
                          ...p,
                          feedback_session_id: '',
                          feedback_note: '',
                        }));
                      }}
                      className={`flex-1 min-h-[40px] px-3 rounded-xl text-sm font-bold transition-all cursor-pointer ${
                        wbFeedbackScope === 'private' ? 'bg-slate-900 text-white' : 'text-slate-500 hover:text-slate-700'
                      }`}
                    >
                      과외 피드백
                    </button>
                    <button
                      type="button"
                      onClick={() => {
                        setWbFeedbackScope('center');
                        setWbForm((p) => ({
                          ...p,
                          feedback_session_id: '',
                          feedback_note: '',
                        }));
                      }}
                      className={`flex-1 min-h-[40px] px-3 rounded-xl text-sm font-bold transition-all cursor-pointer ${
                        wbFeedbackScope === 'center' ? 'bg-slate-900 text-white' : 'text-slate-500 hover:text-slate-700'
                      }`}
                    >
                      센터 피드백
                    </button>
                  </div>
                  <WeeklyBestSessionPicker
                    key={wbFeedbackScope}
                    items={feedbackSessions}
                    selectedId={wbForm.feedback_session_id}
                    onSelect={(id) => setWbForm((p) => ({ ...p, feedback_session_id: id }))}
                    loading={wbStepLoading}
                    emptyMessage={wbFeedbackScope === 'center' ? '해당 기간에 센터 수업이 없습니다.' : '해당 기간에 피드백이 없습니다.'}
                    coaches={coaches}
                    coachFilter={wbCoachFilter}
                    onCoachFilterChange={setWbCoachFilter}
                    anchorDate={wizardOpenDate}
                    onAnchorDateChange={setWizardOpenDate}
                    dateRangeLabel={wbDateRangeLabel}
                    getSearchText={(s) => `${s.title} ${nestedRecordName(s.users)} ${getFeedbackSessionPreview(s)}`}
                    getSummary={(s) => getFeedbackSessionPreview(s)}
                    renderPreview={(item) => (item ? getFeedbackPreviewFull(item) : null)}
                  />
                  {showCenterFeedbackNoteInput && (
                    <div className="space-y-2">
                      <p className="text-[11px] font-bold text-amber-700">센터 피드백 요약 (필수)</p>
                      <textarea
                        placeholder="주간베스트에 게시할 센터 피드백 요약을 입력하세요"
                        value={wbForm.feedback_note}
                        onChange={(e) => setWbForm((p) => ({ ...p, feedback_note: e.target.value }))}
                        className="w-full min-h-[120px] px-4 py-3 bg-amber-50/60 rounded-2xl border border-amber-100 outline-none text-sm text-slate-700 placeholder-slate-400 resize-none"
                      />
                    </div>
                  )}
                  <div className="flex gap-2">
                    <button type="button" onClick={() => setWizardStep(3)} className="flex-1 min-h-[48px] bg-slate-100 text-slate-700 rounded-2xl font-bold">이전</button>
                    <button type="button" onClick={saveWeeklyBest} disabled={wbSaving} className="flex-1 min-h-[48px] bg-indigo-600 text-white rounded-2xl font-bold disabled:opacity-50">
                      {wbSaving ? '저장 중...' : editingWeeklyBestId ? '수정 저장' : '주간베스트 게시하기'}
                    </button>
                  </div>
                </>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import Link from 'next/link';
import { useCallback, useEffect, useRef, useState } from 'react';
import { ArrowUpRight, Image as ImageIcon, Loader2, Save, Trash2 } from 'lucide-react';
import { toast } from 'sonner';

import { getSupabaseBrowserClient } from '@/app/lib/supabase/browser';
import {
  deleteFromStorage,
  getPublicUrl,
  uploadToStorage,
  withPublicUrlCacheBust,
} from '@/app/lib/admin/assets/storageClient';
import { optimizeToWebP } from '@/app/lib/admin/assets/imageOptimizer';
import { resolveSpomovePackCacheBust } from '@/app/lib/spomove/spomoveAssetCacheVersion';
import {
  HOME_MEDIA_FALLBACK,
  HOME_MEDIA_PACK_ID,
  HOME_MEDIA_PACK_NAME,
  homeMediaStoragePath,
  normalizeMasterHomeMedia,
  type MasterHomeMedia,
} from '@/app/spokedu-master/lib/homeMediaAssets';

const OPTIMIZE = { maxW: 1920, maxH: 1080, quality: 0.84 } as const;

export function HomeMediaManager() {
  const fileRef = useRef<HTMLInputElement>(null);
  const mediaRef = useRef<MasterHomeMedia>({ heroImage: null });
  const [media, setMedia] = useState<MasterHomeMedia>({ heroImage: null });
  const [cacheBust, setCacheBust] = useState<number | undefined>();
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  const persist = useCallback(async (next: MasterHomeMedia) => {
    const response = await fetch('/api/admin/think-asset-pack', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      credentials: 'same-origin',
      body: JSON.stringify({
        id: HOME_MEDIA_PACK_ID,
        name: HOME_MEDIA_PACK_NAME,
        theme: 'master-home',
        assets_json: next,
      }),
    });
    const body = (await response.json().catch(() => ({}))) as { error?: string; updated_at?: string };
    if (!response.ok) throw new Error(body.error ?? '홈 이미지를 저장하지 못했습니다.');
    mediaRef.current = next;
    setMedia(next);
    setCacheBust(resolveSpomovePackCacheBust(body.updated_at, next.heroImage ? [next.heroImage] : []) ?? Date.now());
  }, []);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const supabase = getSupabaseBrowserClient();
      const { data, error } = await supabase
        .from('think_asset_packs')
        .select('assets_json, updated_at')
        .eq('id', HOME_MEDIA_PACK_ID)
        .maybeSingle();
      if (error && error.code !== 'PGRST116') throw error;
      const next = normalizeMasterHomeMedia(data?.assets_json);
      mediaRef.current = next;
      setMedia(next);
      setCacheBust(
        resolveSpomovePackCacheBust(
          data?.updated_at as string | undefined,
          next.heroImage ? [next.heroImage] : [],
        ),
      );
    } catch (error) {
      toast.error(error instanceof Error ? error.message : '홈 이미지를 불러오지 못했습니다.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void load();
  }, [load]);

  const previewSrc = media.heroImage
    ? withPublicUrlCacheBust(getPublicUrl(media.heroImage), cacheBust)
    : HOME_MEDIA_FALLBACK.heroImage;

  const onUpload = async (file: File | undefined) => {
    if (!file) return;
    if (!file.type.startsWith('image/')) {
      toast.error('이미지 파일만 업로드할 수 있습니다.');
      return;
    }
    setSaving(true);
    try {
      const optimized = await optimizeToWebP(file, OPTIMIZE);
      const path = homeMediaStoragePath();
      await uploadToStorage(path, optimized, 'image/webp');
      await persist({ heroImage: path });
      toast.success('홈 대표 이미지를 저장했습니다.');
    } catch (error) {
      toast.error(error instanceof Error ? error.message : '홈 대표 이미지 저장에 실패했습니다.');
    } finally {
      setSaving(false);
      if (fileRef.current) fileRef.current.value = '';
    }
  };

  const onReset = async () => {
    if (!media.heroImage) return;
    setSaving(true);
    try {
      const previous = mediaRef.current.heroImage;
      await persist({ heroImage: null });
      if (previous) await deleteFromStorage(previous).catch(() => undefined);
      toast.success('기본 홈 이미지로 복원했습니다.');
    } catch (error) {
      toast.error(error instanceof Error ? error.message : '기본 이미지로 복원하지 못했습니다.');
    } finally {
      setSaving(false);
    }
  };

  return (
    <section className="border-b border-slate-200 bg-white px-4 py-4 sm:px-5" aria-labelledby="home-media-heading">
      <div className="flex flex-wrap items-start justify-between gap-4">
        <div className="min-w-0">
          <p className="text-[11px] font-semibold text-slate-500">MASTER 홈</p>
          <h2 id="home-media-heading" className="mt-0.5 text-[15px] font-semibold text-slate-950">홈 대표 이미지</h2>
          <p className="mt-1 text-[12px] text-slate-500">홈 상단의 대표 이미지만 관리합니다. 업로드 이미지는 WebP로 최적화됩니다.</p>
        </div>
        <div className="flex flex-wrap items-center gap-2">
          <Link
            href="/spokedu-lab/dashboard"
            target="_blank"
            rel="noreferrer"
            className="inline-flex h-10 items-center gap-1.5 rounded-lg border border-slate-200 bg-white px-3 text-[12px] font-semibold text-slate-700"
          >
            홈에서 확인 <ArrowUpRight className="h-3.5 w-3.5" aria-hidden />
          </Link>
          <input
            ref={fileRef}
            type="file"
            accept="image/png,image/jpeg,image/webp"
            className="sr-only"
            onChange={(event) => void onUpload(event.target.files?.[0])}
          />
          <button
            type="button"
            disabled={saving || loading}
            onClick={() => fileRef.current?.click()}
            className="inline-flex h-10 items-center gap-1.5 rounded-lg border border-slate-200 bg-white px-3 text-[12px] font-semibold text-slate-800 disabled:opacity-50"
          >
            {saving ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Save className="h-3.5 w-3.5" />}
            이미지 업로드
          </button>
          <button
            type="button"
            disabled={saving || loading || !media.heroImage}
            onClick={() => void onReset()}
            className="inline-flex h-10 items-center gap-1.5 rounded-lg border border-slate-200 px-3 text-[12px] font-semibold text-slate-600 disabled:opacity-40"
          >
            <Trash2 className="h-3.5 w-3.5" /> 기본값으로 복원
          </button>
        </div>
      </div>
      <div className="mt-3 overflow-hidden rounded-xl bg-slate-100">
        {loading ? (
          <div className="grid aspect-[16/6] place-items-center text-slate-400">
            <Loader2 className="h-5 w-5 animate-spin" />
          </div>
        ) : (
          <img src={previewSrc} alt="현재 홈 대표 이미지" className="aspect-[16/6] w-full object-cover object-center" />
        )}
        {!media.heroImage ? (
          <p className="flex items-center gap-1.5 px-3 py-2 text-[11px] font-medium text-slate-500">
            <ImageIcon className="h-3.5 w-3.5" /> 현재는 저장소의 SPOKEDU 현장 기본 이미지를 사용 중입니다.
          </p>
        ) : null}
      </div>
    </section>
  );
}

'use client';

import { useCallback, useEffect, useRef, useState } from 'react';
import { Image as ImageIcon, Loader2, Save, Trash2 } from 'lucide-react';
import { toast } from 'sonner';
import { getSupabaseBrowserClient } from '@/app/lib/supabase/browser';
import {
  deleteFromStorage,
  getPublicUrl,
  uploadToStorage,
  withPublicUrlCacheBust,
} from '@/app/lib/admin/assets/storageClient';
import { optimizeToWebP } from '@/app/lib/admin/assets/imageOptimizer';
import { resolveSpomovePackCacheBust } from '@/app/lib/spomove/spomoveAssetCacheVersion';
import {
  normalizeProgramGatewayMedia,
  PROGRAM_GATEWAY_FALLBACK,
  PROGRAM_GATEWAY_PACK_ID,
  PROGRAM_GATEWAY_PACK_NAME,
  programGatewayStoragePath,
  type ProgramGatewayHeroKey,
  type ProgramGatewayMedia,
} from '@/app/spokedu-master/lib/programGatewayAssets';

const OPTIMIZE = { maxW: 1600, maxH: 900, quality: 0.82 } as const;

export function ProgramGatewayHeroManager({ domain }: { domain: 'lesson' | 'spomove' }) {
  const key: ProgramGatewayHeroKey = domain === 'lesson' ? 'lessonHero' : 'spomoveHero';
  const label = domain === 'lesson' ? 'Programs Gateway 대표 이미지' : 'SPOMOVE Gateway 대표 이미지';
  const fileRef = useRef<HTMLInputElement>(null);
  const mediaRef = useRef<ProgramGatewayMedia>({ lessonHero: null, spomoveHero: null });
  const [media, setMedia] = useState<ProgramGatewayMedia>({ lessonHero: null, spomoveHero: null });
  const [cacheBust, setCacheBust] = useState<number | undefined>();
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  const persist = useCallback(async (next: ProgramGatewayMedia) => {
    const res = await fetch('/api/admin/think-asset-pack', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      credentials: 'same-origin',
      body: JSON.stringify({
        id: PROGRAM_GATEWAY_PACK_ID,
        name: PROGRAM_GATEWAY_PACK_NAME,
        theme: 'master-gateway',
        assets_json: next,
      }),
    });
    const body = (await res.json().catch(() => ({}))) as { error?: string; updated_at?: string };
    if (!res.ok) throw new Error(body.error ?? 'Gateway 이미지를 저장하지 못했습니다.');
    mediaRef.current = next;
    setMedia(next);
    setCacheBust(resolveSpomovePackCacheBust(body.updated_at, [next.lessonHero, next.spomoveHero].filter(Boolean) as string[]) ?? Date.now());
  }, []);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const supabase = getSupabaseBrowserClient();
      const { data, error } = await supabase
        .from('think_asset_packs')
        .select('assets_json, updated_at')
        .eq('id', PROGRAM_GATEWAY_PACK_ID)
        .maybeSingle();
      if (error && error.code !== 'PGRST116') throw error;
      const next = normalizeProgramGatewayMedia(data?.assets_json);
      mediaRef.current = next;
      setMedia(next);
      setCacheBust(
        resolveSpomovePackCacheBust(
          data?.updated_at as string | undefined,
          [next.lessonHero, next.spomoveHero].filter(Boolean) as string[],
        ),
      );
    } catch (loadError) {
      toast.error(loadError instanceof Error ? loadError.message : 'Gateway 이미지를 불러오지 못했습니다.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void load();
  }, [load]);

  const previewSrc = media[key]
    ? withPublicUrlCacheBust(getPublicUrl(media[key]!), cacheBust)
    : PROGRAM_GATEWAY_FALLBACK[key];

  const onUpload = async (file: File | undefined) => {
    if (!file) return;
    if (!file.type.startsWith('image/')) {
      toast.error('이미지 파일만 업로드할 수 있습니다.');
      return;
    }
    setSaving(true);
    try {
      const optimized = await optimizeToWebP(file, OPTIMIZE);
      const path = programGatewayStoragePath(key);
      await uploadToStorage(path, optimized, 'image/webp');
      const previous = mediaRef.current[key];
      const next = { ...mediaRef.current, [key]: path };
      if (previous && previous !== path) {
        try {
          await deleteFromStorage(previous);
        } catch {
          /* previous cleanup is best-effort */
        }
      }
      await persist(next);
      toast.success(`${label}을 저장했습니다.`);
    } catch (uploadError) {
      toast.error(uploadError instanceof Error ? uploadError.message : '이미지 저장에 실패했습니다.');
    } finally {
      setSaving(false);
      if (fileRef.current) fileRef.current.value = '';
    }
  };

  const onClear = async () => {
    if (!media[key]) return;
    setSaving(true);
    try {
      const previous = mediaRef.current[key];
      const next = { ...mediaRef.current, [key]: null };
      await persist(next);
      if (previous) {
        try {
          await deleteFromStorage(previous);
        } catch {
          /* ignore */
        }
      }
      toast.success('기본 이미지로 되돌렸습니다.');
    } catch (clearError) {
      toast.error(clearError instanceof Error ? clearError.message : '이미지를 비우지 못했습니다.');
    } finally {
      setSaving(false);
    }
  };

  return (
    <section className="border-b border-slate-200 bg-white px-4 py-4 sm:px-5">
      <div className="flex flex-wrap items-start justify-between gap-4">
        <div className="min-w-0">
          <p className="text-[11px] font-semibold text-slate-500">Programs Gateway</p>
          <h2 className="mt-0.5 text-[15px] font-semibold text-slate-950">{label}</h2>
          <p className="mt-1 text-[12px] text-slate-500">Public Programs 페이지의 해당 영역 히어로만 바뀝니다. 없으면 기본 정적 이미지를 씁니다.</p>
        </div>
        <div className="flex items-center gap-2">
          <input
            ref={fileRef}
            type="file"
            accept="image/png,image/jpeg,image/webp"
            className="sr-only"
            onChange={(event) => void onUpload(event.target.files?.[0])}
          />
          <button
            type="button"
            disabled={saving || loading}
            onClick={() => fileRef.current?.click()}
            className="inline-flex h-10 items-center gap-1.5 rounded-lg border border-slate-200 bg-white px-3 text-[12px] font-semibold text-slate-800 disabled:opacity-50"
          >
            {saving ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Save className="h-3.5 w-3.5" />}
            업로드
          </button>
          <button
            type="button"
            disabled={saving || loading || !media[key]}
            onClick={() => void onClear()}
            className="inline-flex h-10 items-center gap-1.5 rounded-lg border border-slate-200 px-3 text-[12px] font-semibold text-slate-600 disabled:opacity-40"
          >
            <Trash2 className="h-3.5 w-3.5" />
            기본값
          </button>
        </div>
      </div>
      <div className="mt-3 overflow-hidden rounded-xl bg-slate-100">
        {loading ? (
          <div className="grid aspect-[16/7] place-items-center text-slate-400">
            <Loader2 className="h-5 w-5 animate-spin" />
          </div>
        ) : (
          <img src={previewSrc} alt="" className="aspect-[16/7] w-full object-cover" />
        )}
        {!media[key] ? (
          <p className="flex items-center gap-1.5 px-3 py-2 text-[11px] font-medium text-slate-500">
            <ImageIcon className="h-3.5 w-3.5" /> 현재는 코드 기본 이미지를 사용 중입니다.
          </p>
        ) : null}
      </div>
    </section>
  );
}

﻿'use client';

import {
