function SlotProgramCombobox({
  items,
  selectedId,
  selectedElsewhere,
  disabled,
  onSelect,
}: {
  items: ProgramItem[];
  selectedId: number | null;
  selectedElsewhere: Set<number>;
  disabled?: boolean;
  onSelect: (curriculumId: number | null) => void;
}) {
  const listboxId = useId();
  const rootRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const listRef = useRef<HTMLUListElement>(null);
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState('');
  const [highlight, setHighlight] = useState(0);

  const selected = items.find((item) => item.curriculum.id === selectedId) ?? null;
  const inputValue = open ? query : selected?.effective.title ?? '';

  const options = useMemo(() => {
    const normalized = query.trim().toLowerCase();
    return items
      .filter((item) => {
        const id = item.curriculum.id;
        if (selectedElsewhere.has(id) && id !== selectedId) return false;
        if (!normalized) return true;
        const text =
          `${item.effective.title} ${item.curriculum.title} ${item.curriculum.id}`.toLowerCase();
        return text.includes(normalized);
      })
      .sort((a, b) => {
        const titleCompare = koreanTitleCollator.compare(
          a.effective.title.trim(),
          b.effective.title.trim(),
        );
        return titleCompare || a.curriculum.id - b.curriculum.id;
      });
  }, [items, query, selectedElsewhere, selectedId]);

  useEffect(() => {
    if (!open) return;
    const onPointerDown = (event: PointerEvent) => {
      if (!rootRef.current?.contains(event.target as Node)) {
        setOpen(false);
        setQuery('');
      }
    };
    document.addEventListener('pointerdown', onPointerDown);
    return () => document.removeEventListener('pointerdown', onPointerDown);
  }, [open]);

  useEffect(() => {
    setHighlight(0);
  }, [query, open]);

  useEffect(() => {
    if (!open) return;
    const active = listRef.current?.querySelector<HTMLElement>('[data-active="true"]');
    active?.scrollIntoView({ block: 'nearest' });
  }, [highlight, open, options]);

  const choose = (curriculumId: number | null) => {
    onSelect(curriculumId);
    setOpen(false);
    setQuery('');
    inputRef.current?.blur();
  };

  const onKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'ArrowDown') {
      event.preventDefault();
      if (!open) {
        setOpen(true);
        return;
      }
      setHighlight((current) => {
        if (current < 0) return 0;
        return Math.min(current + 1, Math.max(options.length - 1, 0));
      });
      return;
    }
    if (event.key === 'ArrowUp') {
      event.preventDefault();
      if (!open) {
        setOpen(true);
        return;
      }
      setHighlight((current) => {
        if (current <= 0) return -1;
        return current - 1;
      });
      return;
    }
    if (event.key === 'Enter') {
      event.preventDefault();
      if (!open) {
        setOpen(true);
        return;
      }
      if (highlight < 0) {
        choose(null);
        return;
      }
      const item = options[highlight];
      if (item) choose(item.curriculum.id);
      return;
    }
    if (event.key === 'Escape') {
      event.preventDefault();
      setOpen(false);
      setQuery('');
    }
  };

  return (
    <div ref={rootRef} className="relative mt-2">
      <Search
        className="pointer-events-none absolute left-3 top-1/2 z-10 -translate-y-1/2 text-slate-400"
        size={14}
      />
      <input
        ref={inputRef}
        value={inputValue}
        disabled={disabled}
        role="combobox"
        aria-expanded={open}
        aria-autocomplete="list"
        aria-controls={listboxId}
        autoComplete="off"
        placeholder={selected ? selected.effective.title : '프로그램명 또는 ID 검색'}
        onFocus={() => {
          setOpen(true);
          setQuery('');
        }}
        onChange={(event) => {
          setQuery(event.target.value);
          if (!open) setOpen(true);
        }}
        onKeyDown={onKeyDown}
        className="h-10 w-full rounded-lg border border-slate-200 bg-white pl-8 pr-9 text-[12px] font-bold text-slate-800 outline-none focus:border-indigo-400 disabled:opacity-50"
      />
      <ChevronDown
        className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-slate-400"
        size={14}
      />
      {open ? (
        <div className="absolute left-0 right-0 top-[calc(100%+4px)] z-30 overflow-hidden rounded-lg border border-slate-200 bg-white shadow-lg">
          <p className="border-b border-slate-100 px-3 py-1.5 text-[10px] font-black text-slate-400">
            {options.length}개 · 키보드 ↑↓ Enter
          </p>
          <ul
            ref={listRef}
            id={listboxId}
            role="listbox"
            className="max-h-56 overflow-y-auto py-1"
          >
            <li role="option" aria-selected={selectedId == null}>
              <button
                type="button"
                data-active={highlight === -1 ? 'true' : undefined}
                onMouseEnter={() => setHighlight(-1)}
                onClick={() => choose(null)}
                className="flex w-full items-center justify-between px-3 py-2 text-left text-[12px] font-bold"
                style={{
                  background: highlight === -1 ? '#eef2ff' : 'transparent',
                  color: highlight === -1 ? '#4338ca' : '#64748b',
                }}
              >
                빈 슬롯
              </button>
            </li>
            {options.length === 0 ? (
              <li className="px-3 py-3 text-[12px] font-bold text-slate-400">검색 결과 없음</li>
            ) : (
              options.map((item, optionIndex) => {
                const active = highlight === optionIndex;
                const isSelected = item.curriculum.id === selectedId;
                return (
                  <li
                    key={item.curriculum.id}
                    role="option"
                    aria-selected={isSelected}
                  >
                    <button
                      type="button"
                      data-active={active ? 'true' : undefined}
                      onMouseEnter={() => setHighlight(optionIndex)}
                      onClick={() => choose(item.curriculum.id)}
                      className="flex w-full items-center justify-between gap-2 px-3 py-2 text-left"
                      style={{
                        background: active ? '#eef2ff' : isSelected ? '#f8fafc' : 'transparent',
                      }}
                    >
                      <span className="min-w-0">
                        <span className="block truncate text-[12px] font-black text-slate-900">
                          {item.effective.title}
                        </span>
                        <span className="block text-[10px] font-bold text-slate-400">
                          #{item.curriculum.id}
                        </span>
                      </span>
                      {isSelected ? <Check size={14} className="shrink-0 text-indigo-600" /> : null}
                    </button>
                  </li>
                );
              })
            )}
          </ul>
        </div>
      ) : null}
    </div>
  );
}

function WeeklyRecommendationManager({
  items,
  onSaved,
}: {
  items: ProgramItem[];
  onSaved: () => Promise<void>;
}) {
  const [slots, setSlots] = useState<Array<number | null>>([null, null, null, null]);
  const [loadingSlots, setLoadingSlots] = useState(true);
  const [savingSlots, setSavingSlots] = useState(false);

  useEffect(() => {
    let active = true;
    const loadSlots = async () => {
      try {
        const res = await fetch('/api/admin/spokedu-master/programs/home-featured', {
          cache: 'no-store',
        });
        const json = await readAdminJsonSafe<{
          slots?: Array<number | null>;
          error?: string;
        }>(res, '추천 슬롯을 불러오지 못했습니다');
        if (!res.ok) throw new Error(json.error ?? '추천 슬롯을 불러오지 못했습니다.');
        if (active) {
          setSlots(
            Array.from({ length: 4 }, (_, index) => json.slots?.[index] ?? null),
          );
        }
      } catch (error) {
        toast.error(
          error instanceof Error ? error.message : '추천 슬롯을 불러오지 못했습니다.',
        );
      } finally {
        if (active) setLoadingSlots(false);
      }
    };
    void loadSlots();
    return () => {
      active = false;
    };
  }, []);

  const updateSlot = (index: number, curriculumId: number | null) => {
    setSlots((current) => {
      if (
        curriculumId != null &&
        current.some((id, slotIndex) => slotIndex !== index && id === curriculumId)
      ) {
        toast.error('같은 프로그램을 여러 추천 슬롯에 선택할 수 없습니다.');
        return current;
      }
      return current.map((id, slotIndex) => (slotIndex === index ? curriculumId : id));
    });
  };

  const saveSlots = async () => {
    setSavingSlots(true);
    try {
      const res = await fetch('/api/admin/spokedu-master/programs/home-featured', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ slots }),
      });
      const json = await readAdminJsonSafe<{
        slots?: Array<number | null>;
        message?: string;
        error?: string;
      }>(res, '추천 슬롯 저장에 실패했습니다');
      if (!res.ok) throw new Error(json.error ?? '추천 슬롯 저장에 실패했습니다.');
      setSlots(Array.from({ length: 4 }, (_, index) => json.slots?.[index] ?? null));
      await useMasterStore.getState().reloadPrograms();
      await onSaved();
      toast.success(json.message ?? '이번주 추천 프로그램을 저장했습니다.');
    } catch (error) {
      toast.error(error instanceof Error ? error.message : '추천 슬롯 저장에 실패했습니다.');
    } finally {
      setSavingSlots(false);
    }
  };

  return (
    <section className="border-b border-slate-200 bg-slate-50 px-4 py-4 sm:px-5">
      <div className="mx-auto max-w-[1500px] rounded-xl border border-indigo-100 bg-white p-4 shadow-sm">
        <div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
          <div>
            <p className="text-[11px] font-black uppercase tracking-[0.12em] text-indigo-600">
              Weekly recommendation
            </p>
            <h2 className="mt-1 text-[17px] font-black text-slate-950">
              이번주 추천 프로그램 관리
            </h2>
            <p className="mt-1 text-[12px] font-semibold leading-5 text-slate-500">
              프로그램명·ID로 검색해 고르세요. 선택한 프로그램은 슬롯 순서대로 홈에 반영되며, 빈
              슬롯은 자동 추천으로 보완됩니다.
            </p>
          </div>
          <button
            type="button"
            onClick={() => void saveSlots()}
            disabled={loadingSlots || savingSlots}
            className="spm-btn-primary inline-flex h-10 shrink-0 items-center justify-center gap-2 rounded-[10px] px-4 text-[12px] font-black focus-visible:outline-none disabled:opacity-50"
          >
            <Save size={14} />
            {savingSlots ? '추천 저장 중' : '추천 슬롯 저장'}
          </button>
        </div>

        <div className="mt-4 grid gap-3 md:grid-cols-2 xl:grid-cols-4">
          {slots.map((selectedId, index) => {
            const selectedElsewhere = new Set(
              slots.filter((id, slotIndex): id is number => slotIndex !== index && id != null),
            );

            return (
              <div key={index} className="rounded-lg border border-slate-200 bg-slate-50 p-3">
                <div className="flex items-center justify-between gap-2">
                  <p className="text-[13px] font-black text-slate-900">
                    {index + 1}번 추천 슬롯
                  </p>
                  {selectedId != null ? (
                    <button
                      type="button"
                      onClick={() => updateSlot(index, null)}
                      className="text-[11px] font-black text-slate-400 hover:text-rose-600"
                    >
                      비우기
                    </button>
                  ) : null}
                </div>
                <SlotProgramCombobox
                  items={items}
                  selectedId={selectedId}
                  selectedElsewhere={selectedElsewhere}
                  disabled={loadingSlots}
                  onSelect={(curriculumId) => updateSlot(index, curriculumId)}
                />
                {selectedId != null ? (
                  <p className="mt-1.5 text-[11px] font-bold text-slate-400">#{selectedId}</p>
                ) : (
                  <p className="mt-1.5 text-[11px] font-bold text-slate-400">비어 있음</p>
                )}
              </div>
            );
          })}
        </div>
      </div>
    </section>
  );
}

export default function AdminSmProgramsPage() {
  const pathname = usePathname();
  const isSpomoveAdmin = pathname.startsWith('/admin/spokedu-lab/spomove') || pathname.startsWith('/admin/spokedu-master/spomove');
  const tabOptions = isSpomoveAdmin ? SPOMOVE_ADMIN_TAB_OPTIONS : LIBRARY_ADMIN_TAB_OPTIONS;
  const [items, setItems] = useState<ProgramItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [creating, setCreating] = useState(false);
  const [syncing, setSyncing] = useState(false);
  const [query, setQuery] = useState('');
  const [activeTab, setActiveTab] = useState<AdminTabKey>(isSpomoveAdmin ? 'spomove-content' : 'programs');
  const [activeFilter, setActiveFilter] = useState<FilterKey>('all');
  const [selectedId, setSelectedId] = useState<number | null>(null);
  const [form, setForm] = useState<EditForm | null>(null);
  const [mobilePane, setMobilePane] = useState<'list' | 'editor'>('list');
  const [createOpen, setCreateOpen] = useState(false);
  const [createForm, setCreateForm] = useState<CreateProgramForm>({
    title: '',
    videoUrl: '',
    equipment: '',
    steps: '',
  });
  const selectedIdRef = useRef<number | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    if (isSpomoveAdmin) {
      setItems([]);
      setSelectedId(null);
      setForm(null);
      setLoading(false);
      return;
    }
    try {
      const res = await fetch('/api/admin/spokedu-master/programs', { cache: 'no-store' });
      const json = await readAdminJsonSafe<ProgramsResponse & { error?: string }>(
        res,
        '프로그램 목록을 불러오지 못했습니다',
      );
      if (!res.ok) throw new Error(json.error ?? '프로그램 목록을 불러오지 못했습니다.');
      const nextItems = json.data ?? [];
      setItems(nextItems);
      const nextSelected =
        nextItems.find((item) => item.curriculum.id === selectedIdRef.current) ??
        nextItems[0] ??
        null;
      if (nextSelected) {
        setSelectedId(nextSelected.curriculum.id);
        setForm(toForm(nextSelected));
      } else {
        setSelectedId(null);
        setForm(null);
      }
    } catch (error) {
      toast.error(error instanceof Error ? error.message : '프로그램 목록을 불러오지 못했습니다.');
      setItems([]);
    } finally {
      setLoading(false);
    }
  }, [isSpomoveAdmin]);

  useEffect(() => {
    void load();
  }, [load]);

  useEffect(() => {
    selectedIdRef.current = selectedId;
  }, [selectedId]);

  useEffect(() => {
    if (!tabOptions.some((tab) => tab.key === activeTab)) {
      setActiveTab(tabOptions[0].key);
    }
  }, [activeTab, tabOptions]);

  const selected = useMemo(() => items.find((item) => item.curriculum.id === selectedId) ?? null, [items, selectedId]);

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    const next = items.filter((item) => {
      if (!matchesFilter(item, activeFilter)) return false;
      if (!q) return true;
      const haystack = `${item.effective.title} ${item.curriculum.id} ${item.effective.target} ${item.effective.space}`.toLowerCase();
      return haystack.includes(q);
    });
    return sortForFilter(next, activeFilter);
  }, [activeFilter, items, query]);

  const summary = useMemo(() => ({
    needsImprovement: items.filter((item) => getItemQuality(item).status === 'needs-improvement').length,
    homeReady: items.filter((item) => getItemQuality(item).status === 'home-ready').length,
    imageNeeded: items.filter((item) => !getItemQuality(item).checks.setupImage).length,
  }), [items]);

  const selectItem = (item: ProgramItem) => {
    setSelectedId(item.curriculum.id);
    setForm(toForm(item));
    setMobilePane('editor');
  };

  const openProgramFromAudit = (curriculumId: number) => {
    const item = items.find((candidate) => candidate.curriculum.id === curriculumId);
    if (!item) {
      toast.error('편집기 목록에 해당 수업이 없습니다. 새로고침 후 다시 시도해 주세요.');
      return;
    }
    selectItem(item);
    setActiveTab('programs');
  };

  const updateForm = <K extends keyof EditForm>(key: K, value: EditForm[K]) => {
    setForm((prev) => (prev ? { ...prev, [key]: value } : prev));
  };

  const updateCreateForm = <K extends keyof CreateProgramForm>(key: K, value: CreateProgramForm[K]) => {
    setCreateForm((prev) => ({ ...prev, [key]: value }));
  };

  const closeCreateModal = () => {
    if (creating) return;
    setCreateOpen(false);
  };

  const createProgram = async () => {
    const title = createForm.title.trim();
    if (!title) {
      toast.error('프로그램 제목을 입력해 주세요.');
      return;
    }

    setCreating(true);
    try {
      const res = await fetch('/api/admin/spokedu-master/programs', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(createForm),
      });
      const json = await readAdminJsonSafe<{ ok?: boolean; error?: string; program?: ProgramItem }>(
        res,
        '프로그램 추가에 실패했습니다',
      );
      if (!res.ok || json.ok !== true || !json.program) {
        throw new Error(json.error ?? '프로그램 추가에 실패했습니다.');
      }

      const next = json.program;
      setItems((current) => [next, ...current.filter((item) => item.curriculum.id !== next.curriculum.id)]);
      setSelectedId(next.curriculum.id);
      setForm(toForm(next));
      setActiveFilter('all');
      setQuery('');
      setCreateOpen(false);
      setCreateForm({ title: '', videoUrl: '', equipment: '', steps: '' });
      toast.success('프로그램을 추가했습니다. 이어서 상세 정보를 채워 주세요.');
    } catch (error) {
      toast.error(error instanceof Error ? error.message : '프로그램 추가에 실패했습니다.');
    } finally {
      setCreating(false);
    }
  };

  const syncFromCenter = async () => {
    setSyncing(true);
    try {
      const previewRes = await fetch('/api/admin/spokedu-master/programs/sync-center', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ dryRun: true }),
      });
      const preview = await readAdminJsonSafe<{
        error?: string;
        summary?: { toInsert: number; toUpdate: number };
        changes?: Array<{ title: string; fields: string[] }>;
        message?: string;
      }>(previewRes, '동기화 미리보기에 실패했습니다');
      if (!previewRes.ok) throw new Error(preview.error ?? '동기화 미리보기에 실패했습니다.');

      const total = (preview.summary?.toInsert ?? 0) + (preview.summary?.toUpdate ?? 0);
      if (total === 0) {
        toast.success(preview.message ?? '커리큘럼과 overlay가 이미 일치합니다.');
        return;
      }

      const sample = (preview.changes ?? [])
        .slice(0, 5)
        .map((item) => `• ${item.title} (${item.fields.join(', ')})`)
        .join('\n');
      const confirmed = window.confirm(
        `커리큘럼 본문을 overlay에 반영합니다.\n\n신규 ${preview.summary?.toInsert ?? 0}개 · 갱신 ${preview.summary?.toUpdate ?? 0}개\n\n${sample}${total > 5 ? `\n…외 ${total - 5}개` : ''}\n\n제목·태그·MASTER 메타는 그대로 두고, 영상 URL·체크리스트·교구·활동 단계·전문가 팁만 덮어씁니다.`,
      );
      if (!confirmed) return;

      const applyRes = await fetch('/api/admin/spokedu-master/programs/sync-center', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ dryRun: false }),
      });
      const applied = await readAdminJsonSafe<{ error?: string; message?: string; applied?: number }>(
        applyRes,
        '동기화 적용에 실패했습니다',
      );
      if (!applyRes.ok) throw new Error(applied.error ?? '동기화 적용에 실패했습니다.');

      await load();
      toast.success(applied.message ?? `커리큘럼 동기화 ${applied.applied ?? 0}건 완료`);
    } catch (error) {
      toast.error(error instanceof Error ? error.message : '커리큘럼 동기화에 실패했습니다.');
    } finally {
      setSyncing(false);
    }
  };

  const save = async () => {
    if (!selected || !form) return;
    setSaving(true);
    try {
      const res = await fetch(`/api/admin/spokedu-master/programs?id=${selected.curriculum.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(buildAdminProgramSavePayload({
          title: form.title,
          fallbackTitle: selected.curriculum.title,
          videoUrl: form.videoUrl,
          equipment: form.equipment,
          activityMethod: form.steps,
          publicationStatus: form.publicationStatus,
          theme: normalizeLessonTheme(form.theme),
          target: serializeMasterTags(parseMasterTargets(form.target)),
          tags: csvToList(form.tags),
          space: serializeMasterTags(parseMasterSpaces(form.space)),
          setupImageUrl: form.setupImageUrl,
          coachScript: form.coachScript,
          briefingNotes: form.briefingNotes,
          variationMethod: form.variations,
        })),
      });
      const json = await readAdminJsonSafe<{
        ok?: boolean;
        partialSave?: boolean;
        failedStage?: string;
        error?: string;
        program?: SavedAdminProgram<Partial<OverlayRow>, MetaRow>;
      }>(res, '저장에 실패했습니다');
      if (!res.ok || json.ok !== true) {
        const message = json.partialSave
          ? `일부 항목 저장 실패${json.failedStage ? ` (${json.failedStage})` : ''}. 다시 저장해 주세요.`
          : json.error ?? '저장에 실패했습니다.';
        throw new Error(message);
      }
      if (!json.program) throw new Error('저장된 프로그램 응답이 없습니다.');
      const next = mergeSavedProgram(selected, json.program);
      setItems((current) => replaceAdminProgramByCurriculumId(
        current,
        selected.curriculum.id,
        next,
        (item) => item.curriculum.id,
      ));
      setSelectedId(next.curriculum.id);
      setForm(toForm(next));
      toast.success('MASTER 편집 값이 저장되었습니다.');
    } catch (error) {
      toast.error(error instanceof Error ? error.message : '저장에 실패했습니다.');
    } finally {
      setSaving(false);
    }
  };

  const removeSetupImage = async () => {
    if (!selected || !form || !form.setupImageUrl.trim()) return;
    const previousForm = form;
    const previousImageUrl = form.setupImageUrl;
    const nextForm = { ...form, setupImageUrl: '' };

    setForm(nextForm);
    setSaving(true);
    try {
      const res = await fetch(`/api/admin/spokedu-master/programs?id=${selected.curriculum.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(buildAdminProgramSavePayload({
          title: nextForm.title,
          fallbackTitle: selected.curriculum.title,
          videoUrl: nextForm.videoUrl,
          equipment: nextForm.equipment,
          activityMethod: nextForm.steps,
          publicationStatus: nextForm.publicationStatus,
          theme: normalizeLessonTheme(nextForm.theme),
          target: serializeMasterTags(parseMasterTargets(nextForm.target)),
          tags: csvToList(nextForm.tags),
          space: serializeMasterTags(parseMasterSpaces(nextForm.space)),
          setupImageUrl: '',
          coachScript: nextForm.coachScript,
          briefingNotes: nextForm.briefingNotes,
          variationMethod: nextForm.variations,
        })),
      });
      const json = await readAdminJsonSafe<{
        ok?: boolean;
        partialSave?: boolean;
        failedStage?: string;
        error?: string;
        program?: SavedAdminProgram<Partial<OverlayRow>, MetaRow>;
      }>(res, '이미지 제거 저장에 실패했습니다');
      if (!res.ok || json.ok !== true) {
        const message = json.partialSave
          ? `이미지 제거 저장 중 일부 단계가 실패했습니다${json.failedStage ? ` (${json.failedStage})` : ''}.`
          : json.error ?? '이미지 제거 저장에 실패했습니다.';
        throw new Error(message);
      }
      if (!json.program) throw new Error('저장된 프로그램 응답이 없습니다.');

      const next = mergeSavedProgram(selected, json.program);
      setItems((current) => replaceAdminProgramByCurriculumId(
        current,
        selected.curriculum.id,
        next,
        (item) => item.curriculum.id,
      ));
      setSelectedId(next.curriculum.id);
      setForm(toForm(next));

      const path = storagePathFromPublicUrl(previousImageUrl);
      if (path) await deleteFromStorage(path).catch(() => undefined);
      toast.success('도식화 이미지를 제거했습니다.');
    } catch (error) {
      setForm(previousForm);
      toast.error(error instanceof Error ? error.message : '이미지 제거에 실패했습니다.');
    } finally {
      setSaving(false);
    }
  };

  const selectedQuality = form ? getFormQuality(form) : null;
  const selectedQualitySummary = selectedQuality ? qualitySummary(selectedQuality) : '';

  return (
    <div className="min-h-dvh bg-slate-50 text-slate-950">
      <header className="sticky top-0 z-20 border-b border-slate-200 bg-white px-4 py-3 sm:px-5 sm:py-4">
        <div className="flex flex-wrap items-center gap-3">
          <Link href="/admin/spokedu-master" className="grid h-11 w-11 shrink-0 place-items-center rounded-lg border border-slate-200 text-slate-500 sm:h-9 sm:w-9" aria-label="이전">
            <ChevronLeft size={17} />
          </Link>
          <div>
            <h1 className="text-[18px] font-black">{isSpomoveAdmin ? '마스터 스포무브' : '마스터 라이브러리'}</h1>
            <p className="mt-0.5 text-[12px] font-semibold text-slate-500">
              {isSpomoveAdmin
                ? 'SPOMOVE 썸네일과 가이드 영상을 직접 관리합니다.'
                : 'curriculum 원본은 보존하고 MASTER 라이브러리 메타와 운영 자료만 편집합니다.'}
            </p>
          </div>
          <div className="order-last flex w-full gap-1 overflow-x-auto rounded-lg border border-slate-200 bg-slate-50 p-1 sm:order-none sm:ml-auto sm:w-auto">
            {tabOptions.map((tab) => (
              <button
                key={tab.key}
                type="button"
                onClick={() => setActiveTab(tab.key)}
                className="min-h-11 shrink-0 rounded-md px-3 text-[12px] font-black transition-colors sm:min-h-8"
                style={{
                  background: activeTab === tab.key ? '#4f46e5' : 'transparent',
                  color: activeTab === tab.key ? '#ffffff' : '#475569',
                }}
              >
                {tab.label}
              </button>
            ))}
          </div>
          {activeTab === 'programs' ? (
            <>
          <button
            type="button"
            onClick={() => setCreateOpen(true)}
            disabled={creating}
            className="inline-flex min-h-11 items-center gap-2 rounded-lg bg-slate-950 px-3 text-[12px] font-black text-white disabled:opacity-50 sm:min-h-9"
          >
            <Plus size={14} />
            프로그램 직접 추가
          </button>
          <button
            type="button"
            onClick={() => void syncFromCenter()}
            disabled={syncing || loading}
            className="inline-flex min-h-11 items-center gap-2 rounded-lg border border-emerald-200 bg-emerald-50 px-3 text-[12px] font-black text-emerald-800 disabled:opacity-50 sm:min-h-9"
          >
            <RefreshCw size={14} className={syncing ? 'animate-spin' : ''} />
            {syncing ? '동기화 확인 중' : '커리큘럼 동기화'}
          </button>
          <button
            type="button"
            onClick={() => void load()}
            disabled={loading}
            className="inline-flex min-h-11 items-center gap-2 rounded-lg border border-slate-200 bg-white px-3 text-[12px] font-black text-slate-600 sm:min-h-9"
          >
            <RefreshCw size={14} className={loading ? 'animate-spin' : ''} />
            새로고침
          </button>
          <button
            type="button"
            onClick={() => void save()}
            disabled={!selected || !form || saving}
            className="spm-btn-primary inline-flex min-h-11 items-center gap-2 rounded-[10px] px-4 text-[12px] font-black focus-visible:outline-none disabled:opacity-50 sm:min-h-9"
          >
            <Save size={14} />
            {saving ? '저장 중' : '저장'}
          </button>
            </>
          ) : null}
        </div>
      </header>

      {activeTab === 'programs' ? (
        <>
          <HomeMediaManager />
          <ProgramGatewayHeroManager domain="lesson" />
          <WeeklyRecommendationManager items={items} onSaved={load} />
        </>
      ) : null}

      {isSpomoveAdmin ? (
        <>
          <ProgramGatewayHeroManager domain="spomove" />
          <SpomoveHomeFeaturedManager />
          <SpomoveHubFamilyFeaturedManager />
        </>
      ) : null}

      {createOpen ? (
        <CreateProgramModal
          form={createForm}
          creating={creating}
          onChange={updateCreateForm}
          onClose={closeCreateModal}
          onSubmit={() => void createProgram()}
        />
      ) : null}

      {activeTab === 'spomove-catalog' ? (
        <SpomoveCatalogManager />
      ) : activeTab === 'content-audit' ? (
        <ContentAuditPanel onOpenProgram={openProgramFromAudit} />
      ) : activeTab === 'spomove-thumbnails' ? (
        <SpomoveThumbnailManager />
      ) : activeTab === 'spomove-guide-videos' ? (
        <SpomoveGuideVideoManager />
      ) : (
      <>
      {!isSpomoveAdmin ? (
        <div className="sticky top-[73px] z-10 grid grid-cols-2 border-b border-slate-200 bg-white p-2 md:hidden">
          <button type="button" onClick={() => setMobilePane('list')} className={`min-h-11 rounded-lg text-sm font-black ${mobilePane === 'list' ? 'bg-slate-950 text-white' : 'text-slate-600'}`}>목록</button>
          <button type="button" onClick={() => setMobilePane('editor')} disabled={!selected || !form} className={`min-h-11 rounded-lg text-sm font-black disabled:opacity-40 ${mobilePane === 'editor' ? 'bg-slate-950 text-white' : 'text-slate-600'}`}>편집</button>
        </div>
      ) : null}
      <main className="grid min-h-[calc(100dvh-73px)] grid-cols-1 md:grid-cols-[280px_minmax(0,1fr)] lg:grid-cols-[340px_minmax(0,1fr)] xl:grid-cols-[360px_minmax(0,1fr)] 2xl:grid-cols-[380px_minmax(0,1fr)]">
        <aside className={`${mobilePane === 'list' ? 'block' : 'hidden'} border-r border-slate-200 bg-white md:block`}>
          <div className="space-y-3 border-b border-slate-200 p-4">
            <div className="grid grid-cols-3 gap-2">
              <div className="rounded-lg bg-indigo-50 p-3">
                <p className="text-[10px] font-black text-indigo-700">홈 가능</p>
                <p className="mt-1 text-[18px] font-black text-indigo-900">{summary.homeReady}</p>
              </div>
              <div className="rounded-lg bg-amber-50 p-3">
                <p className="text-[10px] font-black text-amber-700">보강 필요</p>
                <p className="mt-1 text-[18px] font-black text-amber-900">{summary.needsImprovement}</p>
              </div>
              <div className="rounded-lg bg-slate-100 p-3">
                <p className="text-[10px] font-black text-slate-600">이미지 필요</p>
                <p className="mt-1 text-[18px] font-black text-slate-900">{summary.imageNeeded}</p>
              </div>
            </div>
            <div className="flex flex-wrap gap-1.5">
              {FILTER_OPTIONS.map((filter) => (
                <button
                  key={filter.key}
                  type="button"
                  onClick={() => setActiveFilter(filter.key)}
                  className="min-h-11 rounded-full border px-3 text-[11px] font-black md:min-h-8"
                  style={{
                    borderColor: activeFilter === filter.key ? '#4f46e5' : '#e2e8f0',
                    background: activeFilter === filter.key ? '#eef2ff' : '#ffffff',
                    color: activeFilter === filter.key ? '#4338ca' : '#64748b',
                  }}
                >
                  {filter.label}
                </button>
              ))}
            </div>
            <div className="relative">
              <Search className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={15} />
              <input
                value={query}
                onChange={(event) => setQuery(event.target.value)}
                placeholder="프로그램명 또는 curriculumId 검색"
                className="h-10 w-full rounded-lg border border-slate-200 bg-slate-50 pl-9 pr-3 text-[13px] font-semibold outline-none focus:border-indigo-400"
              />
            </div>
          </div>

          <div className="max-h-[calc(100dvh-238px)] overflow-y-auto p-3">
            {loading ? (
              <div className="flex justify-center py-12">
                <div className="h-7 w-7 animate-spin rounded-full border-2 border-indigo-500 border-t-transparent" />
              </div>
            ) : filtered.map((item) => {
              const selectedNow = item.curriculum.id === selectedId;
              const quality = getItemQuality(item);
              const summaryText = qualitySummary(quality);
              const missingText = missingQualityLabels(quality.checks).join(', ');
              return (
                <button
                  key={item.curriculum.id}
                  type="button"
                  onClick={() => selectItem(item)}
                  className="mb-2 block min-h-16 w-full rounded-lg border p-3 text-left transition-colors"
                  style={{ borderColor: selectedNow ? '#6366f1' : '#e2e8f0', background: selectedNow ? '#eef2ff' : '#ffffff' }}
                  title={missingText ? `부족한 항목: ${missingText}` : summaryText}
                >
                  <div className="flex items-start gap-2">
                    <div className="min-w-0 flex-1">
                      <p className="truncate text-[13px] font-black text-slate-950">{item.effective.title}</p>
                      <p className="mt-0.5 text-[11px] font-bold text-slate-500">curriculumId {item.curriculum.id}</p>
                    </div>
                    <div className="shrink-0 text-right">
                      <StatusPill status={quality.status} />
                      <p className="mt-1 text-[10px] font-black text-slate-400">{quality.score}점 · {quality.grade}</p>
                    </div>
                  </div>
                  <div className="mt-2 hidden md:block">
                    <QualityFlags report={quality} />
                  </div>
                  <p className="mt-2 hidden line-clamp-2 text-[11px] font-bold leading-4 text-slate-500 md:block">{summaryText}</p>
                </button>
              );
            })}
          </div>
        </aside>

        <section className={`${mobilePane === 'editor' ? 'block' : 'hidden'} min-w-0 overflow-y-auto p-4 sm:p-6 md:block`}>
          {selected && form ? (
            <div className="mx-auto max-w-[1500px] space-y-5">
              <div className="rounded-lg border border-slate-200 bg-white p-4">
                <div className="flex flex-wrap items-start gap-3">
                  <div className="min-w-0 flex-1">
                    <p className="text-[11px] font-black uppercase text-slate-400">curriculum 원본 제목</p>
                    <h2 className="mt-1 text-[20px] font-black text-slate-950">{selected.curriculum.title}</h2>
                    <p className="mt-1 text-[12px] font-bold text-slate-500">MASTER 노출 제목: {form.title || selected.curriculum.title}</p>
                  </div>
                  <StatusPill status={getItemQuality(selected).status} />
                  <span className="inline-flex h-7 items-center rounded-full bg-slate-100 px-2.5 text-[11px] font-black text-slate-600">
                    {form.publicationStatus}
                    {selected.overlay?.is_published === true ? '' : ' · MASTER 미노출'}
                  </span>
                </div>
              </div>

              {selectedQuality ? (
                <p className="rounded-lg border border-slate-200 bg-white px-4 py-3 text-[12px] font-semibold text-slate-600">
                  완성도 {selectedQuality.score}점 · {selectedQualitySummary}
                </p>
              ) : null}

              <p className="rounded-lg border border-slate-200 bg-slate-50 px-4 py-3 text-[12px] font-semibold text-slate-600">
                커리큘럼 연동(동기화): 제목 · 준비물 · 활동 방법 — 원본 제목 <strong>{selected.curriculum.title}</strong>
              </p>

              <div className="space-y-5">
                <section className="rounded-lg border border-slate-200 bg-white p-5">
                  <h3 className="mb-4 flex items-center gap-2 text-[15px] font-black"><Sparkles size={16} />기본</h3>
                  <div className="grid gap-4">
                    <Field label="제목"><TextInput value={form.title} onChange={(e) => updateForm('title', e.target.value)} /></Field>
                    <Field label="영상 첨부 링크 (URL)"><TextInput value={form.videoUrl} placeholder={selected.curriculum.url ?? 'curriculum.url fallback 없음'} onChange={(e) => updateForm('videoUrl', e.target.value)} /></Field>
                  </div>
                </section>

                <section className="rounded-lg border border-slate-200 bg-white p-5">
                  <h3 className="mb-4 text-[15px] font-black">분류</h3>
                  <div className="grid gap-4">
                    <Field label="테마">
                      <ChoiceChips options={THEME_OPTIONS} selected={csvToList(form.theme)} onChange={(next) => updateForm('theme', listToCsvValue(next))} />
                    </Field>
                    <Field label="대상">
                      <ChoiceChips options={TARGET_OPTIONS} selected={parseMasterTargets(form.target)} onChange={(next) => updateForm('target', serializeMasterTags(next))} />
                    </Field>
                    <Field label="기능">
                      <ChoiceChips
                        options={BODY_FUNCTION_OPTIONS}
                        selected={mergeStrengthBodyFunctions(selectedTaggedOptions(form.tags, TAG_PREFIX.bodyFunction))}
                        onChange={(next) => updateForm('tags', updateTaggedOptions(form.tags, TAG_PREFIX.bodyFunction, next))}
                      />
                    </Field>
                    <Field label="움직임">
                      <ChoiceChips
                        options={MOVEMENT_OPTIONS}
                        selected={selectedTaggedOptions(form.tags, TAG_PREFIX.movement)}
                        onChange={(next) => updateForm('tags', updateTaggedOptions(form.tags, TAG_PREFIX.movement, next))}
                      />
                    </Field>
                    <Field label="공간">
                      <ChoiceChips options={SPACE_OPTIONS} selected={parseMasterSpaces(form.space)} onChange={(next) => updateForm('space', serializeMasterTags(next))} />
                    </Field>
                    <Field label="인원 구성">
                      <ChoiceChips
                        options={[...MASTER_PARTICIPANT_FORMATS]}
                        selected={getMasterParticipantFormat(csvToList(form.tags)) ? [getMasterParticipantFormat(csvToList(form.tags))] : []}
                        onChange={(next) => {
                          const selectedParticipant = next.at(-1) ?? '';
                          updateForm('tags', listToCsvValue(setMasterParticipantFormatTag(csvToList(form.tags), selectedParticipant)));
                        }}
                      />
                    </Field>
                  </div>
                </section>

                <section className="rounded-lg border border-slate-200 bg-white p-5">
                  <h3 className="mb-4 flex items-center gap-2 text-[15px] font-black"><ShieldAlert size={16} />사전 체크리스트</h3>
                  <div className="grid gap-4">
                    <Field label="준비물"><TextArea rows={6} value={form.equipment} onChange={(e) => updateForm('equipment', e.target.value)} /></Field>
                    <Field label="초기 교구 세팅 (이미지)">
                      <SetupImageUpload
                        curriculumId={selected.curriculum.id}
                        value={form.setupImageUrl}
                        onChange={(next) => updateForm('setupImageUrl', next)}
                        onRemove={() => void removeSetupImage()}
                      />
                    </Field>
                    <Field label="수업 스크립트"><TextArea rows={6} value={form.coachScript} onChange={(e) => updateForm('coachScript', e.target.value)} /></Field>
                    <Field label="사전 교육"><TextArea rows={5} value={form.briefingNotes} onChange={(e) => updateForm('briefingNotes', e.target.value)} /></Field>
                  </div>
                </section>

                <section className="rounded-lg border border-slate-200 bg-white p-5">
                  <h3 className="mb-4 flex items-center gap-2 text-[15px] font-black"><CheckCircle2 size={16} />수업 운영</h3>
                  <div className="grid gap-4">
                    <Field label="활동 방법"><TextArea rows={12} value={form.steps} onChange={(e) => updateForm('steps', e.target.value)} /></Field>
                    <Field label="변형 방법"><TextArea rows={8} value={form.variations} onChange={(e) => updateForm('variations', e.target.value)} /></Field>
                  </div>
                </section>

                <details className="rounded-lg border border-slate-200 bg-white p-5">
                  <summary className="cursor-pointer text-[15px] font-black text-slate-900">미리보기</summary>
                  <div className="mt-4">
                    <PreviewPane item={selected} form={form} />
                  </div>
                </details>
              </div>
            </div>
          ) : (
            <div className="flex h-full items-center justify-center text-[13px] font-bold text-slate-400">
              편집할 프로그램을 선택하세요.
            </div>
          )}
        </section>
      </main>
      </>
      )}
    </div>
  );
}

'use client';
import React from 'react';

export type BodyActionId =
  | 'rightFoot'
  | 'leftFoot'
  | 'rightHand'
  | 'leftHand'
  | 'bothHands'
  | 'bothFeet';

export const BODY_ACTION_LABELS: Record<BodyActionId, string> = {
  rightFoot: '오른발',
  leftFoot: '왼발',
  rightHand: '오른손',
  leftHand: '왼손',
  bothHands: '양손',
  bothFeet: '양발',
};

const BODY_ACTION_IMAGE_SRC = {
  rightFoot: '/spomove/training/body-actions/right-foot.webp',
  leftFoot: '/spomove/training/body-actions/left-foot.webp',
  rightHand: '/spomove/training/body-actions/right-hand.webp',
  leftHand: '/spomove/training/body-actions/left-hand.webp',
  bothHands: '/spomove/training/body-actions/both-hands.webp',
  bothFeet: '/spomove/training/body-actions/both-feet.webp',
} satisfies Record<BodyActionId, string>;

const BODY_ACTION_IMAGE_URLS = Object.values(BODY_ACTION_IMAGE_SRC);

let didPreloadBodyActionImages = false;

function preloadBodyActionImages() {
  if (didPreloadBodyActionImages || typeof window === 'undefined') return;
  didPreloadBodyActionImages = true;

  const load = () => {
    for (const src of BODY_ACTION_IMAGE_URLS) {
      const image = new Image();
      image.decoding = 'async';
      image.src = src;
      void image.decode?.().catch(() => {});
    }
  };

  const browserWindow = window;
  if ('requestIdleCallback' in browserWindow) {
    browserWindow.requestIdleCallback(load, { timeout: 1000 });
  } else {
    globalThis.setTimeout(load, 0);
  }
}

preloadBodyActionImages();

export function BodyActionIcon({
  actionId,
  style,
}: {
  actionId: BodyActionId;
  style?: React.CSSProperties;
}) {
  return (
    <img
      src={BODY_ACTION_IMAGE_SRC[actionId]}
      alt={BODY_ACTION_LABELS[actionId]}
      width={512}
      height={512}
      decoding="async"
      loading="eager"
      draggable={false}
      style={{
        width: '100%',
        height: '100%',
        objectFit: 'contain',
        display: 'block',
        userSelect: 'none',
        pointerEvents: 'none',
        mixBlendMode: 'multiply',
        ...style,
      }}
    />
  );
}

'use client';

import React from 'react';
import { PAD_POSITIONS } from '@/app/lib/admin/constants/padGrid';
import type { FruitSlide, VariantPanelContent } from '../lib/signals';
import { resolveStroopArrowMovementCue } from '../lib/resolveStroopArrowMoveTarget';
import { resolveStroopWordMovementCue } from '../lib/resolveStroopWordMoveTarget';
import { BodyActionIcon, BODY_ACTION_LABELS, type BodyActionId } from './BodyActionIcons';

/** 설치 글꼴만 사용한다. 웹폰트를 나중에 바꾸면 시작 순간 다른 글꼴이 보였다 교체된다. */
const STROOP_WORD_FONT_FAMILY = '"Malgun Gothic", "Apple SD Gothic Neo", "Noto Sans KR", sans-serif';

function variantCells(panel: VariantPanelContent | null | undefined): FruitSlide[] {
  if (!panel) return [];
  return panel.cells ?? (panel.slide ? [panel.slide] : []);
}

function clampUnitPosition(value: number, safeRatio: number) {
  return Math.min(1 - safeRatio, Math.max(safeRatio, value));
}

function arrowRotationDeg(arrowId: string | undefined): number {
  if (arrowId === 'up') return 0;
  if (arrowId === 'up-right') return 45;
  if (arrowId === 'right') return 90;
  if (arrowId === 'down-right') return 135;
  if (arrowId === 'down') return 180;
  if (arrowId === 'down-left') return 225;
  if (arrowId === 'left') return 270;
  if (arrowId === 'up-left') return 315;
  return -90;
}

/** postimg 등 **직링크**만 사용 (next/image·최적화 경로 없음 — 환경마다 깨지는 문제 방지). */
function VariantFruitImg({ slide }: { slide: FruitSlide }) {
  return (
    <img
      src={slide.imageUrl}
      alt=""
      draggable={false}
      loading="eager"
      decoding="async"
      style={{
        width: '100%',
        height: '100%',
        flex: 1,
        minHeight: 0,
        objectFit: 'cover',
        objectPosition: 'center',
        display: 'block',
        userSelect: 'none',
        pointerEvents: 'none',
      }}
    />
  );
}

export const SignalDisplay = React.memo(function SignalDisplay({
  signal,
  animKey,
  bodyLabelMode = 'easy',
}: {
  signal: Record<string, unknown> | null;
  animKey: number;
  bodyLabelMode?: 'easy' | 'hard';
}) {
  if (!signal) return null;
  const type = signal.type as string;
  const content = signal.content as Record<string, unknown> | undefined;
  const C: React.CSSProperties = { position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center' };

  if (type === 'think_quad') {
    const colorId = (content?.colorId as string) ?? '';
    const fillHex = (content?.fillHex as string) ?? '#EF4444';
    const symbol = content?.symbol as string | undefined;
    const textColor = (content?.textColor as string) ?? '#fff';
    const imageUrl = (content?.imageUrl as string | null | undefined) ?? null;
    return (
      <div
        key={animKey}
        className="signal-blink"
        style={{
          position: 'absolute',
          inset: 0,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          padding: 'clamp(0.75rem, 5vmin, 2.5rem)',
          boxSizing: 'border-box',
        }}
      >
        <div
          style={{
            width: '100%',
            height: '100%',
            maxWidth: 'min(96vw, 96vh)',
            maxHeight: 'min(96vw, 96vh)',
            aspectRatio: '1',
            display: 'grid',
            gridTemplateColumns: '1fr 1fr',
            gridTemplateRows: '1fr 1fr',
            gap: 'clamp(6px, 1.2vw, 14px)',
            minHeight: 0,
          }}
        >
          {PAD_POSITIONS.map((row, ri) =>
            row.map((padColorId, ci) => {
              const isActive = padColorId === colorId;
              return (
                <div
                  key={`${ri}-${ci}`}
                  style={{
                    borderRadius: 12,
                    border: '1px solid rgba(148,163,184,0.55)',
                    backgroundColor: isActive ? fillHex : 'rgba(255,255,255,0.15)',
                    minHeight: 0,
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                  }}
                >
                  {isActive && imageUrl ? (
                    <img
                      src={imageUrl}
                      alt=""
                      style={{ width: '100%', height: '100%', objectFit: 'cover', borderRadius: 10, display: 'block' }}
                      draggable={false}
                    />
                  ) : isActive && symbol ? (
                    <span style={{ fontSize: 'clamp(40px, 11vmin, 100px)', lineHeight: 1, color: textColor, opacity: 0.45, userSelect: 'none' }}>
                      {symbol}
                    </span>
                  ) : null}
                </div>
              );
            })
          )}
        </div>
      </div>
    );
  }



  if (type === 'think_quad_body') {
    const cells = (content?.cells as { colorId: string; fillHex: string; bodyActionId: BodyActionId }[] | undefined) ?? [];
    const cellMap = new Map(cells.map(c => [c.colorId, c]));
    return (
      <div
        key={animKey}
        className="signal-blink"
        style={{
          position: 'absolute',
          inset: 0,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          padding: 'clamp(0.75rem, 5vmin, 2.5rem)',
          boxSizing: 'border-box',
        }}
      >
        <div
          style={{
            width: '100%',
            height: '100%',
            maxWidth: 'min(96vw, 96vh)',
            maxHeight: 'min(96vw, 96vh)',
            aspectRatio: '1',
            display: 'grid',
            gridTemplateColumns: '1fr 1fr',
            gridTemplateRows: '1fr 1fr',
            gap: 'clamp(6px, 1.2vw, 14px)',
            minHeight: 0,
          }}
        >
          {PAD_POSITIONS.map((row, ri) =>
            row.map((padColorId, ci) => {
              const cell = cellMap.get(padColorId);
              const isActive = !!cell;
              const bodyActionId = cell?.bodyActionId ?? 'bothFeet';
              const label = isActive ? BODY_ACTION_LABELS[bodyActionId] : '';
              return (
                <div
                  key={`${ri}-${ci}`}
                  style={{
                    borderRadius: 12,
                    border: '1px solid rgba(148,163,184,0.55)',
                    backgroundColor: isActive ? cell!.fillHex : 'rgba(255,255,255,0.15)',
                    minHeight: 0,
                    display: 'flex',
                    flexDirection: 'column',
                    alignItems: 'center',
                    justifyContent: 'center',
                    gap: 'clamp(2px, 0.6vmin, 6px)',
                  }}
                >
                  {isActive ? (
                    <>
                      <div
                        style={{
                          width: '58%',
                          height: '58%',
                          minWidth: 0,
                          minHeight: 0,
                        }}
                        aria-label={label}
                      >
                        <BodyActionIcon actionId={bodyActionId} />
                      </div>
                      {bodyLabelMode !== 'easy' && (
                        <span
                          style={{
                            fontSize: 'clamp(16px, 3.8vmin, 32px)',
                            fontWeight: 800,
                            color: '#000',
                            letterSpacing: '0.04em',
                            lineHeight: 1,
                            userSelect: 'none',
                          }}
                        >
                          {label}
                        </span>
                      )}
                      <span className="sr-only">{label}</span>
                    </>
                  ) : null}
                </div>
              );
            })
          )}
        </div>
      </div>
    );
  }

  if (type === 'full_color' || type === 'gonogo_color') {
    const overlayNumber = (content as { overlayNumber?: number } | undefined)?.overlayNumber;
    return (
      <div key={animKey} className="signal-blink" style={C}>
        {content && (
          <div style={{ position: 'absolute', inset: 0, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: '0.5rem', userSelect: 'none', overflow: 'hidden' }}>
            {typeof content.imageUrl === 'string' && content.imageUrl ? (
              <div
                style={{
                  position: 'absolute',
                  inset: 'clamp(6px, 1.4vmin, 12px)',
                  border: '1px solid #000',
                  background: '#000',
                  overflow: 'hidden',
                }}
              >
                <img
                  src={content.imageUrl as string}
                  alt=""
                  draggable={false}
                  loading="eager"
                  style={{ width: '100%', height: '100%', objectFit: 'contain', display: 'block', userSelect: 'none' }}
                />
              </div>
            ) : (
              <div style={{ fontSize: 'clamp(80px,18vw,180px)', lineHeight: 1, color: content.textColor as string, opacity: 0.35 }}>{content.symbol as string}</div>
            )}
          </div>
        )}
        {overlayNumber != null && (
          <div style={{
            position: 'absolute',
            inset: 0,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            pointerEvents: 'none',
            userSelect: 'none',
          }}>
            <span style={{
              fontSize: 'clamp(180px, 42vmin, 420px)',
              fontWeight: 800,
              lineHeight: 1,
              color: content?.textColor as string ?? '#fff',
              textShadow: '0 4px 40px rgba(0,0,0,0.35)',
            }}>
              {overlayNumber}
            </span>
          </div>
        )}
      </div>
    );
  }

  if (type === 'gonogo_shape') {
    const shape = content?.shape as 'circle' | 'triangle' | undefined;
    const fill = (content?.fillHex as string) ?? '#F8FAFC';
    const box = 'min(52vmin, 78vw)';
    return (
      <div key={animKey} className="signal-blink" style={C}>
        <div
          style={{
            width: box,
            height: box,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            boxSizing: 'border-box',
          }}
        >
          {shape === 'circle' ? (
            <div style={{ width: '100%', height: '100%', borderRadius: '50%', background: fill, boxShadow: '0 12px 48px rgba(0,0,0,0.35)' }} />
          ) : (
            <svg viewBox="0 0 100 100" style={{ width: '100%', height: '100%', display: 'block', filter: 'drop-shadow(0 12px 48px rgba(0,0,0,0.35))' }} aria-hidden>
              <polygon points="50,8 94,92 6,92" fill={fill} />
            </svg>
          )}
        </div>
      </div>
    );
  }

  if (type === 'gonogo_action') {
    const kind = content?.kind as string | undefined;
    if (kind === 'arrow') {
      const arrowId = content?.arrowId as string | undefined;
      const rot = arrowId === 'up' ? 0 : arrowId === 'right' ? 90 : arrowId === 'down' ? 180 : -90;
      return (
        <div key={animKey} className="signal-blink" style={C}>
          <svg
            viewBox="0 0 100 130"
            preserveAspectRatio="xMidYMid meet"
            style={{
              width: 'clamp(9rem, 58vmin, min(98vw, 98vh))',
              height: 'clamp(9rem, 58vmin, min(98vw, 98vh))',
              filter: 'drop-shadow(0 10px 48px rgba(0,0,0,0.5))',
            }}
            aria-hidden
          >
            <g transform={`rotate(${rot} 50 67)`}>
              <path
                d="M 50 8 L 88 62 L 62 62 L 62 122 L 38 122 L 38 62 L 12 62 Z"
                fill="#FFFFFF"
                stroke="rgba(255,255,255,0.26)"
                strokeWidth={5}
                strokeLinejoin="round"
              />
            </g>
          </svg>
        </div>
      );
    }
    return (
      <div key={animKey} className="signal-blink" style={{ ...C, flexDirection: 'column', gap: '0.35rem' }}>
        <div
          style={{
            fontSize: 'clamp(100px, 28vw, 300px)',
            lineHeight: 1,
            fontWeight: 800,
            color: '#F87171',
            textShadow: '0 6px 40px rgba(0,0,0,0.45)',
            userSelect: 'none',
          }}
        >
          ✕
        </div>
        <div style={{ fontSize: 'clamp(22px,5vw,40px)', color: 'rgba(255,255,255,0.85)', fontWeight: 700 }}>멈춤</div>
      </div>
    );
  }

  if (type === 'gonogo_dual') {
    const shape = content?.shape as 'circle' | 'triangle' | undefined;
    const fill = '#FFFFFF';
    const box = 'min(48vmin, 72vw)';
    return (
      <div key={animKey} className="signal-blink" style={C}>
        <div
          style={{
            width: box,
            height: box,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            boxSizing: 'border-box',
          }}
        >
          {shape === 'circle' ? (
            <div style={{ width: '100%', height: '100%', borderRadius: '50%', background: fill, boxShadow: '0 12px 48px rgba(0,0,0,0.25)' }} />
          ) : (
            <svg viewBox="0 0 100 100" style={{ width: '100%', height: '100%', display: 'block', filter: 'drop-shadow(0 12px 48px rgba(0,0,0,0.25))' }} aria-hidden>
              <polygon points="50,8 94,92 6,92" fill={fill} />
            </svg>
          )}
        </div>
      </div>
    );
  }

  if (type === 'arrow') {
    const arrowId = content?.id as string | undefined;
    const fillHex = (content?.fillHex as string | undefined) ?? '#FFFFFF';
    const rot = arrowRotationDeg(arrowId);
    return (
      <div key={animKey} className="signal-blink" style={C}>
        <svg
          className="signal-arrow-reset-pulse"
          viewBox="0 0 100 130"
          preserveAspectRatio="xMidYMid meet"
          style={{
            width: 'clamp(9rem, 58vmin, min(98vw, 98vh))',
            height: 'clamp(9rem, 58vmin, min(98vw, 98vh))',
          }}
          aria-hidden
        >
          <g transform={`rotate(${rot} 50 67)`}>
            <path
              d="M 50 8 L 88 62 L 62 62 L 62 122 L 38 122 L 38 62 L 12 62 Z"
              fill={fillHex}
              stroke="rgba(255,255,255,0.26)"
              strokeWidth={5}
              strokeLinejoin="round"
            />
          </g>
        </svg>
      </div>
    );
  }

  if (type === 'basic_variant_color') {
    const panels = (content?.panels as VariantPanelContent[] | undefined) ?? [];
    const variantTier = Number(content?.variantTier ?? 0);
    const columns = variantTier === 4 ? 3 : panels.length === 2 ? 2 : 3;
    const pad = 'clamp(12px, 2.5vw, 40px)';
    const outer: React.CSSProperties = {
      position: 'absolute',
      inset: 0,
      display: 'grid',
      gridTemplateColumns: `repeat(${columns}, minmax(0, 1fr))`,
      alignItems: 'stretch',
      justifyContent: 'stretch',
      background: '#0F172A',
      padding: pad,
      gap: 'clamp(6px, 1.2vw, 14px)',
      boxSizing: 'border-box',
    };

    /* 2분할/3분할/랜덤분할 공용: 패널당 이미지 1장만, 스택 없음 */
    return (
      <div key={animKey} className="signal-blink" style={outer}>
        {panels.map((panel, idx) => {
          const cells = variantCells(panel);
          const slide = cells[0];
          return (
            <div
              key={idx}
              style={{
                minWidth: 0,
                minHeight: 0,
                height: '100%',
                borderRadius: 12,
                border: '1px solid rgba(148,163,184,0.55)',
                background: slide
                  ? ((slide.imageUrl ?? '').trim() ? '#000' : slide.color.bg)
                  : 'rgba(255,255,255,0.14)',
                overflow: 'hidden',
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                justifyContent: 'center',
              }}
            >
              {slide
                ? ((slide.imageUrl ?? '').trim()
                  ? <VariantFruitImg slide={slide} />
                  : (
                    <span
                      style={{
                        fontSize: 'clamp(72px, 16vw, 180px)',
                        lineHeight: 1,
                        color: slide.color.text,
                        opacity: 0.38,
                        userSelect: 'none',
                      }}
                    >
                      {slide.color.symbol}
                    </span>
                  ))
                : null}
            </div>
          );
        })}
      </div>
    );
  }

  if (type === 'number')
    return (
      <div key={animKey} className="signal-blink" style={C}>
        <div style={{ fontFamily: 'var(--spm-font-display)', fontSynthesis: 'none', fontSize: 'clamp(180px,38vw,400px)', color: '#fff', lineHeight: 1, fontWeight: 800, textShadow: '0 4px 60px rgba(0,0,0,0.5)' }}>{content?.label as string}</div>
      </div>
    );

  if (type === 'stroop_arrow') {
    const arrowId = content?.arrowId as string | undefined;
    const fillHex = (content?.fillHex as string | undefined) ?? '#FFFFFF';
    const pageBg = (signal.bg as string) ?? '#000000';
    const lightPage =
      pageBg === '#FFFFFF' ||
      pageBg.toLowerCase() === '#fff' ||
      pageBg === '#FACC15' ||
      (pageBg.startsWith('#') &&
        (() => {
          const h = pageBg.slice(1);
          if (h.length !== 6) return false;
          const R = parseInt(h.slice(0, 2), 16);
          const G = parseInt(h.slice(2, 4), 16);
          const B = parseInt(h.slice(4, 6), 16);
          return (0.299 * R + 0.587 * G + 0.114 * B) / 255 > 0.55;
        })());
    const strokeCol = lightPage ? 'rgba(0,0,0,0.28)' : 'rgba(255,255,255,0.22)';
    const rot = arrowId === 'up' ? 0 : arrowId === 'right' ? 90 : arrowId === 'down' ? 180 : -90;
    const movementCue = resolveStroopArrowMovementCue(content);
    return (
      <div key={animKey} className="signal-blink" style={C}>
        {movementCue ? (
          <div
            style={{
              position: 'absolute',
              top: 'max(1.25rem, env(safe-area-inset-top))',
              left: 0,
              right: 0,
              display: 'flex',
              justifyContent: 'center',
              pointerEvents: 'none',
              zIndex: 2,
            }}
          >
            <div
              style={{
                padding: '0.45rem 1.1rem',
                borderRadius: '999px',
                background: 'rgba(15,23,42,0.78)',
                color: '#fff',
                fontSize: 'clamp(1.05rem, 3.2vmin, 1.65rem)',
                fontWeight: 800,
                letterSpacing: '-0.02em',
                boxShadow: '0 8px 24px rgba(0,0,0,0.28)',
              }}
            >
              {movementCue}
            </div>
          </div>
        ) : null}
        <svg
          viewBox="0 0 100 130"
          preserveAspectRatio="xMidYMid meet"
          style={{
            /* 화면(뷰포트 짧은 변) 기준 약 50% — 풀스크린 훈련에서 한눈에 보이도록 */
            width: 'clamp(7.5rem, 50vmin, min(92vw, 92vh))',
            height: 'clamp(7.5rem, 50vmin, min(92vw, 92vh))',
            filter: lightPage ? 'drop-shadow(0 8px 32px rgba(0,0,0,0.12))' : 'drop-shadow(0 10px 48px rgba(0,0,0,0.5))',
          }}
          aria-hidden
        >
          {/* 꼬리(몸통)를 viewBox 세로 확장으로 실제로 길게: 머리·날개는 유지, 몸통만 아래로 연장 */}
          <g transform={`rotate(${rot} 50 67)`}>
            <path
              d="M 50 8 L 88 62 L 62 62 L 62 122 L 38 122 L 38 62 L 12 62 Z"
              fill={fillHex}
              stroke={strokeCol}
              strokeWidth={1}
              strokeLinejoin="round"
            />
          </g>
        </svg>
      </div>
    );
  }

  if (type === 'stroop') {
    const pageBg = (signal.bg as string) ?? '#000000';
    const light =
      pageBg === '#FFFFFF' ||
      pageBg.toLowerCase() === '#fff' ||
      (pageBg.startsWith('#') &&
        (() => {
          const h = pageBg.slice(1);
          if (h.length !== 6) return false;
          const R = parseInt(h.slice(0, 2), 16);
          const G = parseInt(h.slice(2, 4), 16);
          const B = parseInt(h.slice(4, 6), 16);
          return (0.299 * R + 0.587 * G + 0.114 * B) / 255 > 0.55;
        })());
    return (
      <div key={animKey} className="signal-blink" style={C}>
        {(() => {
          const wordCue = resolveStroopWordMovementCue(content);
          if (!wordCue) return null;
          return (
            <div
              style={{
                position: 'absolute',
                top: 'max(1.25rem, env(safe-area-inset-top))',
                left: 0,
                right: 0,
                display: 'flex',
                justifyContent: 'center',
                pointerEvents: 'none',
                zIndex: 2,
              }}
            >
              <div
                style={{
                  padding: '0.45rem 1.1rem',
                  borderRadius: '999px',
                  background: 'rgba(15,23,42,0.78)',
                  color: '#fff',
                  fontSize: 'clamp(1.05rem, 3.2vmin, 1.65rem)',
                  fontWeight: 800,
                  letterSpacing: '-0.02em',
                  boxShadow: '0 8px 24px rgba(0,0,0,0.28)',
                }}
              >
                {wordCue}
              </div>
            </div>
          );
        })()}
        <div
          style={{
            fontFamily: STROOP_WORD_FONT_FAMILY,
            fontSize: 'clamp(123px, 28.5vw, 375px)',
            fontWeight: 700,
            color: content?.textHex as string,
            lineHeight: 0.95,
            letterSpacing: '0.02em',
            textAlign: 'center',
            WebkitTextStroke: light ? '1px rgba(15,23,42,0.14)' : '1px rgba(255,255,255,0.08)',
            textShadow: light
              ? '0 3px 0 rgba(15,23,42,0.10), 0 8px 18px rgba(0,0,0,0.16)'
              : '0 4px 0 rgba(0,0,0,0.28), 0 0 70px rgba(0,0,0,0.58)',
          }}
        >
          {content?.word as string}
        </div>
      </div>
    );
  }

  if (type === 'dual_num') {
    const col = content?.color as { text?: string } | undefined;
    const tc = col?.text ?? '#fff';
    return (
      <div key={animKey} className="signal-blink" style={C}>
        <div style={{ fontFamily: 'var(--spm-font-display)', fontSynthesis: 'none', fontSize: 'clamp(180px,38vw,400px)', color: tc, lineHeight: 1, fontWeight: 800, textShadow: '0 4px 60px rgba(0,0,0,0.35)' }}>{(content?.number as { label?: string })?.label}</div>
      </div>
    );
  }

  if (type === 'dual_color_arrow') {
    const arr = content?.arrow as { icon?: string } | undefined;
    return (
      <div key={animKey} className="signal-blink" style={C}>
        <div
          style={{
            fontSize: 'clamp(150px, 36vw, 380px)',
            color: '#0a0a0a',
            lineHeight: 1,
            fontWeight: 800,
          }}
        >
          {arr?.icon}
        </div>
      </div>
    );
  }

  if (type === 'task_switch') {
    const cueTier = typeof content?.cueTier === 'number' ? content.cueTier : 1;
    const rule = (content?.rule as string) ?? 'color';
    const stimulusKind = (content?.stimulusKind as string) ?? 'color';
    const ruleTextK = rule === 'color' ? '색' : rule === 'position' ? '위치' : '반대로';
    const frameTier3: React.CSSProperties =
      cueTier === 3
        ? rule === 'color'
          ? { border: '21px solid rgba(255,255,255,0.94)', borderRadius: '1.35rem', boxSizing: 'border-box' as const }
          : rule === 'position'
            ? { border: '21px dashed rgba(255,255,255,0.9)', borderRadius: '1.35rem', boxSizing: 'border-box' as const }
            : { border: '36px double rgba(255,255,255,0.92)', borderRadius: '1.35rem', boxSizing: 'border-box' as const }
        : {};
    const stimulus =
      stimulusKind === 'color' ? (
        <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '0.5rem', userSelect: 'none' }}>
          <div style={{ fontSize: 'clamp(80px,18vw,180px)', lineHeight: 1, color: content?.textColor as string, opacity: 0.35 }}>{content?.symbol as string}</div>
        </div>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center' }}>
          <div style={{ fontSize: 'clamp(120px, 30vw, 320px)', color: '#fff', lineHeight: 1, fontWeight: 800, textShadow: '0 4px 50px rgba(0,0,0,0.4)' }}>{content?.icon as string}</div>
        </div>
      );
    return (
      <div
        key={animKey}
        className="signal-blink"
        style={{
          position: 'absolute',
          inset: 0,
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'stretch',
          justifyContent: 'flex-start',
          padding: 'clamp(8px, 2vw, 20px)',
          boxSizing: 'border-box',
        }}
      >
        {cueTier === 1 && (
          <div
            style={{
              textAlign: 'center',
              padding: '0.6rem 0 1rem',
              fontSize: 'clamp(4.8rem, 19vw, 8.2rem)',
              fontWeight: 800,
              color: 'rgba(255,255,255,0.98)',
              textShadow: '0 3px 18px rgba(0,0,0,0.45)',
              letterSpacing: '0.14em',
            }}
          >
            {ruleTextK}
          </div>
        )}
        {cueTier === 2 && (
          <div style={{ textAlign: 'center', padding: '0.35rem 0 0.75rem', fontSize: 'clamp(9rem, 33vw, 15rem)', lineHeight: 1 }}>
            {rule === 'color' ? '🎨' : rule === 'position' ? '📍' : '⇄'}
          </div>
        )}
        <div
          style={{
            flex: 1,
            minHeight: 0,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            padding: cueTier === 3 ? 'clamp(10px, 2vmin, 20px)' : 0,
            ...frameTier3,
          }}
        >
          {stimulus}
        </div>
      </div>
    );
  }

  if (type === 'flanker_row') {
    const circles = (content?.circles as { bg: string; id: string; text?: string; label?: string; imageUrl?: string | null }[] | undefined) ?? [];
    const sizeMultsRaw = content?.sizeMults as number[] | undefined;
    const hasVariedSizes =
      Array.isArray(sizeMultsRaw) &&
      sizeMultsRaw.length === circles.length &&
      sizeMultsRaw.length > 0;
    /** 4번: grow 비율로 크기 차등. 1~3번: 균등. %·vmin 혼합 calc는 부모 너비 미확정 시 0이 되어 원이 안 보일 수 있어 사용하지 않음 */
    const mults = hasVariedSizes
      ? sizeMultsRaw!.map((m) => Math.max(0.06, m))
      : circles.map(() => 1);
    const gap = hasVariedSizes ? 'clamp(0px, 0.18vmin, 2px)' : 'clamp(6px, 1.5vmin, 14px)';
    const layout = content?.layout as string | undefined;
    const renderCircleInner = (cell: { bg: string; text?: string; label?: string; imageUrl?: string | null }) => {
      const img = (cell.imageUrl ?? '').trim();
      if (img) {
        return (
          <img
            src={img}
            alt=""
            draggable={false}
            style={{
              width: '100%',
              height: '100%',
              objectFit: 'cover',
              borderRadius: '50%',
              display: 'block',
              pointerEvents: 'none',
              userSelect: 'none',
            }}
          />
        );
      }
      return cell.label ?? '';
    };
    if (layout === 'nestedCircles') {
      const outerSize = 'min(78vmin, 78vw)';
      return (
        <div
          key={animKey}
          className="signal-blink"
          style={{
            position: 'absolute',
            inset: 0,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            padding: 'clamp(10px, 2vw, 22px)',
            boxSizing: 'border-box',
            overflow: 'hidden',
          }}
        >
          <div
            style={{
              position: 'relative',
              width: outerSize,
              height: outerSize,
              maxWidth: '100%',
              maxHeight: '100%',
            }}
          >
            {circles.map((cell, i) => {
              const m = Math.max(0.12, sizeMultsRaw?.[i] ?? mults[i] ?? 1);
              const labelScale = circles.length === 5 ? 5.8 : 7.2;
              return (
                <div
                  key={i}
                  style={{
                    position: 'absolute',
                    left: '50%',
                    top: '50%',
                    width: `${m * 100}%`,
                    height: `${m * 100}%`,
                    transform: 'translate(-50%, -50%)',
                    borderRadius: '50%',
                    background: (cell.imageUrl ?? '').trim() ? '#000' : cell.bg,
                    border: 'clamp(2px, 0.45vmin, 5px) solid rgba(2,6,23,0.86)',
                    boxShadow: '0 12px 30px rgba(0,0,0,0.42), inset 0 0 0 2px rgba(255,255,255,0.18)',
                    filter: (cell.imageUrl ?? '').trim() ? undefined : 'saturate(1.28) contrast(1.08)',
                    color: cell.text ?? '#0F172A',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    fontWeight: 950,
                    fontSize: `clamp(1rem, ${Math.max(1.2, m * labelScale)}vmin, 6rem)`,
                    lineHeight: 1,
                    zIndex: i + 1,
                    overflow: 'hidden',
                  }}
                >
                  {renderCircleInner(cell)}
                </div>
              );
            })}
          </div>
        </div>
      );
    }
    return (
      <div
        key={animKey}
        className="signal-blink"
        style={{
          position: 'absolute',
          inset: 0,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          padding: hasVariedSizes ? 'clamp(0px, 0.2vw, 3px)' : 'clamp(8px, 2vw, 20px)',
          boxSizing: 'border-box',
          minWidth: 0,
          overflow: 'hidden',
        }}
      >
        <div
          style={{
            width: '100%',
            maxWidth: '100%',
            minWidth: 0,
            display: 'flex',
            flexDirection: 'row',
            alignItems: 'center',
            justifyContent: 'center',
            flexWrap: 'nowrap',
            gap,
            boxSizing: 'border-box',
          }}
        >
          {circles.map((cell, i) => (
            <div
              key={i}
              style={{
                flex: hasVariedSizes && circles.length === 3 ? '0 0 auto' : `${mults[i] ?? 1} 1 0`,
                width:
                  hasVariedSizes && circles.length === 3
                    ? `min(${(mults[i] ?? 1) * 58}vmin, ${(mults[i] ?? 1) * 58}vw)`
                    : hasVariedSizes && circles.length === 5
                      ? `min(${(mults[i] ?? 1) * 42}vmin, ${(mults[i] ?? 1) * 42}vw)`
                    : undefined,
                minWidth:
                  hasVariedSizes && circles.length === 3
                    ? `min(${(mults[i] ?? 1) * 12}vmin, ${(mults[i] ?? 1) * 12}vw)`
                    : hasVariedSizes && circles.length === 5
                      ? `min(${Math.max(0.04, mults[i] ?? 1) * 10}vmin, ${Math.max(0.04, mults[i] ?? 1) * 10}vw)`
                    : 'clamp(6px, 2.2vmin, 28px)',
                maxWidth:
                  hasVariedSizes && circles.length === 3
                    ? `min(${(mults[i] ?? 1) * 58}vmin, ${(mults[i] ?? 1) * 58}vw)`
                    : hasVariedSizes && circles.length === 5
                      ? `min(${(mults[i] ?? 1) * 42}vmin, ${(mults[i] ?? 1) * 42}vw)`
                    : hasVariedSizes
                      ? 'min(38vmin, 46vw)'
                      : 'min(30vmin, 24vw)',
                aspectRatio: '1',
                flexShrink: 1,
                borderRadius: '50%',
                background: (cell.imageUrl ?? '').trim() ? '#000' : cell.bg,
                boxSizing: 'border-box',
                boxShadow: '0 4px 20px rgba(0,0,0,0.25)',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                color: cell.text ?? '#0F172A',
                fontWeight: 800,
                fontSize: hasVariedSizes ? 'clamp(1.3rem, 9vmin, 8rem)' : 'clamp(2rem, 11vmin, 9rem)',
                lineHeight: 1,
                overflow: 'hidden',
              }}
            >
              {renderCircleInner(cell)}
            </div>
          ))}
        </div>
      </div>
    );
  }

  if (type === 'flanker_arrows') {
    const arrows = (content?.arrows as { id: string; fillHex?: string }[] | undefined) ?? [];
    const centerIndex = typeof content?.centerIndex === 'number' ? content.centerIndex : 2;
    const sizeMultsRaw = content?.sizeMults as number[] | undefined;
    const hasVariedSizes =
      Array.isArray(sizeMultsRaw) &&
      sizeMultsRaw.length === arrows.length &&
      sizeMultsRaw.length > 0;
    const columnWeights =
      arrows.length > 0
        ? arrows
            .map((_, i) => {
              const weight = hasVariedSizes ? Math.max(0.18, sizeMultsRaw![i] ?? 1) : i === centerIndex ? 1.14 : 1;
              return `${weight.toFixed(2)}fr`;
            })
            .join(' ')
        : '1fr';
    return (
      <div
        key={animKey}
        className="signal-blink"
        style={{
          position: 'absolute',
          inset: 0,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          padding: 'clamp(4px, 1vw, 12px)',
          boxSizing: 'border-box',
          overflow: 'hidden',
        }}
      >
        <div
          style={{
            width: 'min(98vw, 1800px)',
            maxWidth: '100%',
            maxHeight: '88dvh',
            display: 'grid',
            gridTemplateColumns: columnWeights,
            alignItems: 'center',
            justifyContent: 'center',
            /* viewBox가 칸 밖으로 안 넘치므로, 분리만 될 최소 간격 */
            gap: 'clamp(8px, 1.8vmin, 22px)',
            boxSizing: 'border-box',
            overflow: 'visible',
          }}
        >
          {arrows.map((a, i) => {
            const rot = a.id === 'up' ? 0 : a.id === 'right' ? 90 : a.id === 'down' ? 180 : -90;
            const fill = a.fillHex ?? '#FFFFFF';
            const isCenter = i === centerIndex;
            return (
              <div
                key={i}
                style={{
                  minWidth: 0,
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  overflow: 'hidden',
                  boxSizing: 'border-box',
                }}
              >
                {/* 정사각 viewBox: 좌·우 회전 시 옆 칸 침범 방지. maxWidth ≈ 이전 대비 2배 */}
                <svg
                  viewBox="0 0 130 130"
                  preserveAspectRatio="xMidYMid meet"
                  style={{
                    width: '100%',
                    height: 'auto',
                    maxWidth: hasVariedSizes ? '100%' : isCenter ? 'min(100%, 56vmin)' : 'min(100%, 52vmin)',
                    maxHeight: 'min(85dvh, 56vmin)',
                    flex: '0 0 auto',
                    opacity: isCenter ? 1 : 0.92,
                    filter: isCenter ? 'drop-shadow(0 0 18px rgba(255,255,255,0.32))' : undefined,
                    display: 'block',
                  }}
                  aria-hidden
                >
                  <g transform={`rotate(${rot} 65 65)`}>
                    {/* 여백을 줄여 같은 칸 안에서 글리프를 더 크게 */}
                    <g transform="translate(65 65) scale(1.14) translate(-65 -65)">
                      <path
                        d="M 65 12 L 103 66 L 77 66 L 77 118 L 53 118 L 53 66 L 27 66 Z"
                        fill={fill}
                        stroke="rgba(255,255,255,0.26)"
                        strokeWidth={4.4}
                        strokeLinejoin="round"
                      />
                    </g>
                  </g>
                </svg>
              </div>
            );
          })}
        </div>
      </div>
    );
  }

  if (type === 'simon_arrow') {
    type ArrowItem = {
      arrowId?: string;
      fillHex?: string;
      posX?: number;
      posY?: number;
    };
    const rawItems = Array.isArray(content?.items) ? (content.items as ArrowItem[]) : null;
    const items: ArrowItem[] =
      rawItems && rawItems.length > 0
        ? rawItems
        : [
            {
              arrowId: content?.arrowId as string | undefined,
              fillHex: content?.fillHex as string | undefined,
              posX: typeof content?.posX === 'number' ? content.posX : 0.5,
              posY: typeof content?.posY === 'number' ? content.posY : 0.5,
            },
          ];
    return (
      <div key={animKey} style={{ position: 'absolute', inset: 0, pointerEvents: 'none' }}>
        {items.map((item, idx) => {
          const safe = items.length > 1 ? 0.17 : 0.21;
          const posX = clampUnitPosition(typeof item.posX === 'number' ? item.posX : 0.5, safe);
          const posY = clampUnitPosition(typeof item.posY === 'number' ? item.posY : 0.5, safe);
          const arrowId = item.arrowId;
          const fillHex = item.fillHex ?? '#FFFFFF';
          const rot = arrowId === 'up' ? 0 : arrowId === 'right' ? 90 : arrowId === 'down' ? 180 : -90;
          return (
            <div
              key={`sa-${idx}`}
              className="signal-blink"
              style={{
                position: 'absolute',
                left: `${posX * 100}%`,
                top: `${posY * 100}%`,
                transform: 'translate(-50%, -50%)',
                width: items.length > 1 ? 'min(26vw, 26vh)' : 'min(34vw, 34vh)',
                height: items.length > 1 ? 'min(26vw, 26vh)' : 'min(34vw, 34vh)',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                boxSizing: 'border-box',
              }}
            >
              <svg
                viewBox="0 0 100 130"
                preserveAspectRatio="xMidYMid meet"
                style={{
                  width: '100%',
                  height: '100%',
                  display: 'block',
                  filter: 'drop-shadow(0 8px 44px rgba(0,0,0,0.45))',
                }}
                aria-hidden
              >
                <g transform={`rotate(${rot} 50 67)`}>
                  <path
                    d="M 50 8 L 88 62 L 62 62 L 62 122 L 38 122 L 38 62 L 12 62 Z"
                    fill={fillHex}
                    stroke="rgba(255,255,255,0.24)"
                    strokeWidth={6}
                    strokeLinejoin="round"
                  />
                </g>
              </svg>
            </div>
          );
        })}
      </div>
    );
  }

  if (type === 'simon_shape') {
    type ShapeItem = {
      shape?: 'circle' | 'triangle' | 'square' | null;
      fillHex?: string;
      symbol?: string;
      textColor?: string;
      imageUrl?: string | null;
      posX?: number;
      posY?: number;
    };
    const rawItems = Array.isArray(content?.items) ? (content.items as ShapeItem[]) : null;
    const items: ShapeItem[] =
      rawItems && rawItems.length > 0
        ? rawItems
        : [
            {
              shape: content?.shape as ShapeItem['shape'],
              fillHex: (content?.fillHex as string) ?? '#EF4444',
              symbol: content?.symbol as string | undefined,
              textColor: (content?.textColor as string) ?? '#fff',
              imageUrl: (content?.imageUrl as string | null | undefined) ?? null,
              posX: typeof content?.posX === 'number' ? content.posX : 0.5,
              posY: typeof content?.posY === 'number' ? content.posY : 0.5,
            },
          ];
    const size = items.length > 1 ? 'min(18vw, 18vh)' : 'min(24vw, 24vh)';
    return (
      <div key={animKey} style={{ position: 'absolute', inset: 0, pointerEvents: 'none' }}>
        {items.map((item, idx) => {
          const shape = item.shape;
          const fillHex = item.fillHex ?? '#EF4444';
          const symbol = item.symbol;
          const textColor = item.textColor ?? '#fff';
          const imageUrl = item.imageUrl ?? null;
          const safe = items.length > 1 ? 0.12 : 0.14;
          const posX = clampUnitPosition(typeof item.posX === 'number' ? item.posX : 0.5, safe);
          const posY = clampUnitPosition(typeof item.posY === 'number' ? item.posY : 0.5, safe);
          const common: React.CSSProperties = {
            width: '100%',
            height: '100%',
            background: fillHex,
            flexShrink: 0,
          };
          const frameStyle: React.CSSProperties = {
            position: 'absolute',
            left: `${posX * 100}%`,
            top: `${posY * 100}%`,
            transform: 'translate(-50%, -50%)',
            width: size,
            height: size,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            boxSizing: 'border-box',
            overflow: 'hidden',
            borderRadius: shape === 'square' ? '12%' : '50%',
            border: imageUrl ? `3px solid ${fillHex}` : undefined,
            boxShadow: imageUrl ? '0 8px 36px rgba(0,0,0,0.45)' : undefined,
            background: imageUrl ? '#000' : undefined,
          };
          return (
            <div key={`ss-${idx}`} className="signal-blink" style={frameStyle}>
              {imageUrl ? (
                <VariantFruitImg
                  slide={{
                    imageUrl,
                    color: { id: '', name: '', bg: fillHex, text: textColor, symbol: symbol ?? '' },
                  }}
                />
              ) : shape === 'circle' ? (
                <div style={{ ...common, borderRadius: '50%' }} />
              ) : shape === 'square' ? (
                <div style={{ ...common, borderRadius: '6%' }} />
              ) : (
                <svg viewBox="0 0 100 100" style={{ width: '100%', height: '100%', display: 'block' }} aria-hidden>
                  <polygon points="50,6 94,94 6,94" fill={fillHex} />
                </svg>
              )}
            </div>
          );
        })}
      </div>
    );
  }

  return null;
});

'use client';

import { useCallback, useEffect, useState } from 'react';
import { createPortal } from 'react-dom';
import { StudentModal } from './StudentModal';
import { StudentManageScreen } from './StudentManageScreen';
import { useStudents } from '../hooks/useStudents';

const SPOKEDU_PROMO_BANNERS = [
  '/spokedu/spokedu-promo-banner-1.png',
  '/spokedu/spokedu-promo-banner.png',
] as const;

const HERO_ANIM_CSS = `
@keyframes spomoveCatalogHeroFadeUp {
  from { opacity: 0; transform: translateY(14px); }
  to { opacity: 1; transform: translateY(0); }
}
.spomove-catalog-hero-fadein {
  animation: spomoveCatalogHeroFadeUp 0.55s cubic-bezier(0.22,1,0.36,1) both;
}
@media (prefers-reduced-motion: reduce) {
  .spomove-catalog-hero-fadein { animation: none; opacity: 1; transform: none; }
}
`;

/**
 * MemoryGameApp 홈 상단과 동일한 브랜딩·학생 선택·PLAY/THINK/FLOW·헤드라인 블록.
 * SPOMOVE Training 카탈로그(/admin/spomove/training) 상단에서 사용.
 */
export function SpomoveCatalogHero() {
  const { students, add: addStudent, remove: removeStudent, rename: renameStudent } = useStudents();
  const [selectedStudentId, setSelectedStudentId] = useState<string | null>(null);
  const [showStudentModal, setShowStudentModal] = useState(false);
  const [showStudentManage, setShowStudentManage] = useState(false);
  const [bannerLightboxOpen, setBannerLightboxOpen] = useState(false);
  const [bannerMounted, setBannerMounted] = useState(false);
  const [activeBannerIndex, setActiveBannerIndex] = useState(0);
  const [theme] = useState(() =>
    typeof window !== 'undefined' ? localStorage.getItem('spokedu_theme') || 'light' : 'light',
  );

  useEffect(() => {
    setBannerMounted(true);
  }, []);

  const closeBannerLightbox = useCallback(() => setBannerLightboxOpen(false), []);
  const activeBannerSrc = SPOKEDU_PROMO_BANNERS[activeBannerIndex];
  const showPreviousBanner = () => {
    setActiveBannerIndex((current) => (current - 1 + SPOKEDU_PROMO_BANNERS.length) % SPOKEDU_PROMO_BANNERS.length);
  };
  const showNextBanner = () => {
    setActiveBannerIndex((current) => (current + 1) % SPOKEDU_PROMO_BANNERS.length);
  };

  useEffect(() => {
    if (!bannerLightboxOpen) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') closeBannerLightbox();
    };
    window.addEventListener('keydown', onKey);
    const prev = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => {
      window.removeEventListener('keydown', onKey);
      document.body.style.overflow = prev;
    };
  }, [bannerLightboxOpen, closeBannerLightbox]);

  useEffect(() => {
    if (typeof document !== 'undefined') document.documentElement.setAttribute('data-theme', theme);
    if (typeof window !== 'undefined') localStorage.setItem('spokedu_theme', theme);
  }, [theme]);

  return (
    <div
      style={{
        position: 'relative',
        overflow: 'hidden',
        background: '#080C14',
        fontFamily: 'var(--spm-font-body)',
        color: '#fff',
        borderBottom: '1px solid rgba(255,255,255,0.08)',
      }}
    >
      <style>{HERO_ANIM_CSS}</style>
      <div
        aria-hidden
        style={{
          position: 'absolute',
          top: '-25%',
          left: '-8%',
          width: 'min(55vw, 520px)',
          height: 'min(55vw, 520px)',
          borderRadius: '50%',
          background: 'radial-gradient(circle, rgba(249,115,22,0.10) 0%, transparent 70%)',
          pointerEvents: 'none',
        }}
      />
      <div
        aria-hidden
        style={{
          position: 'absolute',
          bottom: '-20%',
          right: '-12%',
          width: 'min(50vw, 480px)',
          height: 'min(50vw, 480px)',
          borderRadius: '50%',
          background: 'radial-gradient(circle, rgba(59,130,246,0.08) 0%, transparent 70%)',
          pointerEvents: 'none',
        }}
      />
      <div
        style={{
          maxWidth: 960,
          margin: '0 auto',
          padding: 'clamp(1.25rem,4vw,2rem) clamp(1rem,4vw,1.5rem) clamp(1.35rem,4vw,1.85rem)',
          position: 'relative',
          boxSizing: 'border-box',
        }}
      >
        <div
          className="spomove-catalog-hero-fadein"
          style={{
            margin: '0 auto',
            width: '100%',
            maxWidth: 1120,
            padding: 'clamp(1.1rem,3vw,1.5rem) clamp(1rem,3vw,1.4rem)',
            borderRadius: 18,
            border: '1px solid rgba(255,255,255,0.09)',
            background: 'linear-gradient(180deg, rgba(249,115,22,0.11) 0%, rgba(255,255,255,0.03) 24%, rgba(255,255,255,0.01) 100%)',
            boxShadow: '0 10px 28px rgba(0,0,0,0.35)',
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            textAlign: 'center',
            gap: 'clamp(0.45rem,1.6vw,0.7rem)',
          }}
        >
          <div
            style={{
              position: 'relative',
              margin: 0,
              padding: 0,
              width: '100%',
              maxWidth: 'min(100%, 920px)',
              borderRadius: 12,
              overflow: 'hidden',
              lineHeight: 0,
              boxShadow: '0 8px 24px rgba(0,0,0,0.4)',
            }}
          >
            <button
              type="button"
              onClick={() => setBannerLightboxOpen(true)}
              aria-label={`${activeBannerIndex + 1}번 SPOKEDU 배너 전체 화면으로 보기`}
              style={{
                margin: 0,
                padding: 0,
                border: 'none',
                background: 'transparent',
                cursor: 'zoom-in',
                width: '100%',
                display: 'block',
                lineHeight: 0,
              }}
            >
              <img
                src={activeBannerSrc}
                alt={`${activeBannerIndex + 1}번 SPOKEDU 홍보 배너`}
                width={1600}
                height={900}
                style={{ width: '100%', height: 'auto', display: 'block' }}
                loading="eager"
                decoding="async"
              />
            </button>
            <button type="button" onClick={showPreviousBanner} aria-label="이전 배너" style={bannerArrowStyle('left')}>
              ‹
            </button>
            <button type="button" onClick={showNextBanner} aria-label="다음 배너" style={bannerArrowStyle('right')}>
              ›
            </button>
          </div>
          <div aria-label="배너 선택" style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
            {SPOKEDU_PROMO_BANNERS.map((src, index) => (
              <button
                key={src}
                type="button"
                onClick={() => setActiveBannerIndex(index)}
                aria-label={`${index + 1}번 배너 보기`}
                aria-current={activeBannerIndex === index ? 'true' : undefined}
                style={{
                  width: activeBannerIndex === index ? 22 : 8,
                  height: 8,
                  padding: 0,
                  border: 0,
                  borderRadius: 999,
                  background: activeBannerIndex === index ? '#F97316' : 'rgba(255,255,255,0.28)',
                  cursor: 'pointer',
                  transition: 'width 160ms ease, background 160ms ease',
                }}
              />
            ))}
          </div>
        </div>
      </div>

      {showStudentModal && (
        <StudentModal
          students={students}
          selectedId={selectedStudentId}
          onSelect={(id) => {
            setSelectedStudentId(id);
            setShowStudentModal(false);
          }}
          onClose={() => setShowStudentModal(false)}
          onManage={() => {
            setShowStudentModal(false);
            setShowStudentManage(true);
          }}
        />
      )}
      {showStudentManage && (
        <div
          style={{
            position: 'fixed',
            inset: 0,
            zIndex: 250,
            overflow: 'auto',
            background: '#080C14',
          }}
        >
          <StudentManageScreen
            students={students}
            onAdd={addStudent}
            onRemove={removeStudent}
            onRename={renameStudent}
            onBack={() => setShowStudentManage(false)}
          />
        </div>
      )}

      {bannerMounted && bannerLightboxOpen
        ? createPortal(
            <div
              role="dialog"
              aria-modal="true"
              aria-label="SPOKEDU 배너 전체 화면 — 화면을 누르거나 Esc로 닫기"
              style={{
                position: 'fixed',
                inset: 0,
                zIndex: 200000,
                margin: 0,
                padding: 0,
                boxSizing: 'border-box',
                width: '100vw',
                height: '100dvh',
                maxWidth: '100vw',
                maxHeight: '100dvh',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                background: '#020617',
                cursor: 'zoom-out',
              }}
              onClick={closeBannerLightbox}
            >
              <img
                src={activeBannerSrc}
                alt=""
                width={1600}
                height={900}
                style={{
                  width: '100vw',
                  height: '100dvh',
                  maxWidth: '100vw',
                  maxHeight: '100dvh',
                  objectFit: 'contain',
                  objectPosition: 'center',
                  display: 'block',
                  pointerEvents: 'none',
                  userSelect: 'none',
                }}
                loading="eager"
                decoding="async"
                draggable={false}
              />
            </div>,
            document.body,
          )
        : null}
    </div>
  );
}

function bannerArrowStyle(side: 'left' | 'right') {
  return {
    position: 'absolute' as const,
    top: '50%',
    [side]: 12,
    transform: 'translateY(-50%)',
    width: 42,
    height: 42,
    padding: 0,
    border: '1px solid rgba(255,255,255,0.32)',
    borderRadius: '50%',
    background: 'rgba(2,6,23,0.62)',
    color: '#fff',
    fontSize: 31,
    lineHeight: '36px',
    cursor: 'pointer',
    backdropFilter: 'blur(6px)',
  };
}

'use client';

import { useState, useEffect, useRef } from 'react';
import { createPortal } from 'react-dom';
import { getSupabaseBrowserClient } from '@/app/lib/supabase/browser';
import { useSpomoveVariantSlidesForTraining } from '../hooks/useSpomoveVariantFruitSlidesForTraining';
import {
  SPOMOVE_COLOR_THEME_LABELS,
  SPOMOVE_THEMED_PACK_BY_THEME,
  type SpomoveColorThemeId,
} from '../lib/spomoveVariantThemeConfig';
import { VARIANT_FRUIT_SLOT_LABELS, SPOMOVE_VARIANT_PACK_ID } from '../lib/variantFruitAssets';

const BG = '#0b0b0b';
const CARD = '#181818';
const BORDER = 'rgba(255,255,255,0.09)';
const TEXT = 'rgba(255,255,255,0.88)';
const MUTED = 'rgba(255,255,255,0.38)';
const ACCENT = '#3B82F6';

type AppendixTheme = Exclude<SpomoveColorThemeId, 'color' | 'mix'>;
const APPENDIX_THEMES: AppendixTheme[] = ['fruit', 'animal', 'food', 'nature', 'vehicle'];

function getDefaultLabels(theme: AppendixTheme): string[] {
  if (theme === 'fruit') return [...VARIANT_FRUIT_SLOT_LABELS];
  return [...SPOMOVE_THEMED_PACK_BY_THEME[theme].slotLabels];
}

function getPackId(theme: AppendixTheme): string {
  if (theme === 'fruit') return SPOMOVE_VARIANT_PACK_ID;
  return SPOMOVE_THEMED_PACK_BY_THEME[theme].packId;
}

function getPackName(theme: AppendixTheme): string {
  if (theme === 'fruit') return 'SPOMOVE 연상 색지각 과일';
  return SPOMOVE_THEMED_PACK_BY_THEME[theme].packName;
}

async function loadStoredLabels(theme: AppendixTheme): Promise<string[] | null> {
  const supabase = getSupabaseBrowserClient();
  const { data } = await supabase
    .from('think_asset_packs')
    .select('assets_json')
    .eq('id', getPackId(theme))
    .maybeSingle();
  const raw = data?.assets_json as { slotLabels?: unknown } | null;
  const stored = raw?.slotLabels;
  if (Array.isArray(stored) && stored.length > 0 && stored.every((s) => typeof s === 'string')) {
    return stored as string[];
  }
  return null;
}

async function saveStoredLabels(theme: AppendixTheme, labels: string[]): Promise<string | null> {
  const packId = getPackId(theme);
  const supabase = getSupabaseBrowserClient();
  const { data: existing } = await supabase
    .from('think_asset_packs')
    .select('assets_json')
    .eq('id', packId)
    .maybeSingle();
  const existingJson = (existing?.assets_json ?? {}) as Record<string, unknown>;

  const res = await fetch('/api/admin/think-asset-pack', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    credentials: 'same-origin',
    body: JSON.stringify({
      id: packId,
      name: getPackName(theme),
      theme: 'iiwarmup',
      assets_json: { ...existingJson, slotLabels: labels },
    }),
  });
  const body = (await res.json().catch(() => ({}))) as { error?: string };
  if (!res.ok) return body.error ?? res.statusText;
  return null;
}

function CategoryContent({ theme }: { theme: AppendixTheme }) {
  const { slides, status } = useSpomoveVariantSlidesForTraining(theme);
  const [labels, setLabels] = useState<string[]>(() => getDefaultLabels(theme));
  const [editingIdx, setEditingIdx] = useState<number | null>(null);
  const [editValue, setEditValue] = useState('');
  const [saving, setSaving] = useState(false);
  const [saveMsg, setSaveMsg] = useState<string | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const userEditedRef = useRef(false);
  const loadGenRef = useRef(0);

  useEffect(() => {
    const gen = ++loadGenRef.current;
    userEditedRef.current = false;
    setEditingIdx(null);
    const defaults = getDefaultLabels(theme);
    void loadStoredLabels(theme).then((stored) => {
      if (loadGenRef.current !== gen || userEditedRef.current) return;
      setLabels(stored ? defaults.map((def, i) => stored[i] ?? def) : defaults);
    });
  }, [theme]);

  const startEdit = (i: number, currentLabel: string) => {
    setEditingIdx(i);
    setEditValue(currentLabel);
    setTimeout(() => inputRef.current?.select(), 0);
  };

  const commitEdit = () => {
    if (editingIdx === null) return;
    const next = [...labels];
    next[editingIdx] = editValue.trim() || (getDefaultLabels(theme)[editingIdx] ?? '');
    userEditedRef.current = true;
    setLabels(next);
    setEditingIdx(null);
  };

  const handleSave = async () => {
    const nextLabels =
      editingIdx === null
        ? labels
        : labels.map((label, i) =>
            i === editingIdx ? editValue.trim() || (getDefaultLabels(theme)[i] ?? label) : label,
          );
    if (editingIdx !== null) {
      userEditedRef.current = true;
      setLabels(nextLabels);
      setEditingIdx(null);
    }
    setSaving(true);
    setSaveMsg(null);
    const err = await saveStoredLabels(theme, nextLabels);
    setSaving(false);
    setSaveMsg(err ? `오류: ${err}` : '저장됨 ✓');
    setTimeout(() => setSaveMsg(null), 2500);
  };

  const items = labels
    .map((label, i) => ({ label, imageUrl: (slides[i]?.imageUrl ?? '').trim(), index: i }))
    .filter((item) => item.imageUrl);

  return (
    <>
      {/* 이미지 그리드 — 남은 공간 전부 */}
      <div style={{ flex: 1, minHeight: 0, padding: '1.5rem 2rem 0', overflow: 'hidden' }}>
        {status === 'loading' && (
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', height: '100%', color: MUTED, fontSize: '1rem' }}>
            로딩 중…
          </div>
        )}
        {status !== 'loading' && items.length === 0 && (
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', height: '100%', color: MUTED, fontSize: '1rem' }}>
            업로드된 이미지가 없습니다.
          </div>
        )}
        {items.length > 0 && (
          <div
            style={{
              display: 'grid',
              gridTemplateColumns: 'repeat(4, 1fr)',
              gridAutoRows: '1fr',
              gap: '1.5rem',
              height: '100%',
            }}
          >
            {items.map(({ label, imageUrl, index }) => (
              <div
                key={index}
                style={{
                  display: 'flex',
                  flexDirection: 'column',
                  alignItems: 'center',
                  gap: '0.65rem',
                  minHeight: 0,
                }}
              >
                {/* 이미지 — 셀 높이에서 이름 영역을 뺀 나머지 차지 */}
                <div
                  style={{
                    flex: 1,
                    minHeight: 0,
                    width: '100%',
                    borderRadius: '1.1rem',
                    overflow: 'hidden',
                    border: `1px solid ${BORDER}`,
                    background: CARD,
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                  }}
                >
                  <img
                    src={imageUrl}
                    alt={label}
                    style={{ width: '100%', height: '100%', objectFit: 'contain' }}
                  />
                </div>

                {/* 이름 */}
                {editingIdx === index ? (
                  <input
                    ref={inputRef}
                    value={editValue}
                    onChange={(e) => setEditValue(e.target.value)}
                    onBlur={commitEdit}
                    onKeyDown={(e) => {
                      if (e.key === 'Enter') commitEdit();
                      if (e.key === 'Escape') setEditingIdx(null);
                    }}
                    style={{
                      width: '100%',
                      padding: '0.45rem 0.65rem',
                      borderRadius: '0.55rem',
                      border: `1.5px solid ${ACCENT}`,
                      background: '#1e293b',
                      color: TEXT,
                      fontSize: '1.45rem',
                      fontWeight: 700,
                      fontFamily: 'inherit',
                      textAlign: 'center',
                      outline: 'none',
                      boxSizing: 'border-box',
                      flexShrink: 0,
                    }}
                    autoFocus
                  />
                ) : (
                  <button
                    type="button"
                    onClick={() => startEdit(index, label)}
                    title="클릭하여 이름 수정"
                    style={{
                      background: 'rgba(255,255,255,0.04)',
                      border: '1px solid transparent',
                      color: TEXT,
                      fontSize: '1.45rem',
                      fontWeight: 700,
                      cursor: 'pointer',
                      textAlign: 'center',
                      fontFamily: 'inherit',
                      padding: '0.3rem 0.65rem',
                      borderRadius: '0.5rem',
                      width: '100%',
                      flexShrink: 0,
                      lineHeight: 1.3,
                    }}
                    onMouseEnter={(e) => {
                      (e.currentTarget as HTMLButtonElement).style.borderColor = BORDER;
                      (e.currentTarget as HTMLButtonElement).style.background = 'rgba(255,255,255,0.07)';
                    }}
                    onMouseLeave={(e) => {
                      (e.currentTarget as HTMLButtonElement).style.borderColor = 'transparent';
                      (e.currentTarget as HTMLButtonElement).style.background = 'rgba(255,255,255,0.04)';
                    }}
                  >
