/** lesson-plans-sessions API와 동일한 KST 주간(월 00:00 ~ 일 23:59) UTC 구간 */
function getKstWeekRangeFromYmd(dateYmd: string): { start: Date; end: Date } {
  const KST_OFFSET = 9 * 60 * 60 * 1000;
  const anchorMs = new Date(`${dateYmd}T12:00:00+09:00`).getTime();
  const nowKST = new Date(anchorMs + KST_OFFSET);
  const dayOfWeek = nowKST.getUTCDay();
  const daysFromMonday = (dayOfWeek + 6) % 7;
  const startKST = new Date(nowKST);
  startKST.setUTCDate(nowKST.getUTCDate() - daysFromMonday);
  startKST.setUTCHours(0, 0, 0, 0);
  const endKST = new Date(startKST);
  endKST.setUTCDate(startKST.getUTCDate() + 6);
  endKST.setUTCHours(23, 59, 59, 999);
  return {
    start: new Date(startKST.getTime() - KST_OFFSET),
    end: new Date(endKST.getTime() - KST_OFFSET),
  };
}

function formatKstWeekRangeLabel(start: Date, end: Date): string {
  const opt: Intl.DateTimeFormatOptions = {
    timeZone: 'Asia/Seoul',
    month: 'numeric',
    day: 'numeric',
    weekday: 'short',
  };
  return `${new Intl.DateTimeFormat('ko-KR', opt).format(start)} ~ ${new Intl.DateTimeFormat('ko-KR', opt).format(end)}`;
}

/** 피드백 조회용 YYYY-MM-DD에 로컬 달력 기준 일 수를 더함 */
function addDaysToYmd(ymd: string, deltaDays: number): string {
  const [y, m, d] = ymd.split('-').map((v) => parseInt(v, 10));
  if (!Number.isFinite(y) || !Number.isFinite(m) || !Number.isFinite(d)) return ymd;
  const base = new Date(y, m - 1, d);
  base.setDate(base.getDate() + deltaDays);
  const yy = base.getFullYear();
  const mm = String(base.getMonth() + 1).padStart(2, '0');
  const dd = String(base.getDate()).padStart(2, '0');
  return `${yy}-${mm}-${dd}`;
}

/** 피드백 검수 탭: 카드·필터용 empty | done | verified (fetchListData보다 위에 두어 클로저 순서 명확) */
function formatKstSessionDateTime(value: string): string {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return '';
  return new Intl.DateTimeFormat('ko-KR', {
    timeZone: 'Asia/Seoul',
    month: 'numeric',
    day: 'numeric',
    weekday: 'short',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
  }).format(date);
}

function hasExtraTeacher(session: Pick<Session, 'memo' | 'students_text'>): boolean {
  for (const raw of [session.memo, session.students_text]) {
    if (!raw?.includes('EXTRA_TEACHERS:')) continue;
    const { extraTeachers } = parseExtraTeachers(raw);
    if (extraTeachers.some((t) => String(t.id || '').trim())) return true;
  }
  return false;
}

function getSessionStatusForFeedbackReview(session: Session): 'empty' | 'done' | 'verified' {
  return getSessionDisplayStatus({
    ...session,
    feedback_fields: session.feedback_fields ?? parseTemplateToFields(session.students_text || ''),
  });
}

/** Blob을 `download` 속성으로 저장 — `displayNameForDownload`로 만든 한글 파일명 유지 */
function downloadBlobWithFilename(blob: Blob, filename: string): void {
  const objectUrl = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = objectUrl;
  a.download = filename;
  a.rel = 'noopener';
  document.body.appendChild(a);
  a.click();
  a.remove();
  window.setTimeout(() => URL.revokeObjectURL(objectUrl), 15_000);
}

/** `/api/admin/storage/center-session-file`의 MAX_BYTES_PER_CHUNK(3MB)와 동일 */
const CENTER_FILE_CHUNK_BYTES = 3 * 1024 * 1024;

function parseTotalBytesFromContentRangeHeader(cr: string | null): number | null {
  if (!cr) return null;
  const m = cr.trim().match(/\/(\d+)\s*$/);
  if (m) return parseInt(m[1], 10);
  return null;
}

/** 한 청크 + 본문(blob)까지 합쳐서 무한 대기 방지 */
async function fetchCenterSessionFileChunk(
  body: { sessionId: string; fileIndex: number; byteStart: number; byteEnd: number },
  timeoutMs: number,
): Promise<Response> {
  const ctrl = new AbortController();
  const t = window.setTimeout(() => ctrl.abort(), timeoutMs);
  try {
    return await fetch('/api/admin/storage/center-session-file', {
      method: 'POST',
      credentials: 'include',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
      signal: ctrl.signal,
    });
  } finally {
    window.clearTimeout(t);
  }
}

async function blobWithTimeout(res: Response, timeoutMs: number): Promise<Blob> {
  return await Promise.race([
    res.blob(),
    new Promise<never>((_, reject) => {
      window.setTimeout(() => reject(new Error('파일 데이터 수신 시간이 초과되었습니다.')), timeoutMs);
    }),
  ]);
}

/** Vercel 응답 한도 회피용 느린 경로 — 직접 스트리밍 실패 시만 사용 */
async function downloadCenterSessionFileChunked(params: {
  sessionId: string;
  fileIndex: number;
  filename: string;
}): Promise<void> {
  const { sessionId, fileIndex, filename } = params;

  const chunkFetchMs = 120_000;
  const chunkBlobMs = 120_000;

  let offset = 0;
  let total: number | null = null;
  const parts: Blob[] = [];
  let iterations = 0;

  for (;;) {
    iterations += 1;
    if (iterations > 50_000) {
      throw new Error('다운로드 분할 횟수가 비정상적으로 많습니다.');
    }

    const end =
      total === null
        ? offset + CENTER_FILE_CHUNK_BYTES - 1
        : Math.min(offset + CENTER_FILE_CHUNK_BYTES - 1, total - 1);

    let res: Response;
    try {
      res = await fetchCenterSessionFileChunk(
        { sessionId, fileIndex, byteStart: offset, byteEnd: end },
        chunkFetchMs,
      );
    } catch (err: unknown) {
      if (err instanceof DOMException && err.name === 'AbortError') {
        throw new Error('서버 응답이 너무 느립니다. 잠시 후 다시 시도해 주세요.');
      }
      throw err;
    }
    if (!res.ok) {
      const payload = (await res.json().catch(() => ({}))) as { error?: string };
      throw new Error(payload.error || `다운로드 실패 (${res.status})`);
    }

    const parsed = parseTotalBytesFromContentRangeHeader(res.headers.get('content-range'));
    if (parsed !== null) {
      total = parsed;
    }

    const part = await blobWithTimeout(res, chunkBlobMs);
    parts.push(part);
    offset += part.size;

    if (total !== null && offset >= total) {
      break;
    }
    if (part.size === 0) {
      break;
    }
    if (total === null && part.size < CENTER_FILE_CHUNK_BYTES) {
      break;
    }
  }

  downloadBlobWithFilename(new Blob(parts), filename);
}

/**
 * 1) 서버에서 서명 URL만 받고 → 브라우저가 Supabase로 직접 받음 (빠름)
 * 2) CORS 등으로 실패 시 → 기존 청크 프록시 폴백
 */
async function downloadCenterSessionFileAsKoreanName(params: {
  sessionId: string;
  fileIndex: number;
  fileStorageUrl: string;
  centerDocumentNames: string[] | null | undefined;
}): Promise<void> {
  const { sessionId, fileIndex, fileStorageUrl, centerDocumentNames } = params;
  const filenameFallback = displayNameForDownload(fileStorageUrl, fileIndex, centerDocumentNames ?? null);

  const linkRes = await fetch('/api/admin/storage/center-session-file-link', {
    method: 'POST',
    credentials: 'include',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ sessionId, fileIndex }),
  });
  if (!linkRes.ok) {
    const payload = (await linkRes.json().catch(() => ({}))) as { error?: string };
    throw new Error(payload.error || `다운로드 준비 실패 (${linkRes.status})`);
  }
  const json = (await linkRes.json()) as { signedUrl?: string; filename?: string };
  const signedUrl = typeof json.signedUrl === 'string' ? json.signedUrl.trim() : '';
  if (!signedUrl) {
    throw new Error('다운로드 URL을 받지 못했습니다.');
  }
  const filename =
    typeof json.filename === 'string' && json.filename.trim().length > 0 ? json.filename.trim() : filenameFallback;

  const directMs = 15 * 60_000;
  const ctrl = new AbortController();
  const directTimer = window.setTimeout(() => ctrl.abort(), directMs);
  try {
    const blobRes = await fetch(signedUrl, { mode: 'cors', signal: ctrl.signal });
    if (!blobRes.ok) {
      throw new Error(`스토리지 응답 ${blobRes.status}`);
    }
    const blob = await blobWithTimeout(blobRes, directMs);
    downloadBlobWithFilename(blob, filename);
  } catch {
    await downloadCenterSessionFileChunked({ sessionId, fileIndex, filename });
  } finally {
    window.clearTimeout(directTimer);
  }
}

// 피드백 검수 탭
function FeedbackReviewTab({
  coaches,
  excludedAdminCoachIds,
  supabase,
}: {
  coaches: Coach[];
  excludedAdminCoachIds: string[];
  supabase: ReturnType<typeof getSupabaseBrowserClient> | null;
}) {
  const [downloadingCenterFileIndex, setDownloadingCenterFileIndex] = useState<number | null>(null);

  const handleCenterFileOpenOrDownload: MouseEventHandler<HTMLButtonElement> = async (e) => {
    const url = e.currentTarget.dataset.fileUrl ?? '';
    const index = Number(e.currentTarget.dataset.fileIndex ?? '0');
    const sessionId = e.currentTarget.dataset.sessionId ?? '';
    if (!url || !sessionId || !Number.isFinite(index)) return;
    if (e.metaKey || e.ctrlKey || e.shiftKey || e.button !== 0) {
      window.open(url, '_blank', 'noopener,noreferrer');
      return;
    }
    e.preventDefault();
    e.currentTarget.blur();
    if (downloadingCenterFileIndex !== null) return;
    setDownloadingCenterFileIndex(index);
    const centerNames = feedbackFields.center_document_names;
    const wholeMs = 12 * 60_000;
    try {
      await Promise.race([
        downloadCenterSessionFileAsKoreanName({
          sessionId,
          fileIndex: index,
          fileStorageUrl: url,
          centerDocumentNames: centerNames,
        }),
        new Promise<never>((_, reject) => {
          window.setTimeout(
            () => reject(new Error('전체 다운로드 시간이 초과되었습니다. 네트워크를 확인해 주세요.')),
            wholeMs,
          );
        }),
      ]);
    } catch (err) {
      devLogger.warn('[FeedbackReviewTab] center file download', err);
      const msg = err instanceof Error ? err.message : String(err);
      toast.error(msg);
      window.open(url, '_blank', 'noopener,noreferrer');
    } finally {
      setDownloadingCenterFileIndex(null);
    }
  };
  const getSessionTypeLabel = (sessionType: Session['session_type']): string => {
    switch (sessionType) {
      case 'regular_center':
      case 'one_day_center':
      case 'special_lecture':
        return '센터';
      case 'one_day':
        return '원데이';
      case 'one_day_private':
      case 'regular_private':
        return '개인';
      case 'regular_group':
        return '그룹';
      default:
        return '개인';
    }
  };

  const getSessionTypeBadgeLabel = (sessionType: Session['session_type']): string => {
    switch (sessionType) {
      case 'regular_center':
      case 'one_day_center':
      case 'special_lecture':
        return '센터 수업';
      case 'one_day':
        return '원데이 수업';
      case 'one_day_private':
      case 'regular_private':
        return '개인 수업';
      case 'regular_group':
        return '그룹 수업';
      default:
        return '개인 수업';
    }
  };

  const [sessions, setSessions] = useState<Session[]>([]);
  const [feedbackScope, setFeedbackScope] = useState<'private' | 'center'>('private');
  const [selectedCoachId, setSelectedCoachId] = useState('all');
  const [selectedDate, setSelectedDate] = useState(() => {
    const now = new Date();
    const kst = new Date(now.getTime() - now.getTimezoneOffset() * 60000);
    kst.setDate(kst.getDate() - 1);
    return kst.toISOString().split('T')[0];
  });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedEvent, setSelectedEvent] = useState<Session | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [feedbackFields, setFeedbackFields] = useState<FeedbackFields>({});
  const [photoUrls, setPhotoUrls] = useState<string[]>([]);
  const [fileUrls, setFileUrls] = useState<string[]>([]);
  const [zoomedImg, setZoomedImg] = useState<string | null>(null);
  const [statusFilter, setStatusFilter] = useState<'all' | 'empty' | 'done' | 'verified'>('all');
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedSessions, setSelectedSessions] = useState<Set<string>>(new Set());
  const [bulkActionLoading, setBulkActionLoading] = useState(false);
  const [duplicateCheck, setDuplicateCheck] = useState<{ isDuplicate: boolean; similarity?: number; matchedSession?: { title?: string; start_at?: string }; duplicate?: boolean; message?: string } | null>(null);
  const [selectedCenterWeekday, setSelectedCenterWeekday] = useState<number | 'all'>('all');
  const feedbackDateInputRef = useRef<HTMLInputElement>(null);

  const fetchListData = useCallback(async () => {
    setLoading(true);
    setError(null);
    
    try {
      const params = new URLSearchParams({ date: selectedDate, scope: feedbackScope });
      if (selectedCoachId !== 'all') params.set('coachId', selectedCoachId);
      const res = await fetch(`/api/admin/teachers-classes/list?${params.toString()}`, {
        credentials: 'include',
        cache: 'no-store',
      });
      const payload = (await res.json().catch(() => ({}))) as { sessions?: Session[]; error?: string };
      if (!res.ok) throw new Error(payload.error || '데이터를 불러오지 못했습니다.');
      if (payload.sessions) {
        let rows = payload.sessions;
        if (feedbackScope === 'center' && excludedAdminCoachIds.length > 0) {
          rows = rows.filter((s) => !excludedAdminCoachIds.includes(s.created_by) || hasExtraTeacher(s));
        }

        // 검수완료 카드의 링크 복사: iPad/iOS는 클릭 직후 await fetch가 끼면 clipboard가 막히는 경우가 많아,
        // short_code를 목록 단계에서 미리 발급·캐시해 두고 복사 버튼에서는 네트워크 없이 동기 복사만 수행
        const needsShortCode = rows.filter((s) => {
          if (getSessionStatusForFeedbackReview(s) !== 'verified') return false;
          const sc = s.short_code;
          return typeof sc !== 'string' || !/^[A-Z0-9]{6}$/.test(sc);
        });
        const idToCode = new Map<string, string>();
        const chunk = 8;
        for (let i = 0; i < needsShortCode.length; i += chunk) {
          const slice = needsShortCode.slice(i, i + chunk);
          await Promise.all(
            slice.map(async (s) => {
              try {
                const res = await fetch('/api/admin/session-short-code', {
                  method: 'POST',
                  credentials: 'include',
                  headers: { 'Content-Type': 'application/json' },
                  body: JSON.stringify({ sessionId: s.id }),
                });
                if (!res.ok) return;
                const json = (await res.json().catch(() => ({}))) as { shortCode?: string };
                if (typeof json.shortCode === 'string' && /^[A-Z0-9]{6}$/.test(json.shortCode)) {
                  idToCode.set(s.id, json.shortCode);
                }
              } catch (err) {
                devLogger.warn('[FeedbackReviewTab] prefetch short_code', err);
              }
            })
          );
        }
        const enriched = rows.map((s) => {
          let row: Session = { ...s };
          const c = idToCode.get(s.id);
          if (c) row = { ...row, short_code: c };
          const urls = Array.isArray(row.file_url) ? row.file_url : [];
          const isCenter =
            isCenterSessionType(row.session_type);
          if (isCenter && urls.length > 0) {
            const ff = (row.feedback_fields || {}) as FeedbackFields;
            row = {
              ...row,
              feedback_fields: {
                ...ff,
                center_document_names: alignCenterDocumentNamesWithUrls(urls, ff.center_document_names),
              },
            };
          }
          return row;
        });
        setSessions(enriched);
      }
    } catch (err: unknown) {
      devLogger.error('데이터 로드 실패:', err);
      setError(err instanceof Error ? err.message : '데이터를 불러오지 못했습니다.');
    } finally {
      setLoading(false);
    }
  }, [selectedDate, selectedCoachId, feedbackScope, excludedAdminCoachIds]);

  useEffect(() => {
    fetchListData();
  }, [fetchListData]);

  useEffect(() => {
    setSelectedSessions(new Set());
  }, [feedbackScope]);

  const coachFilterOptions = useMemo(
    () =>
      feedbackScope === 'center'
        ? coaches.filter((c) => !excludedAdminCoachIds.includes(c.id))
        : coaches,
    [coaches, feedbackScope, excludedAdminCoachIds],
  );

  useEffect(() => {
    if (
      feedbackScope === 'center' &&
      selectedCoachId !== 'all' &&
      excludedAdminCoachIds.includes(selectedCoachId)
    ) {
      setSelectedCoachId('all');
    }
  }, [feedbackScope, selectedCoachId, excludedAdminCoachIds]);

  const centerWeekRangeText = useMemo(() => {
    const { start, end } = getKstWeekRangeFromYmd(selectedDate);
    return formatKstWeekRangeLabel(start, end);
  }, [selectedDate]);

  const statistics = useMemo(() => {
    const empty = sessions.filter((s) => getSessionStatusForFeedbackReview(s) === 'empty').length;
    const done = sessions.filter((s) => getSessionStatusForFeedbackReview(s) === 'done').length;
    const verified = sessions.filter((s) => getSessionStatusForFeedbackReview(s) === 'verified').length;
    return { empty, done, verified, total: sessions.length };
  }, [sessions]);

  const filteredAndSearchedSessions = useMemo(() => {
    return sessions.filter(s => {
      if (statusFilter !== 'all') {
        const sessionStatus = getSessionStatusForFeedbackReview(s);
        if (sessionStatus !== statusFilter) return false;
      }
      if (searchTerm) {
        const searchLower = searchTerm.toLowerCase();
        const titleMatch = s.title?.toLowerCase().includes(searchLower);
        const coachName = s.users?.name ?? coaches.find((c) => c.id === s.created_by)?.name ?? '';
        const coachMatch = coachName.toLowerCase().includes(searchLower);
        if (!titleMatch && !coachMatch) return false;
      }
      return true;
    });
  }, [sessions, statusFilter, searchTerm, coaches]);

  const centerWeekdayGroups = useMemo(() => {
    const labels = ['월', '화', '수', '목', '금', '토', '일'];
    const { start } = getKstWeekRangeFromYmd(selectedDate);
    return labels.map((label, dayIndex) => {
      const date = new Date(start.getTime() + dayIndex * 24 * 60 * 60 * 1000);
      const sessionsForDay = filteredAndSearchedSessions.filter((session) => {
        const kst = new Date(new Date(session.start_at).getTime() + 9 * 60 * 60 * 1000);
        return (kst.getUTCDay() + 6) % 7 === dayIndex;
      });
      return {
        dayIndex,
        label,
        dateLabel: `${date.getUTCMonth() + 1}.${date.getUTCDate()}`,
        sessions: sessionsForDay,
      };
    });
  }, [filteredAndSearchedSessions, selectedDate]);

  const feedbackListItems = useMemo(() => {
    if (feedbackScope !== 'center') {
      return filteredAndSearchedSessions.map((session) => ({ kind: 'session' as const, session }));
    }
    const visible = selectedCenterWeekday === 'all'
      ? filteredAndSearchedSessions
      : centerWeekdayGroups[selectedCenterWeekday]?.sessions ?? [];
    return visible.map((session) => ({ kind: 'session' as const, session }));
  }, [feedbackScope, filteredAndSearchedSessions, centerWeekdayGroups, selectedCenterWeekday]);

  const toggleSelection = (sessionId: string) => {
    setSelectedSessions(prev => {
      const newSet = new Set(prev);
      if (newSet.has(sessionId)) newSet.delete(sessionId);
      else newSet.add(sessionId);
      return newSet;
    });
  };

  const selectAll = () => {
    const allDone = filteredAndSearchedSessions
      .filter(
        (s) =>
          getSessionStatusForFeedbackReview(s) === 'done' &&
          s.status !== 'postponed' &&
          s.status !== 'cancelled'
      )
      .map(s => s.id);
    setSelectedSessions(new Set(allDone));
  };

  const clearSelection = () => setSelectedSessions(new Set());

  const handleBulkApprove = async () => {
    if (selectedSessions.size === 0) return toast.success('승인할 리포트를 선택해주세요.');
    if (!confirm(`선택한 ${selectedSessions.size}개의 리포트를 일괄 승인합니다.\n승인 전 수업일/중복 경고를 다시 확인했는지 점검해 주세요.`)) return;
    
    setBulkActionLoading(true);
    try {
      const ids = Array.from(selectedSessions);
      const res = await fetch('/api/admin/teachers-classes/bulk-approve', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ids }),
      });
      const data = (await res.json().catch(() => ({}))) as { error?: string };
      if (!res.ok) throw new Error(data.error ?? 'bulk_approve_failed');

      toast.success(`${selectedSessions.size}개의 리포트가 승인되었습니다.`);
      clearSelection();
      fetchListData();
    } catch (error: unknown) {
      toast.error('일괄 승인에 실패했습니다: ' + (error instanceof Error ? error.message : String(error)));
    } finally {
      setBulkActionLoading(false);
    }
  };

  const calculateSimilarity = (text1: string, text2: string): number => {
    const words1 = text1.split(/\s+/).filter(w => w.length > 1);
    const words2 = text2.split(/\s+/).filter(w => w.length > 1);
    if (words1.length === 0 || words2.length === 0) return 0;
    const commonWords = words1.filter(w => words2.includes(w));
    const similarity = (commonWords.length * 2) / (words1.length + words2.length);
    return Math.round(similarity * 100);
  };

  const checkDuplicateFeedback = async (currentSession: Session) => {
    if (!supabase) return { isDuplicate: false };
    if (currentSession.status !== 'finished' && currentSession.status !== 'verified') {
      return { isDuplicate: false };
    }
    if (
      isCenterSessionType(currentSession.session_type)
    ) {
      return { isDuplicate: false };
    }
    try {
      const { data: recentSessions } = await supabase
        .from('sessions')
        .select('id, title, students_text, start_at')
        .eq('created_by', currentSession.created_by)
        .in('status', ['finished', 'verified'])
        .lt('start_at', currentSession.start_at)
        .order('start_at', { ascending: false })
        .limit(5);
      
      if (!recentSessions || recentSessions.length === 0) return { isDuplicate: false };
      
      const currentText = currentSession.students_text || '';
      if (currentText.trim().length < 10) return { isDuplicate: false };
      
      for (const session of recentSessions) {
        const sessionText = session.students_text || '';
        if (sessionText.trim().length < 10) continue;
        
        const similarity = calculateSimilarity(currentText, sessionText);
        if (similarity >= 50) {
          return {
            isDuplicate: true,
            similarity,
            matchedSession: session
          };
        }
      }
      
      return { isDuplicate: false };
    } catch (err) {
      devLogger.error('중복 체크 실패:', err);
      return { isDuplicate: false };
    }
  };

  const openEditModal = async (session: Session) => {
    setSelectedEvent(session);
    const urls = Array.isArray(session.file_url) ? session.file_url : [];
    const isCenter =
      isCenterSessionType(session.session_type);
    let fields: FeedbackFields = session.feedback_fields || parseTemplateToFields(session.students_text || '');
    if (isCenter && urls.length > 0) {
      fields = {
        ...fields,
        center_document_names: alignCenterDocumentNamesWithUrls(urls, fields.center_document_names),
      };
    } else if (!isCenter) {
      const rest = { ...fields };
      delete rest.center_document_names;
      fields = rest;
    }
    setFeedbackFields(fields);
    setPhotoUrls(Array.isArray(session.photo_url) ? session.photo_url : []);
    setFileUrls(urls);
    
    // 중복 체크
    const check = await checkDuplicateFeedback(session);
    setDuplicateCheck(check);
    
    setIsModalOpen(true);
  };

  const handleSave = async (newStatus = 'verified') => {
    if (!supabase || !selectedEvent) return;
    if (newStatus === 'verified') {
      const sessionStart = new Date(selectedEvent.start_at);
      const today = new Date();
      sessionStart.setHours(0, 0, 0, 0);
      today.setHours(0, 0, 0, 0);
      if (sessionStart > today) {
        toast.error('수업일이 아직 지나지 않았습니다. 수업일 이후에 검수 승인해 주세요.');
        return;
      }
    }
    try {
      const updatedText = fieldsToTemplateText(feedbackFields);
      const res = await fetch('/api/admin/teachers-classes/save', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          sessionId: selectedEvent.id,
          status: newStatus,
          students_text: updatedText,
          feedback_fields: feedbackFields,
          photo_url: photoUrls,
          file_url: fileUrls,
        }),
      });
      const data = (await res.json().catch(() => ({}))) as { error?: string };
      if (!res.ok) throw new Error(data.error ?? 'save_failed');

      toast.success(newStatus === 'verified' ? '검수 승인 완료!' : '수정 요청 완료!');
      setIsModalOpen(false);
      fetchListData();
    } catch (error: unknown) {
      toast.error('저장에 실패했습니다: ' + (error instanceof Error ? error.message : String(error)));
    }
  };

  return (
    <>
      {zoomedImg && (
        <div className="fixed inset-0 z-[10000] bg-black/90 backdrop-blur-md flex items-center justify-center p-4 cursor-zoom-out" onClick={() => setZoomedImg(null)}>
          <img src={zoomedImg} className="max-w-full max-h-full object-contain rounded-lg" alt="확대" />
          <button className="absolute top-10 right-10 text-white/50 hover:text-white"><X size={40} /></button>
        </div>
      )}

      <div className="mb-6 space-y-3">
        <div className="flex gap-2 rounded-2xl border border-slate-200 bg-white p-1 shadow-sm">
          <button
            type="button"
            onClick={() => setFeedbackScope('private')}
            className={`min-h-[44px] flex-1 min-w-[8rem] px-4 py-2.5 rounded-xl text-sm font-bold transition-all cursor-pointer ${
              feedbackScope === 'private' ? 'bg-slate-900 text-white' : 'text-slate-400 hover:text-slate-600'
            }`}
          >
            과외 피드백
          </button>
          <button
            type="button"
            onClick={() => setFeedbackScope('center')}
            className={`min-h-[44px] flex-1 min-w-[8rem] px-4 py-2.5 rounded-xl text-sm font-bold transition-all cursor-pointer ${
              feedbackScope === 'center' ? 'bg-slate-900 text-white' : 'text-slate-400 hover:text-slate-600'
            }`}
          >
            센터 피드백
          </button>
        </div>
        <div className="space-y-3 rounded-2xl border border-slate-200 bg-white p-3 shadow-sm">
          <div className="space-y-2">
            <div className="flex items-center gap-2">
              <button
                type="button"
                aria-label={feedbackScope === 'center' ? '이전 주' : '이전 날'}
                title={feedbackScope === 'center' ? '이전 주' : '이전 날'}
                onClick={() =>
                  setSelectedDate((prev) => addDaysToYmd(prev, feedbackScope === 'center' ? -7 : -1))
                }
                className="shrink-0 flex min-h-[44px] min-w-[44px] items-center justify-center rounded-xl bg-slate-100 text-slate-600 hover:bg-slate-200 cursor-pointer transition-colors"
              >
                <ChevronLeft size={20} strokeWidth={2.5} />
              </button>
              <div className="relative min-h-11 min-w-0 flex-1">
                <div className="flex min-h-11 items-center justify-center rounded-xl bg-slate-50 px-3 text-sm font-bold text-slate-800">
                  {new Intl.DateTimeFormat('ko-KR', { timeZone: 'Asia/Seoul', month: 'long', day: 'numeric', weekday: 'short' }).format(new Date(`${selectedDate}T12:00:00+09:00`))}
                </div>
                <input
                  ref={feedbackDateInputRef}
                  id="feedback-review-date"
                  type="date"
                  value={selectedDate}
                  onChange={(e) => setSelectedDate(e.target.value)}
                  aria-label="날짜 선택"
                  className="absolute inset-0 cursor-pointer opacity-0"
                />
              </div>
              <button
                type="button"
                aria-label={feedbackScope === 'center' ? '다음 주' : '다음 날'}
                title={feedbackScope === 'center' ? '다음 주' : '다음 날'}
                onClick={() =>
                  setSelectedDate((prev) => addDaysToYmd(prev, feedbackScope === 'center' ? 7 : 1))
                }
                className="shrink-0 flex min-h-[44px] min-w-[44px] items-center justify-center rounded-xl bg-slate-100 text-slate-600 hover:bg-slate-200 cursor-pointer transition-colors"
              >
                <ChevronRight size={20} strokeWidth={2.5} />
              </button>
            </div>
            {feedbackScope === 'center' ? (
              <p className="text-[11px] text-slate-500 font-bold leading-snug px-1">
                주간 조회 (KST 월요일~일요일): {centerWeekRangeText}
              </p>
            ) : (
              <p className="text-[11px] text-slate-500 font-bold px-1">일간 조회: 선택한 날짜의 수업만</p>
            )}
          </div>
          <select value={selectedCoachId} onChange={(e) => setSelectedCoachId(e.target.value)} className="min-h-11 w-full cursor-pointer rounded-xl bg-slate-50 px-4 py-2 text-sm font-bold outline-none">
            <option value="all">전체 강사</option>
            {coachFilterOptions.map((c) => (
              <option key={c.id} value={c.id}>
                {c.name} 선생님
              </option>
            ))}
          </select>
        </div>
      </div>

      {error && (
        <div className="bg-red-50 border-2 border-red-200 rounded-2xl p-6 mb-8">
          <p className="font-bold text-red-600">{error}</p>
          <button onClick={fetchListData} className="mt-4 px-6 py-2 bg-red-600 text-white rounded-xl font-bold hover:bg-red-500">다시 시도</button>
        </div>
      )}

      {!loading && !error && (
        <>
          <div className="mb-8 space-y-4">
            <div className="grid grid-cols-2 gap-2 sm:flex sm:rounded-2xl sm:border sm:bg-white sm:p-1 sm:shadow-sm">
              {['all', 'empty', 'done', 'verified'].map(filter => (
                <button 
                  key={filter}
                  onClick={() => setStatusFilter(filter as 'all' | 'empty' | 'done' | 'verified')}
                  className={`min-h-11 rounded-xl px-3 py-2 text-sm font-bold transition-all cursor-pointer sm:flex-1 ${
                    statusFilter === filter ? 'bg-slate-900 text-white' : 'bg-white text-slate-500 shadow-sm ring-1 ring-slate-200 hover:text-slate-700 sm:bg-transparent sm:shadow-none sm:ring-0'
                  }`}
                >
                  {filter === 'all' && `전체 (${statistics.total})`}
                  {filter === 'empty' && `미작성 (${statistics.empty})`}
                  {filter === 'done' && `작성완료 (${statistics.done})`}
                  {filter === 'verified' && `검수완료 (${statistics.verified})`}
                </button>
              ))}
            </div>

            <div className="relative">
              <Search className="absolute left-4 top-1/2 transform -translate-y-1/2 text-slate-400" size={20} />
              <input 
                type="text"
                placeholder="수업명 또는 강사명 검색..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-12 pr-4 py-3 bg-white rounded-xl text-sm font-bold outline-none border-2 border-slate-200 focus:border-blue-400"
              />
            </div>

            {statistics.done > 0 && (
              <button onClick={selectAll} className="px-4 py-2 bg-slate-100 text-slate-600 rounded-xl text-xs font-bold hover:bg-slate-200 cursor-pointer">
                작성완료 전체 선택 ({statistics.done}개)
              </button>
            )}
          </div>
        </>
      )}

      {loading ? (
        <div className="py-40 text-center font-black text-slate-300 animate-pulse">Syncing...</div>
      ) : filteredAndSearchedSessions.length === 0 && feedbackScope !== 'center' ? (
        <div className="bg-white rounded-[40px] py-12 md:py-32 text-center border border-dashed border-slate-300">
          <p className="text-slate-400 font-bold">
            {searchTerm || statusFilter !== 'all'
              ? '검색 결과가 없습니다.'
              : `${new Intl.DateTimeFormat('ko-KR', { timeZone: 'Asia/Seoul', month: 'long', day: 'numeric', weekday: 'short' }).format(new Date(`${selectedDate}T12:00:00+09:00`))} 과외 수업이 없습니다.`}
          </p>
        </div>
      ) : (
        <div className="space-y-4">
          {feedbackScope === 'center' && (
            <div className="grid grid-cols-4 gap-1 rounded-2xl border border-slate-200 bg-white p-1.5 shadow-sm md:grid-cols-8">
              {[{ dayIndex: 'all' as const, label: '전체', sessions: filteredAndSearchedSessions }, ...centerWeekdayGroups].map((item) => {
                const selected = selectedCenterWeekday === item.dayIndex;
                return (
                  <button
                    key={String(item.dayIndex)}
                    type="button"
                    onClick={() => setSelectedCenterWeekday(item.dayIndex)}
                    className={`min-h-11 min-w-0 rounded-xl px-1 py-2 text-xs font-bold transition-colors ${selected ? 'bg-slate-900 text-white' : 'text-slate-500 hover:bg-slate-100'}`}
                  >
                    <span className="block truncate">{item.label}</span>
                    <span className={`mt-0.5 block text-[11px] ${selected ? 'text-slate-300' : 'text-slate-400'}`}>{item.sessions.length}</span>
                  </button>
                );
              })}
            </div>
          )}
          <div className="grid grid-cols-1 gap-4 md:grid-cols-3 lg:grid-cols-4">
          {feedbackListItems.map((item) => {
            const s = item.session;
            const sessionStatus = getSessionStatusForFeedbackReview(s);
            const rawStatus = s.status;
            const isSelected = selectedSessions.has(s.id);
            const canSelect =
              sessionStatus === 'done' &&
              rawStatus !== 'postponed' &&
              rawStatus !== 'cancelled';
            const isVerified = sessionStatus === 'verified';
            const isDone = sessionStatus === 'done';
            const time = feedbackScope === 'center'
              ? formatKstSessionDateTime(s.start_at)
              : new Date(s.start_at).toLocaleTimeString('ko-KR', { hour: '2-digit', minute: '2-digit', hour12: false });
            const coachName = s.users?.name || coaches.find(c => c.id === s.created_by)?.name || '강사';

            const cardBadge = (() => {
              if (rawStatus === 'postponed') {
                return { text: '연기', className: 'bg-purple-100 text-purple-700' };
              }
              if (rawStatus === 'cancelled') {
                return { text: '취소', className: 'bg-rose-100 text-rose-700' };
              }
              if (isVerified) {
                return { text: 'DONE', className: 'bg-blue-600 text-white' };
              }
              if (isDone) {
                return { text: 'READY', className: 'bg-emerald-500 text-white' };
              }
              return { text: 'EMPTY', className: 'bg-slate-100 text-slate-400' };
            })();

            return (
              <div key={s.id} className="relative">
                {canSelect && (
                  <div className="absolute top-3 left-3 z-10">
                    <input type="checkbox" checked={isSelected} onChange={() => toggleSelection(s.id)} className="w-4 h-4 cursor-pointer" onClick={(e) => e.stopPropagation()} />
                  </div>
                )}
                <div className={`bg-white rounded-2xl p-4 shadow-sm border-2 ${isSelected ? 'border-blue-500' : 'border-slate-200'} flex flex-col hover:shadow-lg hover:border-blue-300 transition-all cursor-pointer`} onClick={() => openEditModal(s)}>
                  <div className="flex justify-between items-start mb-3">
                    <span className="bg-indigo-50 text-indigo-600 px-2 py-1 rounded-lg text-[10px] font-bold">{time}</span>
                    <span className={`text-[9px] font-bold px-2 py-1 rounded-lg uppercase ${cardBadge.className}`}>
                      {cardBadge.text}
                    </span>
                  </div>
                  <h3 className="text-base font-bold text-slate-900 mb-2 line-clamp-2 text-left leading-tight">{s.title}</h3>
                  <div className="space-y-1 mb-3 text-left">
                    <div className="flex items-center gap-1 text-slate-600 text-xs">
                      <User size={12} /> {coachName}
                    </div>
                    <div className="flex items-center gap-1 text-slate-400 text-[10px]">
                      <MapPin size={10} /> {getSessionTypeLabel(s.session_type)}
                    </div>
                  </div>
                  <div className="mt-auto flex flex-wrap gap-2 items-center">
                    <button 
                      onClick={(e) => { 
                        e.stopPropagation();
                        if (!isVerified) {
                          toast.error('검수 완료된 리포트만 복사 가능합니다.');
                          return;
                        }
                        const origin = getPublicAppOrigin();
                        if (!origin) {
                          toast.error('복사할 사이트 주소를 찾을 수 없습니다.');
                          return;
                        }
                        const shortCode = s.short_code;
                        if (typeof shortCode === 'string' && /^[A-Z0-9]{6}$/.test(shortCode)) {
                          const shortUrl = `${origin}/r/${shortCode}`;
                          if (copyTextToClipboardSync(shortUrl)) {
                            toast.success('링크 복사 완료!');
                            return;
                          }
                          if (typeof navigator !== 'undefined' && typeof navigator.share === 'function') {
                            void navigator
                              .share({ url: shortUrl, title: '학부모 리포트 링크' })
                              .then(() => {
                                toast.success('공유 패널에서 링크를 보내 주세요.');
                              })
                              .catch((shareErr) => {
                                if ((shareErr as { name?: string })?.name === 'AbortError') return;
                                window.prompt(
                                  '자동 복사가 되지 않습니다. 아래 링크를 길게 눌러 복사해 주세요.',
                                  shortUrl
                                );
                              });
                            return;
                          }
                          window.prompt(
                            '자동 복사가 되지 않습니다. 아래 링크를 길게 눌러 복사해 주세요.',
                            shortUrl
                          );
                          return;
                        }
                        toast.info('링크 코드를 불러오는 중입니다. 잠시 후 다시 눌러 주세요.');
                        void fetchListData();
                      }} 
                      className={`flex min-h-[44px] min-w-[44px] items-center justify-center rounded-xl ${isVerified ? 'bg-slate-100 text-slate-600 hover:bg-slate-200' : 'bg-slate-50 text-slate-300 cursor-not-allowed'}`}
                    >
                      <Send size={14} />
                    </button>
                    <button className="min-h-[44px] flex-1 min-w-[4rem] py-2 bg-slate-900 text-white rounded-xl text-xs font-bold hover:bg-indigo-600 transition-colors">검수</button>
                  </div>
                </div>
              </div>
            );
          })}
          </div>
        </div>
      )}

      {selectedSessions.size > 0 && (
        <div className="fixed bottom-4 left-3 right-3 z-50 flex flex-col gap-3 rounded-2xl bg-slate-900 px-4 py-3 text-white shadow-2xl sm:bottom-8 sm:left-1/2 sm:right-auto sm:w-auto sm:-translate-x-1/2 sm:flex-row sm:items-center sm:gap-6 sm:rounded-full sm:px-8 sm:py-4">
          <div className="min-w-0">
            <span className="font-bold">{selectedSessions.size}개 선택됨</span>
            <p className="mt-0.5 text-[11px] leading-snug text-slate-300 sm:mt-0 sm:inline sm:ml-3">
              승인 전 대상 카드(날짜/강사/중복 경고)를 확인하세요
            </p>
          </div>
          <div className="flex items-center gap-3">
            <button onClick={handleBulkApprove} disabled={bulkActionLoading} className="flex-1 sm:flex-none px-5 py-2.5 bg-blue-600 rounded-full font-black hover:bg-blue-500 cursor-pointer disabled:opacity-50">
              {bulkActionLoading ? '처리 중...' : '일괄 승인'}
            </button>
            <button onClick={clearSelection} className="shrink-0 text-slate-400 hover:text-white cursor-pointer px-2 py-2">취소</button>
          </div>
        </div>
      )}

      {/* 모달 */}
      {isModalOpen && selectedEvent && (
        <div
          className="fixed inset-0 z-[999] flex items-end justify-center bg-slate-900/40 p-0 backdrop-blur-md md:items-center md:p-4"
          onClick={() => setIsModalOpen(false)}
        >
          <div
            className="flex max-h-[calc(var(--viewport-height-px,100dvh)-0.75rem)] w-full max-w-3xl flex-col overflow-hidden rounded-t-3xl bg-white shadow-2xl md:max-h-[calc(var(--viewport-height-px,100dvh)-2rem)] md:rounded-[48px]"
            onClick={e => e.stopPropagation()}
          >
            <div className="flex shrink-0 items-start justify-between gap-3 border-b p-4 sm:gap-4 sm:p-8">
              <div className="min-w-0 flex-1">
                <h2 className="truncate text-lg font-black text-slate-900 sm:text-2xl" title={selectedEvent.title}>
                  {selectedEvent.title}
                </h2>
                <div className="mt-2 flex flex-wrap items-center gap-2">
                  <button type="button" onClick={() => window.open(`/report/${selectedEvent.id}`, '_blank')} className="text-indigo-500 text-xs font-bold flex items-center gap-1 hover:underline cursor-pointer">
                    <ExternalLink size={12} /> 미리보기
                  </button>
                </div>
              </div>
              <button type="button" onClick={() => setIsModalOpen(false)} className="flex h-11 w-11 shrink-0 items-center justify-center rounded-lg text-slate-300 hover:bg-slate-100 hover:text-slate-900 cursor-pointer" aria-label="닫기">
                <X size={28} className="sm:h-8 sm:w-8" />
              </button>
            </div>

            <div className="flex-1 space-y-6 overflow-y-auto bg-slate-50/30 p-4 sm:space-y-8 sm:p-8">
              <div className="flex gap-2">
                <span className={`text-[9px] font-black px-3 py-1.5 rounded-full uppercase ${isCenterSessionType(selectedEvent.session_type) ? 'bg-indigo-100 text-indigo-600' : 'bg-sky-100 text-sky-600'}`}>
                  {getSessionTypeBadgeLabel(selectedEvent.session_type)}
                </span>
                {selectedEvent.status === 'postponed' && (
                  <span className="text-[9px] font-black px-3 py-1.5 rounded-full uppercase bg-purple-100 text-purple-700">
                    연기
                  </span>
                )}
                {selectedEvent.status === 'cancelled' && (
                  <span className="text-[9px] font-black px-3 py-1.5 rounded-full uppercase bg-rose-100 text-rose-700">
                    취소
                  </span>
                )}
              </div>

              {/* 중복 경고 */}
              {duplicateCheck?.isDuplicate && (
                <div className="bg-amber-50 border-2 border-amber-400 rounded-xl p-4">
                  <div className="flex items-center gap-2 mb-2">
                    <AlertTriangle className="text-amber-600" size={20} />
                    <span className="font-bold text-amber-900">중복 의심</span>
                  </div>
                  <p className="text-sm text-amber-800">
                    <strong>{duplicateCheck.matchedSession?.title ?? ''}</strong> ({new Date(duplicateCheck.matchedSession?.start_at ?? 0).toLocaleDateString()})와 
                    <strong className="text-amber-900"> {duplicateCheck.similarity ?? 0}% 유사</strong>합니다.
                  </p>
                  <p className="text-xs text-amber-700 mt-1">
                    복사/붙여넣기 피드백일 수 있습니다. 확인 후 검수해주세요.
                  </p>
                </div>
              )}

              {(() => {
                  const centerCondition =
                    isCenterSessionType(selectedEvent.session_type);
                  return centerCondition ? (
                    <div className="bg-white p-5 rounded-[24px] border border-indigo-100 space-y-3">
                  <p className="text-[10px] font-black text-indigo-400 uppercase">파일</p>
                  {fileUrls.length > 0 ? fileUrls.map((url, i) => (
                    <button
                      key={i}
                      type="button"
                      data-file-url={url}
                      data-file-index={String(i)}
                      data-session-id={selectedEvent.id}
                      aria-busy={downloadingCenterFileIndex === i}
                      disabled={downloadingCenterFileIndex !== null}
                      onClick={handleCenterFileOpenOrDownload}
                      className={`w-full text-left flex items-center gap-3 p-3 bg-indigo-50/50 rounded-xl hover:bg-indigo-100 cursor-pointer border-0 disabled:opacity-60 disabled:cursor-wait ${downloadingCenterFileIndex === i ? 'ring-2 ring-indigo-300' : ''}`}
                    >
                      <FileText size={18} className="text-indigo-500 shrink-0" />
                      <span className="text-sm font-bold text-slate-600 truncate">
                        {sessionFileDisplayName(url, i, feedbackFields.center_document_names ?? null)}
                      </span>
                      <ExternalLink size={14} className="ml-auto text-indigo-300 shrink-0" />
                    </button>
                  )) : <p className="text-slate-400 text-sm py-4 text-center">업로드된 파일이 없습니다</p>}
                    </div>
                  ) : null;
                })()}

              {(() => {
                const centerCondition =
                  isCenterSessionType(selectedEvent.session_type);
                return !centerCondition ? (
                <div className="space-y-3">
                  <p className="text-[10px] font-black text-slate-400 uppercase">사진</p>
                  {photoUrls.length > 0 ? (
                    <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 sm:gap-4">
                      {photoUrls.map((url, i) => (
                        <div key={i} className="relative aspect-square rounded-2xl sm:rounded-[24px] overflow-hidden border-2 border-white shadow-sm hover:scale-105 cursor-zoom-in" onClick={() => setZoomedImg(url)}>
                          <img src={url} className="w-full h-full object-cover" alt="수업 사진" />
                          <div className="absolute inset-0 bg-black/10 opacity-0 hover:opacity-100 flex items-center justify-center"><Maximize2 size={20} className="text-white" /></div>
                        </div>
                      ))}
                    </div>
                  ) : <p className="text-slate-400 text-sm py-4 text-center bg-white rounded-2xl border">업로드된 사진이 없습니다</p>}
                </div>
                ) : null;
              })()}

              {(() => {
                const centerCondition =
                  isCenterSessionType(selectedEvent.session_type);
                return centerCondition ? (
                <div className="space-y-3">
                  <label className="text-[10px] font-black text-slate-400 uppercase block ml-1">메모</label>
                  <textarea 
                    className="w-full min-h-[120px] bg-white rounded-2xl p-4 text-sm text-slate-700 outline-none focus:ring-2 focus:ring-blue-100 resize-none border" 
                    value={feedbackFields.condition_notes || ''} 
                    onChange={(e) => setFeedbackFields({...feedbackFields, condition_notes: e.target.value})}
                    placeholder="센터 수업 메모를 작성하세요..."
                  />
                </div>
                ) : (
                <div className="space-y-4">
                  <p className="text-[10px] font-black text-slate-400 uppercase ml-1">피드백 내용</p>
                  {[
                    { key: 'main_activity', label: '✅ 오늘 수업의 주요 활동', color: 'indigo', placeholder: '예: 축구 기본기 드리블 연습' },
                    { key: 'strengths', label: '✅ 강점 및 긍정적인 부분', color: 'emerald', placeholder: '예: 드리블 속도가 빨라졌습니다' },
                    { key: 'improvements', label: '✅ 개선이 필요한 부분', color: 'amber', placeholder: '예: 슈팅 정확도 연습 필요' },
                    { key: 'next_goals', label: '✅ 다음 수업 목표 및 계획', color: 'blue', placeholder: '예: 패스 연습과 전술 이해도 향상' },
                    { key: 'condition_notes', label: '✅ 특이사항 및 시작/종료 시간', color: 'slate', placeholder: '예: 14:00 시작, 15:30 종료' }
                  ].map(field => (
                    <div key={field.key} className="space-y-2">
                      <label className={`text-[9px] font-bold text-${field.color}-600 uppercase block ml-1`}>{field.label}</label>
                      <textarea 
                        className={`w-full h-20 bg-white rounded-xl p-3 text-sm text-slate-700 outline-none focus:ring-2 focus:ring-${field.color}-100 resize-none border`}
                        value={(feedbackFields as Record<string, string>)[field.key] || ''} 
                        onChange={(e) => setFeedbackFields({...feedbackFields, [field.key]: e.target.value})}
                        placeholder={field.placeholder}
                      />
                    </div>
                  ))}
                </div>
                );
              })()}
            </div>

            <div className="flex shrink-0 flex-col gap-2 border-t p-4 sm:flex-row sm:gap-4 sm:p-8">
              <button onClick={() => handleSave('finished')} className="w-full py-3.5 sm:py-5 bg-slate-50 border rounded-2xl sm:rounded-3xl font-bold text-rose-500 hover:bg-rose-50 cursor-pointer sm:flex-1">
                <RotateCcw size={18} className="inline mr-1" /> 수정 요청으로 저장
              </button>
              <button onClick={() => handleSave('verified')} className="w-full py-3.5 sm:py-5 bg-slate-900 rounded-2xl sm:rounded-3xl font-black text-white shadow-xl hover:bg-indigo-600 cursor-pointer sm:flex-[2]">
                검수 승인(학부모 공유용) 저장
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );
}

// 수업안 조회 탭 - 세션 타입 (lesson_plans: API가 배열 또는 단일 객체로 올 수 있음)
type LessonPlanSession = Record<string, unknown> & { id: string; created_by: string; users?: { name?: string } | null; title?: string; start_at?: string; lesson_plans?: { content?: unknown }[] | { content?: unknown } | null };
function getLessonPlanContent(session: LessonPlanSession): string | null {
  const lp = session.lesson_plans;
  if (lp == null) return null;
  const content = Array.isArray(lp) ? lp[0]?.content : (lp as { content?: unknown } | null)?.content;
  return content != null && content !== '' ? String(content) : null;
}
function LessonPlanTab({
  coaches,
  excludedAdminCoachIds,
}: {
  coaches: Coach[];
  excludedAdminCoachIds: string[];
}) {
  const [lessonPlanScope, setLessonPlanScope] = useState<'private' | 'center'>('private');
  const [sessions, setSessions] = useState<LessonPlanSession[]>([]);
  const [selectedTeacher, setSelectedTeacher] = useState('all');
  const [selectedPrivateWeekday, setSelectedPrivateWeekday] = useState<number | 'all'>('all');
  const [loading, setLoading] = useState(true);
  const [selectedSession, setSelectedSession] = useState<LessonPlanSession | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);

  useEffect(() => {
    const fetchSessions = async () => {
      setLoading(true);
      try {
        const scopeParam = lessonPlanScope === 'center' ? 'center' : 'private';
        const res = await fetch(
          `/api/admin/lesson-plans-sessions?teacherId=${encodeURIComponent(selectedTeacher)}&scope=${scopeParam}&_=${Date.now()}`,
          { credentials: 'include', cache: 'no-store' }
        );
        if (!res.ok) {
          if (res.status === 401 || res.status === 403) {
            setSessions([]);
            return;
          }
          throw new Error(await res.text());
        }
        const data = await res.json();
        const raw = Array.isArray(data) ? data : [];
        const filtered =
          excludedAdminCoachIds.length === 0
            ? raw
            : raw.filter((s: LessonPlanSession) => !excludedAdminCoachIds.includes(String(s.created_by)));
        setSessions(filtered);
      } catch (err: unknown) {
        devLogger.error('수업안 로드 실패:', err instanceof Error ? err.message : err);
        setSessions([]);
      } finally {
        setLoading(false);
      }
    };
    fetchSessions();
  }, [selectedTeacher, lessonPlanScope, excludedAdminCoachIds]);

  const privateWeekdayGroups = useMemo(() => {
