          <button
            key={option}
            type="button"
            onClick={() => onChange(toggleOption(selected, option))}
            className="h-8 rounded-full border px-3 text-[12px] font-black transition-colors"
            style={{
              borderColor: active ? '#4f46e5' : '#e2e8f0',
