function SlotProgramCombobox({
  items,
  selectedId,
  selectedElsewhere,
  disabled,
  onSelect,
}: {
  items: ProgramItem[];
  selectedId: number | null;
  selectedElsewhere: Set<number>;
  disabled?: boolean;
  onSelect: (curriculumId: number | null) => void;
}) {
  const listboxId = useId();
  const rootRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const listRef = useRef<HTMLUListElement>(null);
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState('');
  const [highlight, setHighlight] = useState(0);

  const selected = items.find((item) => item.curriculum.id === selectedId) ?? null;
  const inputValue = open ? query : selected?.effective.title ?? '';

  const options = useMemo(() => {
    const normalized = query.trim().toLowerCase();
    return items
      .filter((item) => {
        const id = item.curriculum.id;
        if (selectedElsewhere.has(id) && id !== selectedId) return false;
        if (!normalized) return true;
        const text =
          `${item.effective.title} ${item.curriculum.title} ${item.curriculum.id}`.toLowerCase();
        return text.includes(normalized);
      })
      .sort((a, b) => {
        const titleCompare = koreanTitleCollator.compare(
          a.effective.title.trim(),
          b.effective.title.trim(),
        );
        return titleCompare || a.curriculum.id - b.curriculum.id;
      });
  }, [items, query, selectedElsewhere, selectedId]);

  useEffect(() => {
    if (!open) return;
    const onPointerDown = (event: PointerEvent) => {
      if (!rootRef.current?.contains(event.target as Node)) {
        setOpen(false);
        setQuery('');
      }
    };
    document.addEventListener('pointerdown', onPointerDown);
    return () => document.removeEventListener('pointerdown', onPointerDown);
  }, [open]);

  useEffect(() => {
    setHighlight(0);
  }, [query, open]);

  useEffect(() => {
    if (!open) return;
    const active = listRef.current?.querySelector<HTMLElement>('[data-active="true"]');
    active?.scrollIntoView({ block: 'nearest' });
  }, [highlight, open, options]);

  const choose = (curriculumId: number | null) => {
    onSelect(curriculumId);
    setOpen(false);
    setQuery('');
    inputRef.current?.blur();
  };

  const onKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'ArrowDown') {
      event.preventDefault();
      if (!open) {
        setOpen(true);
        return;
      }
      setHighlight((current) => {
        if (current < 0) return 0;
        return Math.min(current + 1, Math.max(options.length - 1, 0));
      });
      return;
    }
    if (event.key === 'ArrowUp') {
      event.preventDefault();
      if (!open) {
        setOpen(true);
        return;
      }
      setHighlight((current) => {
        if (current <= 0) return -1;
        return current - 1;
      });
      return;
    }
    if (event.key === 'Enter') {
      event.preventDefault();
      if (!open) {
        setOpen(true);
        return;
      }
      if (highlight < 0) {
        choose(null);
        return;
      }
      const item = options[highlight];
      if (item) choose(item.curriculum.id);
      return;
    }
    if (event.key === 'Escape') {
      event.preventDefault();
      setOpen(false);
      setQuery('');
    }
  };

  return (
    <div ref={rootRef} className="relative mt-2">
      <Search
        className="pointer-events-none absolute left-3 top-1/2 z-10 -translate-y-1/2 text-slate-400"
        size={14}
      />
      <input
        ref={inputRef}
        value={inputValue}
        disabled={disabled}
        role="combobox"
        aria-expanded={open}
        aria-autocomplete="list"
        aria-controls={listboxId}
        autoComplete="off"
        placeholder={selected ? selected.effective.title : '프로그램명 또는 ID 검색'}
        onFocus={() => {
          setOpen(true);
          setQuery('');
        }}
        onChange={(event) => {
          setQuery(event.target.value);
          if (!open) setOpen(true);
        }}
        onKeyDown={onKeyDown}
        className="h-10 w-full rounded-lg border border-slate-200 bg-white pl-8 pr-9 text-[12px] font-bold text-slate-800 outline-none focus:border-indigo-400 disabled:opacity-50"
      />
      <ChevronDown
        className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-slate-400"
        size={14}
      />
      {open ? (
        <div className="absolute left-0 right-0 top-[calc(100%+4px)] z-30 overflow-hidden rounded-lg border border-slate-200 bg-white shadow-lg">
          <p className="border-b border-slate-100 px-3 py-1.5 text-[10px] font-black text-slate-400">
            {options.length}개 · 키보드 ↑↓ Enter
          </p>
          <ul
            ref={listRef}
            id={listboxId}
            role="listbox"
            className="max-h-56 overflow-y-auto py-1"
          >
            <li role="option" aria-selected={selectedId == null}>
              <button
                type="button"
                data-active={highlight === -1 ? 'true' : undefined}
                onMouseEnter={() => setHighlight(-1)}
                onClick={() => choose(null)}
                className="flex w-full items-center justify-between px-3 py-2 text-left text-[12px] font-bold"
                style={{
                  background: highlight === -1 ? '#eef2ff' : 'transparent',
                  color: highlight === -1 ? '#4338ca' : '#64748b',
                }}
              >
                빈 슬롯
              </button>
            </li>
            {options.length === 0 ? (
              <li className="px-3 py-3 text-[12px] font-bold text-slate-400">검색 결과 없음</li>
            ) : (
              options.map((item, optionIndex) => {
                const active = highlight === optionIndex;
                const isSelected = item.curriculum.id === selectedId;
                return (
                  <li
                    key={item.curriculum.id}
                    role="option"
                    aria-selected={isSelected}
                  >
                    <button
                      type="button"
                      data-active={active ? 'true' : undefined}
                      onMouseEnter={() => setHighlight(optionIndex)}
                      onClick={() => choose(item.curriculum.id)}
                      className="flex w-full items-center justify-between gap-2 px-3 py-2 text-left"
                      style={{
                        background: active ? '#eef2ff' : isSelected ? '#f8fafc' : 'transparent',
                      }}
                    >
                      <span className="min-w-0">
                        <span className="block truncate text-[12px] font-black text-slate-900">
                          {item.effective.title}
                        </span>
                        <span className="block text-[10px] font-bold text-slate-400">
                          #{item.curriculum.id}
                        </span>
                      </span>
                      {isSelected ? <Check size={14} className="shrink-0 text-indigo-600" /> : null}
                    </button>
                  </li>
                );
              })
            )}
          </ul>
        </div>
      ) : null}
    </div>
  );
}

function WeeklyRecommendationManager({
  items,
  onSaved,
}: {
  items: ProgramItem[];
  onSaved: () => Promise<void>;
}) {
  const [slots, setSlots] = useState<Array<number | null>>([null, null, null, null]);
  const [loadingSlots, setLoadingSlots] = useState(true);
  const [savingSlots, setSavingSlots] = useState(false);

  useEffect(() => {
    let active = true;
    const loadSlots = async () => {
      try {
        const res = await fetch('/api/admin/spokedu-master/programs/home-featured', {
          cache: 'no-store',
        });
        const json = await readAdminJsonSafe<{
          slots?: Array<number | null>;
          error?: string;
        }>(res, '추천 슬롯을 불러오지 못했습니다');
        if (!res.ok) throw new Error(json.error ?? '추천 슬롯을 불러오지 못했습니다.');
        if (active) {
          setSlots(
            Array.from({ length: 4 }, (_, index) => json.slots?.[index] ?? null),
          );
        }
      } catch (error) {
        toast.error(
          error instanceof Error ? error.message : '추천 슬롯을 불러오지 못했습니다.',
        );
      } finally {
        if (active) setLoadingSlots(false);
      }
    };
    void loadSlots();
    return () => {
      active = false;
    };
  }, []);

  const updateSlot = (index: number, curriculumId: number | null) => {
    setSlots((current) => {
      if (
        curriculumId != null &&
        current.some((id, slotIndex) => slotIndex !== index && id === curriculumId)
      ) {
        toast.error('같은 프로그램을 여러 추천 슬롯에 선택할 수 없습니다.');
        return current;
      }
      return current.map((id, slotIndex) => (slotIndex === index ? curriculumId : id));
    });
  };

  const saveSlots = async () => {
    setSavingSlots(true);
    try {
      const res = await fetch('/api/admin/spokedu-master/programs/home-featured', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ slots }),
      });
      const json = await readAdminJsonSafe<{
        slots?: Array<number | null>;
        message?: string;
        error?: string;
      }>(res, '추천 슬롯 저장에 실패했습니다');
      if (!res.ok) throw new Error(json.error ?? '추천 슬롯 저장에 실패했습니다.');
      setSlots(Array.from({ length: 4 }, (_, index) => json.slots?.[index] ?? null));
      await useMasterStore.getState().reloadPrograms();
      await onSaved();
      toast.success(json.message ?? '이번주 추천 프로그램을 저장했습니다.');
    } catch (error) {
      toast.error(error instanceof Error ? error.message : '추천 슬롯 저장에 실패했습니다.');
    } finally {
      setSavingSlots(false);
    }
  };

  return (
    <section className="border-b border-slate-200 bg-slate-50 px-4 py-4 sm:px-5">
      <div className="mx-auto max-w-[1500px] rounded-xl border border-indigo-100 bg-white p-4 shadow-sm">
        <div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
          <div>
            <p className="text-[11px] font-black uppercase tracking-[0.12em] text-indigo-600">
              Weekly recommendation
            </p>
            <h2 className="mt-1 text-[17px] font-black text-slate-950">
              이번주 추천 프로그램 관리
            </h2>
            <p className="mt-1 text-[12px] font-semibold leading-5 text-slate-500">
              프로그램명·ID로 검색해 고르세요. 선택한 프로그램은 슬롯 순서대로 홈에 반영되며, 빈
              슬롯은 자동 추천으로 보완됩니다.
            </p>
          </div>
          <button
            type="button"
            onClick={() => void saveSlots()}
            disabled={loadingSlots || savingSlots}
            className="spm-btn-primary inline-flex h-10 shrink-0 items-center justify-center gap-2 rounded-[10px] px-4 text-[12px] font-black focus-visible:outline-none disabled:opacity-50"
          >
            <Save size={14} />
            {savingSlots ? '추천 저장 중' : '추천 슬롯 저장'}
          </button>
        </div>

        <div className="mt-4 grid gap-3 md:grid-cols-2 xl:grid-cols-4">
          {slots.map((selectedId, index) => {
            const selectedElsewhere = new Set(
              slots.filter((id, slotIndex): id is number => slotIndex !== index && id != null),
            );

            return (
              <div key={index} className="rounded-lg border border-slate-200 bg-slate-50 p-3">
                <div className="flex items-center justify-between gap-2">
                  <p className="text-[13px] font-black text-slate-900">
                    {index + 1}번 추천 슬롯
                  </p>
                  {selectedId != null ? (
                    <button
                      type="button"
                      onClick={() => updateSlot(index, null)}
                      className="text-[11px] font-black text-slate-400 hover:text-rose-600"
                    >
                      비우기
                    </button>
                  ) : null}
                </div>
                <SlotProgramCombobox
                  items={items}
                  selectedId={selectedId}
                  selectedElsewhere={selectedElsewhere}
                  disabled={loadingSlots}
                  onSelect={(curriculumId) => updateSlot(index, curriculumId)}
                />
                {selectedId != null ? (
                  <p className="mt-1.5 text-[11px] font-bold text-slate-400">#{selectedId}</p>
                ) : (
                  <p className="mt-1.5 text-[11px] font-bold text-slate-400">비어 있음</p>
                )}
              </div>
            );
          })}
        </div>
      </div>
    </section>
  );
}

export default function AdminSmProgramsPage() {
  const pathname = usePathname();
  const isSpomoveAdmin = pathname.startsWith('/admin/spokedu-lab/spomove') || pathname.startsWith('/admin/spokedu-master/spomove');
  const tabOptions = isSpomoveAdmin ? SPOMOVE_ADMIN_TAB_OPTIONS : LIBRARY_ADMIN_TAB_OPTIONS;
  const [items, setItems] = useState<ProgramItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [creating, setCreating] = useState(false);
  const [syncing, setSyncing] = useState(false);
  const [query, setQuery] = useState('');
  const [activeTab, setActiveTab] = useState<AdminTabKey>(isSpomoveAdmin ? 'spomove-content' : 'programs');
  const [activeFilter, setActiveFilter] = useState<FilterKey>('all');
  const [selectedId, setSelectedId] = useState<number | null>(null);
  const [form, setForm] = useState<EditForm | null>(null);
  const [mobilePane, setMobilePane] = useState<'list' | 'editor'>('list');
  const [createOpen, setCreateOpen] = useState(false);
  const [createForm, setCreateForm] = useState<CreateProgramForm>({
    title: '',
    videoUrl: '',
    equipment: '',
    steps: '',
  });
  const selectedIdRef = useRef<number | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    if (isSpomoveAdmin) {
      setItems([]);
      setSelectedId(null);
      setForm(null);
      setLoading(false);
      return;
    }
    try {
      const res = await fetch('/api/admin/spokedu-master/programs', { cache: 'no-store' });
      const json = await readAdminJsonSafe<ProgramsResponse & { error?: string }>(
        res,
        '프로그램 목록을 불러오지 못했습니다',
      );
      if (!res.ok) throw new Error(json.error ?? '프로그램 목록을 불러오지 못했습니다.');
      const nextItems = json.data ?? [];
      setItems(nextItems);
      const nextSelected =
        nextItems.find((item) => item.curriculum.id === selectedIdRef.current) ??
        nextItems[0] ??
        null;
      if (nextSelected) {
        setSelectedId(nextSelected.curriculum.id);
        setForm(toForm(nextSelected));
      } else {
        setSelectedId(null);
        setForm(null);
      }
    } catch (error) {
      toast.error(error instanceof Error ? error.message : '프로그램 목록을 불러오지 못했습니다.');
      setItems([]);
    } finally {
      setLoading(false);
    }
  }, [isSpomoveAdmin]);

  useEffect(() => {
    void load();
  }, [load]);

  useEffect(() => {
    selectedIdRef.current = selectedId;
  }, [selectedId]);

  useEffect(() => {
    if (!tabOptions.some((tab) => tab.key === activeTab)) {
      setActiveTab(tabOptions[0].key);
    }
  }, [activeTab, tabOptions]);

  const selected = useMemo(() => items.find((item) => item.curriculum.id === selectedId) ?? null, [items, selectedId]);

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    const next = items.filter((item) => {
      if (!matchesFilter(item, activeFilter)) return false;
      if (!q) return true;
      const haystack = `${item.effective.title} ${item.curriculum.id} ${item.effective.target} ${item.effective.space}`.toLowerCase();
      return haystack.includes(q);
    });
    return sortForFilter(next, activeFilter);
  }, [activeFilter, items, query]);

  const summary = useMemo(() => ({
    needsImprovement: items.filter((item) => getItemQuality(item).status === 'needs-improvement').length,
    homeReady: items.filter((item) => getItemQuality(item).status === 'home-ready').length,
    imageNeeded: items.filter((item) => !getItemQuality(item).checks.setupImage).length,
  }), [items]);

  const selectItem = (item: ProgramItem) => {
    setSelectedId(item.curriculum.id);
    setForm(toForm(item));
    setMobilePane('editor');
  };

  const openProgramFromAudit = (curriculumId: number) => {
    const item = items.find((candidate) => candidate.curriculum.id === curriculumId);
    if (!item) {
      toast.error('편집기 목록에 해당 수업이 없습니다. 새로고침 후 다시 시도해 주세요.');
      return;
    }
    selectItem(item);
    setActiveTab('programs');
  };

  const updateForm = <K extends keyof EditForm>(key: K, value: EditForm[K]) => {
    setForm((prev) => (prev ? { ...prev, [key]: value } : prev));
  };

  const updateCreateForm = <K extends keyof CreateProgramForm>(key: K, value: CreateProgramForm[K]) => {
    setCreateForm((prev) => ({ ...prev, [key]: value }));
  };

  const closeCreateModal = () => {
    if (creating) return;
    setCreateOpen(false);
  };

  const createProgram = async () => {
    const title = createForm.title.trim();
    if (!title) {
      toast.error('프로그램 제목을 입력해 주세요.');
      return;
    }

    setCreating(true);
    try {
      const res = await fetch('/api/admin/spokedu-master/programs', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(createForm),
      });
      const json = await readAdminJsonSafe<{ ok?: boolean; error?: string; program?: ProgramItem }>(
        res,
        '프로그램 추가에 실패했습니다',
      );
      if (!res.ok || json.ok !== true || !json.program) {
        throw new Error(json.error ?? '프로그램 추가에 실패했습니다.');
      }

      const next = json.program;
      setItems((current) => [next, ...current.filter((item) => item.curriculum.id !== next.curriculum.id)]);
      setSelectedId(next.curriculum.id);
      setForm(toForm(next));
      setActiveFilter('all');
      setQuery('');
      setCreateOpen(false);
      setCreateForm({ title: '', videoUrl: '', equipment: '', steps: '' });
      toast.success('프로그램을 추가했습니다. 이어서 상세 정보를 채워 주세요.');
    } catch (error) {
      toast.error(error instanceof Error ? error.message : '프로그램 추가에 실패했습니다.');
    } finally {
      setCreating(false);
    }
  };

  const syncFromCenter = async () => {
    setSyncing(true);
    try {
      const previewRes = await fetch('/api/admin/spokedu-master/programs/sync-center', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ dryRun: true }),
      });
      const preview = await readAdminJsonSafe<{
        error?: string;
        summary?: { toInsert: number; toUpdate: number };
        changes?: Array<{ title: string; fields: string[] }>;
        message?: string;
      }>(previewRes, '동기화 미리보기에 실패했습니다');
      if (!previewRes.ok) throw new Error(preview.error ?? '동기화 미리보기에 실패했습니다.');

      const total = (preview.summary?.toInsert ?? 0) + (preview.summary?.toUpdate ?? 0);
      if (total === 0) {
        toast.success(preview.message ?? '커리큘럼과 overlay가 이미 일치합니다.');
        return;
      }

      const sample = (preview.changes ?? [])
        .slice(0, 5)
        .map((item) => `• ${item.title} (${item.fields.join(', ')})`)
        .join('\n');
      const confirmed = window.confirm(
        `커리큘럼 본문을 overlay에 반영합니다.\n\n신규 ${preview.summary?.toInsert ?? 0}개 · 갱신 ${preview.summary?.toUpdate ?? 0}개\n\n${sample}${total > 5 ? `\n…외 ${total - 5}개` : ''}\n\n제목·태그·MASTER 메타는 그대로 두고, 영상 URL·체크리스트·교구·활동 단계·전문가 팁만 덮어씁니다.`,
      );
      if (!confirmed) return;

      const applyRes = await fetch('/api/admin/spokedu-master/programs/sync-center', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ dryRun: false }),
      });
      const applied = await readAdminJsonSafe<{ error?: string; message?: string; applied?: number }>(
        applyRes,
        '동기화 적용에 실패했습니다',
      );
      if (!applyRes.ok) throw new Error(applied.error ?? '동기화 적용에 실패했습니다.');

      await load();
      toast.success(applied.message ?? `커리큘럼 동기화 ${applied.applied ?? 0}건 완료`);
    } catch (error) {
      toast.error(error instanceof Error ? error.message : '커리큘럼 동기화에 실패했습니다.');
    } finally {
      setSyncing(false);
    }
  };

  const save = async () => {
    if (!selected || !form) return;
    setSaving(true);
    try {
      const res = await fetch(`/api/admin/spokedu-master/programs?id=${selected.curriculum.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(buildAdminProgramSavePayload({
          title: form.title,
          fallbackTitle: selected.curriculum.title,
          videoUrl: form.videoUrl,
          equipment: form.equipment,
          activityMethod: form.steps,
          publicationStatus: form.publicationStatus,
          theme: normalizeLessonTheme(form.theme),
          target: serializeMasterTags(parseMasterTargets(form.target)),
          tags: csvToList(form.tags),
          space: serializeMasterTags(parseMasterSpaces(form.space)),
          setupImageUrl: form.setupImageUrl,
          coachScript: form.coachScript,
          briefingNotes: form.briefingNotes,
          variationMethod: form.variations,
        })),
      });
      const json = await readAdminJsonSafe<{
        ok?: boolean;
        partialSave?: boolean;
        failedStage?: string;
        error?: string;
        program?: SavedAdminProgram<Partial<OverlayRow>, MetaRow>;
      }>(res, '저장에 실패했습니다');
      if (!res.ok || json.ok !== true) {
        const message = json.partialSave
          ? `일부 항목 저장 실패${json.failedStage ? ` (${json.failedStage})` : ''}. 다시 저장해 주세요.`
          : json.error ?? '저장에 실패했습니다.';
        throw new Error(message);
      }
      if (!json.program) throw new Error('저장된 프로그램 응답이 없습니다.');
      const next = mergeSavedProgram(selected, json.program);
      setItems((current) => replaceAdminProgramByCurriculumId(
        current,
        selected.curriculum.id,
        next,
        (item) => item.curriculum.id,
      ));
      setSelectedId(next.curriculum.id);
      setForm(toForm(next));
      toast.success('MASTER 편집 값이 저장되었습니다.');
    } catch (error) {
      toast.error(error instanceof Error ? error.message : '저장에 실패했습니다.');
    } finally {
      setSaving(false);
    }
  };

  const removeSetupImage = async () => {
    if (!selected || !form || !form.setupImageUrl.trim()) return;
    const previousForm = form;
    const previousImageUrl = form.setupImageUrl;
    const nextForm = { ...form, setupImageUrl: '' };

    setForm(nextForm);
    setSaving(true);
    try {
      const res = await fetch(`/api/admin/spokedu-master/programs?id=${selected.curriculum.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(buildAdminProgramSavePayload({
          title: nextForm.title,
          fallbackTitle: selected.curriculum.title,
          videoUrl: nextForm.videoUrl,
          equipment: nextForm.equipment,
          activityMethod: nextForm.steps,
          publicationStatus: nextForm.publicationStatus,
          theme: normalizeLessonTheme(nextForm.theme),
          target: serializeMasterTags(parseMasterTargets(nextForm.target)),
          tags: csvToList(nextForm.tags),
          space: serializeMasterTags(parseMasterSpaces(nextForm.space)),
          setupImageUrl: '',
          coachScript: nextForm.coachScript,
          briefingNotes: nextForm.briefingNotes,
          variationMethod: nextForm.variations,
        })),
      });
      const json = await readAdminJsonSafe<{
        ok?: boolean;
        partialSave?: boolean;
        failedStage?: string;
        error?: string;
        program?: SavedAdminProgram<Partial<OverlayRow>, MetaRow>;
      }>(res, '이미지 제거 저장에 실패했습니다');
      if (!res.ok || json.ok !== true) {
        const message = json.partialSave
          ? `이미지 제거 저장 중 일부 단계가 실패했습니다${json.failedStage ? ` (${json.failedStage})` : ''}.`
          : json.error ?? '이미지 제거 저장에 실패했습니다.';
        throw new Error(message);
      }
      if (!json.program) throw new Error('저장된 프로그램 응답이 없습니다.');

      const next = mergeSavedProgram(selected, json.program);
      setItems((current) => replaceAdminProgramByCurriculumId(
        current,
        selected.curriculum.id,
        next,
        (item) => item.curriculum.id,
      ));
      setSelectedId(next.curriculum.id);
      setForm(toForm(next));

      const path = storagePathFromPublicUrl(previousImageUrl);
      if (path) await deleteFromStorage(path).catch(() => undefined);
      toast.success('도식화 이미지를 제거했습니다.');
    } catch (error) {
      setForm(previousForm);
      toast.error(error instanceof Error ? error.message : '이미지 제거에 실패했습니다.');
    } finally {
      setSaving(false);
    }
  };

  const selectedQuality = form ? getFormQuality(form) : null;
  const selectedQualitySummary = selectedQuality ? qualitySummary(selectedQuality) : '';

  return (
    <div className="min-h-dvh bg-slate-50 text-slate-950">
      <header className="sticky top-0 z-20 border-b border-slate-200 bg-white px-4 py-3 sm:px-5 sm:py-4">
        <div className="flex flex-wrap items-center gap-3">
          <Link href="/admin/spokedu-master" className="grid h-11 w-11 shrink-0 place-items-center rounded-lg border border-slate-200 text-slate-500 sm:h-9 sm:w-9" aria-label="이전">
            <ChevronLeft size={17} />
          </Link>
          <div>
            <h1 className="text-[18px] font-black">{isSpomoveAdmin ? '마스터 스포무브' : '마스터 라이브러리'}</h1>
            <p className="mt-0.5 text-[12px] font-semibold text-slate-500">
              {isSpomoveAdmin
                ? 'SPOMOVE 썸네일과 가이드 영상을 직접 관리합니다.'
                : 'curriculum 원본은 보존하고 MASTER 라이브러리 메타와 운영 자료만 편집합니다.'}
            </p>
          </div>
          <div className="order-last flex w-full gap-1 overflow-x-auto rounded-lg border border-slate-200 bg-slate-50 p-1 sm:order-none sm:ml-auto sm:w-auto">
            {tabOptions.map((tab) => (
              <button
                key={tab.key}
                type="button"
                onClick={() => setActiveTab(tab.key)}
                className="min-h-11 shrink-0 rounded-md px-3 text-[12px] font-black transition-colors sm:min-h-8"
                style={{
                  background: activeTab === tab.key ? '#4f46e5' : 'transparent',
                  color: activeTab === tab.key ? '#ffffff' : '#475569',
                }}
              >
                {tab.label}
              </button>
            ))}
          </div>
          {activeTab === 'programs' ? (
            <>
          <button
            type="button"
            onClick={() => setCreateOpen(true)}
            disabled={creating}
            className="inline-flex min-h-11 items-center gap-2 rounded-lg bg-slate-950 px-3 text-[12px] font-black text-white disabled:opacity-50 sm:min-h-9"
          >
            <Plus size={14} />
            프로그램 직접 추가
          </button>
          <button
            type="button"
            onClick={() => void syncFromCenter()}
            disabled={syncing || loading}
            className="inline-flex min-h-11 items-center gap-2 rounded-lg border border-emerald-200 bg-emerald-50 px-3 text-[12px] font-black text-emerald-800 disabled:opacity-50 sm:min-h-9"
          >
            <RefreshCw size={14} className={syncing ? 'animate-spin' : ''} />
