async function make(b){const c=await b.newContext({viewport:{width:1280,height:800},serviceWorkers:'block'});const errors=[],writes=[];await c.route('**/*',r=>{const u=new URL(r.request().url());if(u.hostname!=='127.0.0.1')return r.abort();if(!['GET','HEAD'].includes(r.request().method())){writes.push(u.pathname);return r.fulfill({status:503,json:{error:'GATE_WRITE_BLOCKED'}})}if(u.pathname.startsWith('/api/'))return r.fulfill({json:{ok:true,data:[]}});return r.continue()});const p=await c.newPage();p.on('pageerror',e=>errors.push(e.message));await p.clock.install();return {c,p,errors,writes}}
async function text(p){return (await p.locator('body').innerText()).slice(-12000)}
async function advance(p,ms){let timeout;try{await Promise.race([p.clock.fastForward(ms),new Promise((_,reject)=>{timeout=setTimeout(()=>reject(Error('CLOCK_COMMAND_TIMEOUT')),15000)})])}finally{clearTimeout(timeout)}}
async function warm(p){for(let i=0;i<8;i++)await advance(p,1000)}
async function stop(p){const b=p.locator('button').filter({hasText:/STOP|훈련 종료|훈련 중지/}).filter({visible:true});if(await b.count()){await b.first().click({force:true});await advance(p,200);return true}const x=p.locator('button[aria-label="나가기"]');if(await x.count()){await x.first().click({force:true});await advance(p,200);return true}return false}
