await warm(p);row.stages.running=await text(p);row.stages.stopControl=await stop(p);if(await p.locator('.tr-result-root').count()){row.stages.stopResult=await text(p);const retry=p.getByRole('button',{name:group==='teacher'?'다시 실행':'같은 설정으로 다시 준비',exact:true});if(await retry.count()){await retry.first().click({force:true});await advance(p,100);row.stages.retry=await text(p);if(group!=='teacher')await p.getByRole('button',{name:'수업 시작',exact:true}).click({force:true});await warm(p)}}
