const fs = require('fs'), path = require('path'), os = require('os'), cp = require('child_process');
const root = process.cwd(), out = path.join(root, '.spomove-gate-b', 'current-final');
const dest = fs.mkdtempSync(path.join(os.tmpdir(), 'spomove-stage3-'));
fs.writeFileSync(path.join(out, 'workspace.json'), JSON.stringify({ root, dest, at: new Date().toISOString() }, null, 2));
const files = cp.execFileSync('git', ['ls-files', '--cached', '--others', '--exclude-standard', '-z'], { cwd: root }).toString().split('\0').filter(Boolean);
for (const file of files) {
  if (file.startsWith('.') || file.startsWith('public/') || file.startsWith('node_modules/')) continue;
  const src = path.join(root, file), target = path.join(dest, file);
  if (!fs.existsSync(src) || !fs.statSync(src).isFile()) continue;
  fs.mkdirSync(path.dirname(target), { recursive: true }); fs.copyFileSync(src, target);
}
for (const file of ['.gitignore', '.env.example', '.npmrc', '.postcssrc.json']) if (fs.existsSync(path.join(root,file))) fs.copyFileSync(path.join(root,file),path.join(dest,file));
for (const dir of ['node_modules','public']) fs.symlinkSync(path.join(root,dir),path.join(dest,dir),'junction');
const env = {};
for (const key of ['PATH','Path','SystemRoot','TEMP','TMP','COMSPEC','WINDIR','USERPROFILE','LOCALAPPDATA','APPDATA','NUMBER_OF_PROCESSORS','PROCESSOR_ARCHITECTURE']) if(process.env[key]) env[key]=process.env[key];
Object.assign(env,{NEXT_TELEMETRY_DISABLED:'1',NEXT_PUBLIC_SUPABASE_URL:'http://127.0.0.1:9',NEXT_PUBLIC_SUPABASE_ANON_KEY:'local-audit-placeholder',SUPABASE_SERVICE_ROLE_KEY:'local-audit-placeholder',NODE_OPTIONS:'--require '+JSON.stringify(path.join(root,'.spomove-gate-a/network-guard.cjs'))});
async function run(label,args){const start=new Date().toISOString(), fd=fs.openSync(path.join(out,label+'.log'),'w');return new Promise(resolve=>{const p=cp.spawn(process.execPath,args,{cwd:dest,env,stdio:['ignore',fd,fd],windowsHide:true});p.on('error',e=>{fs.writeSync(fd,String(e));});p.on('close',(code,signal)=>{fs.closeSync(fd);fs.writeFileSync(path.join(out,label+'.json'),JSON.stringify({start,end:new Date().toISOString(),code,signal,args,cwd:dest},null,2));console.log(label+': '+code);resolve(code);});});}
