const rows=[];
for(const item of manifest){
 const current=fs.existsSync(item.path)?fs.readFileSync(item.path):null;
 const head=cp.execFileSync('git',['show','HEAD:'+item.path],{maxBuffer:32*1024*1024});
 const currentHash=current?hash(current):null,headHash=hash(head);
 if(currentHash===item.sha256)continue;
 let cause='UNRESOLVED: manifest and committed evidence differ; original authoring history not established';
 if(!current)cause='MISSING';
 else if(hash(Buffer.from(current.toString('utf8').replace(/\r\n/g,'\n')))===item.sha256)cause='CRLF conversion: LF-normalized current bytes match manifest';
 else if(hash(Buffer.from(current.toString('utf8').replace(/\r\n/g,'\n').replace(/\n/g,'\r\n')))===item.sha256)cause='LF conversion: CRLF-normalized current bytes match manifest';
 rows.push({path:item.path,manifestSha256:item.sha256,currentSha256:currentHash,headBlobSha256:headHash,cause,status:'VERIFICATION_WITHHELD_PENDING_INDEPENDENT_REPRODUCTION'});
}
fs.writeFileSync(path.join(out,'evidence-mismatches.json'),JSON.stringify({manifestEntries:manifest.length,stage1FolderPresent:fs.existsSync('.spomove-audit'),mismatches:rows},null,2));
