function MemoryGameRuntime({
  initialMode,
  initialLevel,
  autoLaunch,
  embed = false,
  disableBgm = false,
  flowBgmPath,
  flowBgmEnabled = true,
  flowSfxEnabled = true,
  onExit,
  onComplete,
  onUnavailable,
  onThemeChange,
}: {
  onThemeChange?: (theme: 'light' | 'dark') => void;
  initialMode?: string;
  initialLevel?: number;
  /** SPOKEDU MASTER iframe ????? ???????????????????admin????????????????????????????????????????????????癲????????????釉먮폁???????????곕츥???꿔꺂????용끏???????????????????????????????????????? */
  embed?: boolean;
  /** ?????????????????????????????????????????????????BGM????????????????????????????? ??????????????????????BGM????????????????????????????????????? */
  disableBgm?: boolean;
  flowBgmPath?: string;
  flowBgmEnabled?: boolean;
  flowSfxEnabled?: boolean;
  /** ???????????????????????????????怨뺤떪???????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????*/
  autoLaunch?: MemoryGameAutoLaunch;
  /** autoLaunch ?????????????????????????????????????????????resume????????????????????????????????????? ????????????????????????????????????????????????????????????꾩룆梨띰쭕?뚢뵾??????????????嶺뚮죭?댁젘??????????????????????釉먮폁???????????????????살몝????????????????????????????????????????????????????????????????????????????????????????????????????????*/
  onExit?: (resume?: TrainingExitResume) => void;
  /** autoLaunch ?????????????????????????????????????????????????????????? embed???????????????????????????????????????????????????ㅻ깹??????????????????????????釉먮폁??????????????????????????? ???????????????????????MASTER)??????????? ??????????????????????? */
  onComplete?: (result: TrainingSessionResult) => void;
  /** initialMode??????????? MODES??????????????????(?????????????????????????????????????????????꾩룆梨띰쭕?뚢뵾??????????????嶺뚮죭?댁젘??????????????????????釉먮폁???????????????????살몝????????????????????????????????????????????????????????????????????????????????????????????????????????????????? ??????????????????????????????????????????????????????*/
  onUnavailable?: () => void;
}) {
  const [screen, setScreen] = useState<Screen>('home');
  useViewportScrollLock(
    screen === 'training'
    || screen === 'memory'
    || screen === 'visualReaction'
    || screen === 'flow'
    || screen === 'result',
  );
  const [settings, setSettings] = useState<Settings>(defaultSettings);
  const [pendingAutoStart, setPendingAutoStart] = useState(false);
  const autoLaunchCfgRef = useRef<Settings | null>(null);
  const initializationKeyRef = useRef<string | null>(null);
  useEffect(() => {
    if (typeof window === 'undefined') return;
    // autoLaunch에 테마가 있으면 그것만 쓰고, 없으면 항상 색상 기본값 유지(localStorage로 덮지 않음)
    const fromAuto = autoLaunch?.variantColorTheme;
    if (typeof fromAuto === 'string' && fromAuto.trim()) {
      try {
        localStorage.setItem(SPOMOVE_VARIANT_THEME_LS_KEY, fromAuto);
      } catch {
        /* ignore */
