                      ))}
                    </div>
                    {settings.mode === 'reactTrain' ? (
                    <div style={{ marginTop: '0.75rem' }}>
                      <button
                        type="button"
                        onClick={() => set('kidsSafeMode', !settings.kidsSafeMode)}
                        style={{
                          width: '100%',
                          padding: '0.6rem 0.9rem',
                          borderRadius: '0.75rem',
                          border: `2px solid ${settings.kidsSafeMode ? '#F97316' : 'var(--border)'}`,
                          background: settings.kidsSafeMode ? '#FFF7ED' : 'var(--card)',
                          color: settings.kidsSafeMode ? '#C2410C' : 'var(--text)',
                          fontWeight: 800,
                          cursor: 'pointer',
                          fontFamily: 'inherit',
                          textAlign: 'left',
                        }}
                      >
                        Kids safe mode: {settings.kidsSafeMode ? "On" : "Off"}
                      </button>
                    </div>
                    ) : null}
                  </div>
                ) : null}
                {settings.mode !== 'spatial' && settings.mode !== 'reactTrain' && (
                  <div style={S.sec}>
                    {stepNum(stepReps, "Choose repetitions")}
                    <div style={{ display: 'flex', gap: '0.4rem', flexWrap: 'wrap' }}>
                      {[10, 20, 30, 40].map((n) => (
                        <button
                          key={n}
                          type="button"
                          onClick={() => {
                            // UI???????????????????????????????????????????????????????????????????timeMode??reps??????????
                            if (settings.timeMode !== 'reps') set('timeMode', 'reps');
                            set('targetReps', n);
                          }}
                          style={{
                            padding: '0.6rem 1rem',
                            borderRadius: '0.75rem',
                            border: `2px solid ${settings.targetReps === n ? '#F97316' : 'var(--border)'}`,
                            background: settings.targetReps === n ? '#FFF7ED' : 'var(--card)',
                            fontWeight: 700,
                            cursor: 'pointer',
                            fontFamily: 'inherit',
                            color: 'var(--text)',
                          }}
                        >
                          {n}??
                        </button>
                      ))}
                    </div>
                  </div>
                )}
                <div style={S.sec}>
                  <button type="button" onClick={() => setAdvancedOpen((o) => !o)} style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', width: '100%', padding: '0.65rem 0', background: 'none', border: 'none', cursor: 'pointer', fontFamily: 'inherit', fontSize: '0.96rem', fontWeight: 700, color: '#64748B' }}>
                    <span>{advancedOpen ? "v" : ">"}</span>
                    <span>Advanced settings</span>
                  </button>
                  {advancedOpen && (
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '0.9rem', marginTop: '0.5rem', paddingTop: '0.5rem', borderTop: '1px solid #E2E8F0' }}>
                      <div>
                        <div style={{ fontSize: "0.96rem", fontWeight: 700, color: "#64748B", marginBottom: "0.35rem" }}>Warmup</div>
                        <div style={{ display: 'flex', gap: '0.4rem' }}>{[0, 3, 5].map((n) => (
                          <button key={n} type="button" onClick={() => set("warmup", n)} style={{ padding: "0.5rem 0.8rem", borderRadius: "0.6rem", border: `2px solid ${settings.warmup === n ? "#0F172A" : "#E2E8F0"}`, background: settings.warmup === n ? "#0F172A" : "#fff", color: settings.warmup === n ? "#fff" : "#475569", fontWeight: 600, fontSize: "0.96rem", cursor: "pointer", fontFamily: "inherit" }}>{n === 0 ? "None" : `${n}s`}</button>
                        ))}</div>
                      </div>
                      <div>
                        <div style={{ fontSize: "0.96rem", fontWeight: 700, color: "#64748B", marginBottom: "0.35rem" }}>Interval mode</div>
                        <button type="button" onClick={() => set("intervalMode", !settings.intervalMode)} style={{ padding: "0.5rem 0.9rem", borderRadius: "0.6rem", border: `2px solid ${settings.intervalMode ? "#22C55E" : "#E2E8F0"}`, background: settings.intervalMode ? "#F0FDF4" : "#fff", fontWeight: 600, fontSize: "0.96rem", cursor: "pointer", fontFamily: "inherit" }}>{settings.intervalMode ? "On" : "Off"}</button>
                      </div>
                      <div>
                        <div style={{ fontSize: "0.96rem", fontWeight: 700, color: "#64748B", marginBottom: "0.35rem" }}>Acceleration</div>
                        <button type="button" onClick={() => set("accel", !settings.accel)} style={{ padding: "0.5rem 0.9rem", borderRadius: "0.6rem", border: `2px solid ${settings.accel ? "#22C55E" : "#E2E8F0"}`, background: settings.accel ? "#F0FDF4" : "#fff", fontWeight: 600, fontSize: "0.96rem", cursor: "pointer", fontFamily: "inherit" }}>{settings.accel ? "On" : "Off"}</button>
                        <p style={{ fontSize: '0.82rem', color: '#94A3B8', marginTop: '0.35rem', lineHeight: 1.5 }}>
                          Gradually increases signal speed during the session.
                          <br />
                          Use this after students are comfortable with the base speed.
                        </p>
                      </div>
                    </div>
                  )}
                </div>
              </>
            )}
            {(() => {
              const needsImageAssets = readiness.requirement.minimumCount > 0;
              const assetBlocking = needsImageAssets && readiness.status !== 'ready';
              return (
                <div style={{ display: 'flex', flexDirection: 'column', gap: '0.4rem' }}>
                  {needsImageAssets && readiness.status === 'loading' && (
                    <div style={{ fontSize: '0.82rem', color: '#64748B', textAlign: 'center' }}>
                      Loading image assets... Minimum required: {readiness.requirement.minimumCount}
                    </div>
                  )}
                  {needsImageAssets && readiness.status === 'error' && (
                    <div style={{ display: 'flex', gap: '0.4rem', alignItems: 'center' }}>
                      <span style={{ fontSize: "0.82rem", color: "#EF4444", flex: 1 }}>Failed to load image assets.</span>
                      <button type="button" onClick={() => void reloadVariantAssets()} style={{ fontSize: "0.78rem", padding: "0.3rem 0.6rem", borderRadius: "0.4rem", border: "1px solid #EF4444", background: "transparent", color: "#EF4444", cursor: "pointer", fontFamily: "inherit" }}>Retry</button>
                    </div>
                  )}
                  {needsImageAssets && readiness.status === 'insufficient' && (
                    <div style={{ display: 'flex', gap: '0.4rem', alignItems: 'center' }}>
                      <span style={{ fontSize: '0.82rem', color: '#F59E0B', flex: 1 }}>
                        Need {readiness.requirement.minimumCount} image assets. Currently available: {readiness.usableAssets.length}.

                      </span>
                      <button type="button" onClick={() => void reloadVariantAssets()} style={{ fontSize: "0.78rem", padding: "0.3rem 0.6rem", borderRadius: "0.4rem", border: "1px solid #F59E0B", background: "transparent", color: "#F59E0B", cursor: "pointer", fontFamily: "inherit" }}>Retry</button>
                    </div>
                  )}
                  <div style={{ display: 'flex', gap: '0.5rem' }}>
                    <button
                      type="button"
                      disabled={assetBlocking}
                      style={{ ...S.btn, ...S.bPrimary, flex: 3, fontSize: '1.05rem', padding: '1.1rem', opacity: assetBlocking ? 0.5 : 1, cursor: assetBlocking ? 'not-allowed' : 'pointer' }}
                      onClick={() => {
                        if (assetBlocking) return;
                        // ??????????????????????????????????????????????????????????????????????fullscreen ????????(useEffect ???????????????????????????????
                        if (document.fullscreenEnabled) {
                          document.documentElement.requestFullscreen().catch((err: Error) => {
                            console.warn('[SPOMOVE] fullscreen request failed:', err.message);
                          });
                        }
                        startSession();
                      }}
                    >
                      {readiness.status === "loading" && needsImageAssets ? "Loading..." : "Start training"}
                    </button>
                  </div>
                </div>
              );
            })()}
          </div>
        </div>
      </div>
    );
  }

  // ???? MEMORY / TRAINING / RESULT ????
  const handleMemoryComplete = () => {
    if (document.fullscreenElement) exitFullscreenSafely();
    const elapsedMs = sessionStartMsRef.current > 0 ? performance.now() - sessionStartMsRef.current : 0;
    deliverSessionResult({ ...settings }, elapsedMs, null);
  };
  const runtimeSuspense = (content: React.ReactNode) => (
    <TrainingRunErrorBoundary onError={handleRuntimeError}>
      {renderRuntimeSuspense(content)}
    </TrainingRunErrorBoundary>
  );

  if (screen === 'memory') {
    if (countdown !== null) {
      return (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.85)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 400 }}>
          <style>{CSS}</style>
          <div key={countdown} className="countdown-pop" style={{ fontFamily: 'var(--spm-font-display)', fontSynthesis: 'none', fontSize: 'clamp(120px,30vw,240px)', fontWeight: 800, color: '#F97316', lineHeight: 1 }}>{countdown}</div>
        </div>
      );
    }
    if (selectedActivity.runtime === 'color-number-memory')
      return runtimeSuspense(<MemoryGameLevel4 onExit={stop} onComplete={handleMemoryComplete} audioMode={settings.audioMode} speedSec={settings.speed} startDelayMs={0} />);
    if (selectedActivity.runtime === 'color-number-quiz')
      return runtimeSuspense(<MemoryGameLevel5 onExit={stop} onComplete={handleMemoryComplete} audioMode={settings.audioMode} speedSec={settings.speed} startDelayMs={0} />);
    return runtimeSuspense(
      <MemoryGame
        level={settings.level}
        onExit={stop}
        onComplete={handleMemoryComplete}
        audioMode={settings.audioMode}
        speedSec={settings.speed}
        startDelayMs={0}
        roundCount={settings.targetReps}
        slotColorIds={settings.level === 6 ? settings.memoryColorSlots : undefined}
      />,
    );
  }

  if (screen === 'visualReaction') {
    const rawReactSpeedLevel = mapSpomoveSpeedToReactTrainSpd(settings.speed);
    const safeReactSpeedLevel = settings.kidsSafeMode
      ? Math.max(1, rawReactSpeedLevel - 2)
      : rawReactSpeedLevel;
    const safeReactSpeedSec = settings.kidsSafeMode
      ? Math.min(6, settings.speed * 1.25)
      : settings.speed;
    const visualRuntime = selectedActivity.runtime;
    const isInstantMemory =
      settings.mode === 'spatial' && isInstantMemoryLevel(settings.level);
    return runtimeSuspense(
      <div ref={visualReactionContainerRef} style={{ ...EMBED_FIXED_VIEWPORT, zIndex: 320 }}>
        <style>{CSS}</style>
        {settings.activityId === 'shape-completion' ? (
          <ShapeCompletionReactionTraining targetRounds={settings.targetReps} difficulty={settings.shapeCompletionDifficulty} responseSeconds={settings.shapeCompletionResponseSeconds} onExit={stop} onComplete={handleReactTrainComplete} />
        ) : settings.activityId === 'relative-compass' ? (
          <RelativeCompassReactionTraining
            targetRounds={settings.targetReps}
            difficulty={settings.relativeCompassDifficulty}
            startSeconds={settings.relativeCompassStartSeconds}
            responseSeconds={settings.relativeCompassResponseSeconds}
            effectsEnabled={settings.audioMode !== 'off'}
            onExit={stop}
            onComplete={handleReactTrainComplete}
          />
        ) : countdown !== null ? (
          <div style={{ position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.85)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
            <div key={countdown} className="countdown-pop" style={{ fontFamily: 'var(--spm-font-display)', fontSynthesis: 'none', fontSize: 'clamp(120px,30vw,240px)', fontWeight: 800, color: '#F97316', lineHeight: 1 }}>{countdown}</div>
          </div>
        ) : visualRuntime === 'instant-memory' ? (
          <ColorMemoryGridReactionTraining
            roundCount={Math.max(1, settings.targetReps ?? 10)}
            speedLevel={safeReactSpeedLevel}
            speedSec={safeReactSpeedSec}
            gridSize={settings.colorMemoryGridSize === 3 || settings.colorMemoryGridSize === 5 ? settings.colorMemoryGridSize : 4}
            gameMode={settings.colorMemoryGridMode === 'oneshot' ? 'oneshot' : 'flicker'}
            effectsEnabled={settings.audioMode !== 'off'}
            onExit={stop}
            onComplete={handleReactTrainComplete}
          />
        ) : visualRuntime === 'virus' ? (
          <VirusOutbreakReactionTraining
            durationSec={Math.max(1, settings.duration ?? 60)}
            speedLevel={safeReactSpeedLevel}
            speedSec={safeReactSpeedSec}
            effectsEnabled={settings.audioMode !== 'off'}
            difficulty={
              settings.virusOutbreakDifficulty === 'easy' || settings.virusOutbreakDifficulty === 'hard'
                ? settings.virusOutbreakDifficulty
                : 'normal'
            }
            onExit={stop}
            onComplete={handleReactTrainComplete}
          />
        ) : visualRuntime === 'shell-tracking' ? (
          <TargetTrackingReactionTraining
            targetRounds={settings.targetReps}
            difficulty={settings.shellTrackingDifficulty}
            targetSeconds={settings.shellTrackingTargetSeconds}
            shuffleCount={settings.shellTrackingShuffleCount}
            responseSeconds={settings.shellTrackingResponseSeconds}
            onExit={stop}
            onComplete={handleReactTrainComplete}
          />
        ) : visualRuntime === 'goalkeeper' ? (
          <GoalkeeperReactionTraining
            durationSec={Math.max(1, settings.duration ?? 120)}
            targetReps={settings.timeMode === 'reps' ? settings.targetReps : undefined}
            speedSec={safeReactSpeedSec}
            goalkeeperTier={settings.goalkeeperTier === 1 ? 1 : 2}
            bonusTimeEnabled={settings.goalkeeperBonusTimeEnabled}
            onExit={stop}
            onComplete={handleReactTrainComplete}
          />
        ) : visualRuntime === 'color-tracker' ? (
          <ColorTrackerReactionTraining
            targetRounds={normalizeColorTrackerRounds(settings.targetReps ?? 5)}
            tier={settings.colorTrackerTier}
            dualPanel={settings.colorTrackerDualPanel}
            onExit={stop}
            onComplete={handleReactTrainComplete}
          />
        ) : visualRuntime === 'number-cart' ? (
          <NumberCartReactionTraining
            targetRounds={normalizeNumberCartRounds(settings.targetReps ?? 5)}
            speedLevel={safeReactSpeedLevel}
            speedSec={safeReactSpeedSec}
            tier={settings.numberCartTier}
            onExit={stop}
            onComplete={handleReactTrainComplete}
          />
        ) : visualRuntime === 'wormhole' ? (
          <WormholeReactionTraining
            durationSec={Math.max(1, settings.duration ?? 60)}
            speedLevel={safeReactSpeedLevel}
            speedSec={safeReactSpeedSec}
            onExit={stop}
            onComplete={handleReactTrainComplete}
          />
        ) : visualRuntime === 'mole' ? (
          <RobloxMoleReactionTraining
            durationSec={Math.max(1, settings.duration ?? 60)}
            targetReps={settings.timeMode === 'reps' ? settings.targetReps : undefined}
            speedLevel={safeReactSpeedLevel}
            speedSec={safeReactSpeedSec}
            lookMode={settings.moleLookMode}
            bonusTimeEnabled={settings.moleBonusTimeEnabled}
            onExit={stop}
            onComplete={handleReactTrainComplete}
          />
        ) : visualRuntime === 'camouflage' ? (
          <CamouflageReactionTraining
            durationSec={Math.max(1, settings.duration ?? 60)}
            speedLevel={safeReactSpeedLevel}
            speedSec={safeReactSpeedSec}
            placementMode="variant"
            onExit={stop}
            onComplete={handleReactTrainComplete}
          />
        ) : visualRuntime === 'beat-wave' ? (
          <BeatWaveReactionTraining
            effectsEnabled={settings.audioMode !== 'off'}
            durationSec={Math.max(1, settings.duration ?? 60)}
            speedLevel={safeReactSpeedLevel}
            speedSec={safeReactSpeedSec}
            onExit={stop}
            onComplete={handleReactTrainComplete}
          />
        ) : visualRuntime === 'rush' ? (
          <RushReactionTraining
            durationSec={Math.max(1, settings.duration ?? 60)}
            speedLevel={safeReactSpeedLevel}
            speedSec={safeReactSpeedSec}
            onExit={stop}
            onComplete={handleReactTrainComplete}
          />
        ) : visualRuntime === 'falling-bricks' || visualRuntime === 'balloon' ? (
          <VisualReactionTraining
            variant={visualRuntime === 'falling-bricks' ? 'flow' : 'flash'}
            durationSec={Math.max(1, settings.duration ?? 60)}
            speedSec={safeReactSpeedSec}
            concurrent={visualRuntime === 'falling-bricks' ? 2 : undefined}
            onExit={stop}
            onComplete={handleReactTrainComplete}
          />
        ) : (() => { throw new Error(`SPOMOVE visual runtime has no player: ${settings.activityId}`); })()}
      </div>,
    );
  }

  if (screen === 'flow') {
    const unityThemeId = resolveDiveUnityThemeId(settings.diveEnvironmentTheme);
    if (settings.mode === 'flow' && settings.level === 1 && unityThemeId) {
      return runtimeSuspense(<UnityDiveThemeClient config={{ themeId: unityThemeId, stageDuration: settings.flowDuration, side: settings.sportsArenaFeatures.has('side'), jump: settings.sportsArenaFeatures.has('jump'), duck: settings.sportsArenaFeatures.has('duck'), bonus: settings.flowIncludeBonus }} durationSec={diveActionMoveDurationSec({ side: settings.sportsArenaFeatures.has('side'), jump: settings.sportsArenaFeatures.has('jump'), duck: settings.sportsArenaFeatures.has('duck'), bonus: settings.flowIncludeBonus }, settings.flowDuration)} onComplete={handleFlowComplete} onExit={stop} onSessionStart={startSportsArenaBgm} onSessionStop={stopSportsArenaBgm} />);
    }
    // SELECTABLE_MODULE_KEYS ?????????????????????????????????????????????????????????????????????????????????????????????????????? ??????????????????????????꾩룆梨띰쭕?뚢뵾??????????????嶺뚮죭?댁젘??????????????????????釉먮폁???????????????????살몝????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????ㅻ깹??????????????????????????釉먮폁?????????????????
    const selectedModules = [
      ...SELECTABLE_MODULE_KEYS,
      ...(settings.flowFeatures.has('colorGate') ? ['colorGate' as const] : []),
    ].filter((k) => settings.flowFeatures.has(k as FlowFeatureKey));
    const stages = buildStages(selectedModules, settings.flowDuration, {
      layout: settings.flowLayout,
      includeBonus: settings.flowIncludeBonus,
    });

    const handleFlowDone = (stats?: { colorGateColorCounts?: ColorStimulusCounts }) => {
      if (flowCompleteGuardRef.current) return;
      flowCompleteGuardRef.current = true;
      if (document.fullscreenElement) exitFullscreenSafely();
      const cfg = { ...settings };
      const elapsedMs = sessionStartMsRef.current > 0 ? performance.now() - sessionStartMsRef.current : 0;
      const flowColorCounts = stats?.colorGateColorCounts ?? null;
      deliverSessionResult(cfg, elapsedMs, flowColorCounts && totalColorStimulusCount(flowColorCounts) > 0 ? flowColorCounts : null);
    };

    return runtimeSuspense(
      <FlowGameClient
        stages={stages}
        bgmPath={flowBgmPathRef.current}
        bgmEnabled={flowBgmEnabled}
        sfxEnabled={flowSfxEnabled}
        panoramaHighUrl={divePanorama.highUrl}
        panoramaLowUrl={divePanorama.lowUrl}
        panoramaYawDeg={divePanorama.yawDeg}
        colorGateCueSeconds={settings.speed}
        colorGateTargetCount={settings.targetReps}
        colorGateVariant={settings.colorGateVariant}
        colorGateCategory={settings.colorGateCategory}
        colorGateCategories={settings.colorGateCategories}
        colorGateDifficulties={settings.colorGateDifficulties}
        onComplete={handleFlowDone}
        onExit={stop}
        onEngineReady={(api) => { flowEngineApiRef.current = api; }}
      />,
    );
  }

  if (screen === 'training') {
    if (selectedActivity.runtime === 'simon-camouflage') {
      const rawReactSpeedLevel = mapSpomoveSpeedToReactTrainSpd(settings.speed);
      const safeReactSpeedLevel = settings.kidsSafeMode
        ? Math.max(1, rawReactSpeedLevel - 2)
        : rawReactSpeedLevel;
      const safeReactSpeedSec = settings.kidsSafeMode
        ? Math.min(6, settings.speed * 1.25)
        : settings.speed;
      // 워밍업은 CamouflageReactionTraining 내부 카운트다운만 사용 (이중 3·2·1 방지)
      return runtimeSuspense(
        <div ref={trainingContainerRef} style={{ ...EMBED_FIXED_VIEWPORT, zIndex: 320 }}>
          <style>{CSS}</style>
          <CamouflageReactionTraining
            durationSec={Math.max(1, settings.duration ?? 60)}
            speedLevel={safeReactSpeedLevel}
            speedSec={safeReactSpeedSec}
            placementMode="variant"
            concurrent={settings.simonPoleCount === 2 ? 2 : 1}
            onExit={stop}
            onComplete={handleReactTrainComplete}
          />
        </div>,
      );
    }
    if (selectedActivity.runtime === 'simon-balloon') {
      const safeReactSpeedSec = settings.kidsSafeMode
        ? Math.min(6, settings.speed * 1.25)
        : settings.speed;
      // 워밍업은 VisualReactionTraining 내부 카운트다운만 사용 (이중 3·2·1 방지)
      return runtimeSuspense(
        <div ref={trainingContainerRef} style={{ ...EMBED_FIXED_VIEWPORT, zIndex: 320 }}>
          <style>{CSS}</style>
          <VisualReactionTraining
            variant="balloonSimon"
            durationSec={Math.max(1, settings.duration ?? 60)}
            speedSec={safeReactSpeedSec}
            concurrent={settings.simonPoleCount === 2 ? 2 : 1}
            onExit={stop}
            onComplete={handleReactTrainComplete}
          />
        </div>,
      );
    }
    const bg = (signal?.bg as string) ?? '#0F172A';
    const dark = bg === '#0F172A' || bg.startsWith('#0') || bg.startsWith('#1');
    return (
