function pickResultCopy(copies: readonly string[], seed: string): string {
  let hash = 0;
  for (let i = 0; i < seed.length; i++) hash = (hash * 31 + seed.charCodeAt(i)) >>> 0;
  return copies[hash % copies.length] ?? copies[0] ?? '';
}

function buildActivityFeel(
  mode: string,
