): string {
  const seed = `${programTitle ?? mode}:${level}:${colorTotal}:${Math.round(elapsedMs / 1000)}`;
  if (mode === 'stroop' && isVoiceHeavyStroop(level)) {
    return pickResultCopy([
      '목소리와 생각을 함께 썼어요',
      '규칙을 떠올리며 힘차게 답했어요',
