      '머리를 빠르게 바꿔 가며 답했어요',
    ], seed);
  }
  if (mode === 'spatial') {
    return pickResultCopy([
      '차분히 보고 기억했어요',
      '순서와 위치에 집중했어요',
      '눈으로 살피고 머릿속에 담았어요',
      '끝까지 집중하며 기억했어요',
    ], seed);
  }
  if (mode === 'flanker' || mode === 'simon') {
    return pickResultCopy([
