      praise: '오늘도 멋지게 해냈어요!',
      praiseSub: `${withObjectParticle(shapeCompletionTitle)} 끝까지 완주했어요.`,
      activityFeel: shapeFeel,
      elapsedLabel,
      volumeLabel,
      sessionHighlight: `${shapeCompletionTitle} · ${volumeLabel}`,
