        { id: 'program', label: '프로그램', value: shapeCompletionTitle },
        { id: 'activity', label: '활동', value: shapePhaseName },
        { id: 'volume', label: '설정 분량', value: volumeLabel },
        { id: 'elapsed', label: '진행 시간', value: elapsedLabel },
