interface Teacher {
  id: string;
  name: string;
  points: number;
  /** 앱 도입 이전 누적 기존값 */
  session_count: number;
  /** 앱 도입 이후 session_count_logs 건수 */
  logCount?: number;
  fee_private?: number | null;
  fee_group?: number | null;
  fee_center_main?: number | null;
  fee_center_assist?: number | null;
}

interface MileageLog {
  id: string;
  teacher_id: string;
  amount: number;
  reason: string;
  session_title: string;
  created_at: string;
  session_id?: string | null;
  session_started_at?: string | null;
}

interface SessionCountLog {
  id: string;
  teacher_id: string;
  session_id: string | null;
  session_title: string;
  count_change: number;
  reason: string;
  created_at: string;
  sessions?: { start_at: string } | null;
}

/** 회차 숫자(1/2, 4/5, 7/10 등) 제거하고 한글 제목만 반환 */
function titleWithoutRound(title: string | null | undefined): string {
  if (!title || !title.trim()) return '';
  return title
    .replace(/^\s*\d+\/\d+\s*/, '')       // 앞의 "7/10 " 제거
    .replace(/\s*[-_]?\s*\d+회차\s*$/i, '')
    .replace(/\s+\d+회\s*$/i, '')
    .replace(/\s+\d+회차\s*$/i, '')
    .trim();
}

function stripTrailingParenDate(text: string): string {
  return text.replace(/\s*\([^()]*\d{4}[^()]*\d{1,2}[^()]*\d{1,2}[^()]*\)\s*$/, '').trim();
}

/** 수업 이름(한글만) + 수업 날짜 괄호 표기 */
function formatSessionWithDate(title: string | null | undefined, dateIso: string): string {
  const clean = stripTrailingParenDate(titleWithoutRound(title));
  const dateStr = new Date(dateIso).toLocaleDateString('ko-KR', {
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    timeZone: 'Asia/Seoul',
  });
  return clean ? `${clean} (${dateStr})` : dateStr;
}

/** 운영에서 조건 충족 시 수동 지급하는 빠른 추가 항목 */
const ADDITIONAL_POINT_OPTIONS = [
  { label: '하루 수업 3개 이상 진행', value: 5000 },
  { label: '한 아이 25회 이상 수업 진행', value: 15000 },
];

interface MileageDetailModalProps {
  teacher: Teacher;
  supabase: SupabaseClient | null;
  onClose: () => void;
  onSaved?: () => void;
  /** true면 카운팅 관리 등에서 열었을 때 상단 「적용 기본 수업료」 블록 숨김 */
  hideAppliedFeePreview?: boolean;
}

function SessionCountByMonth({
  logs,
  sessionStartById,
}: {
  logs: SessionCountLog[];
  sessionStartById: Record<string, string>;
}) {
  const [openMonth, setOpenMonth] = useState<string | null>(null);

  const grouped = useMemo(() => {
    const map: Record<string, { total: number; items: SessionCountLog[] }> = {};
    for (const log of logs) {
      const d = new Date(log.created_at);
      const key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
      if (!map[key]) map[key] = { total: 0, items: [] };
      map[key].total += log.count_change;
      map[key].items.push(log);
    }
    return Object.entries(map).sort((a, b) => b[0].localeCompare(a[0]));
  }, [logs]);

  if (logs.length === 0) {
    return <div className="py-16 text-center text-slate-200 font-black italic text-sm tracking-tighter uppercase">No session logs found</div>;
  }

  return (
    <div className="space-y-1.5">
      {grouped.map(([monthKey, { total, items }]) => {
        const [y, m] = monthKey.split('-');
        const isOpen = openMonth === monthKey;
        return (
          <div key={monthKey} className="rounded-2xl border border-slate-100 overflow-hidden">
            <button
              onClick={() => setOpenMonth(isOpen ? null : monthKey)}
              className="w-full flex items-center justify-between px-4 py-3 bg-white hover:bg-slate-50 transition-colors cursor-pointer"
            >
              <div className="flex items-center gap-3">
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest w-16">{y}.{m}</span>
                <span className="text-sm font-black text-emerald-600">+{total}회</span>
                <span className="text-[9px] text-slate-300 font-bold">{items.length}건</span>
              </div>
              <ChevronDown size={14} className={`text-slate-300 transition-transform ${isOpen ? 'rotate-180' : ''}`} />
            </button>
            {isOpen && (
              <div className="border-t border-slate-50 divide-y divide-slate-50">
                {items.map((log) => (
                  (() => {
                    const resolvedDateIso =
                      (log.session_id ? sessionStartById[log.session_id] : undefined)
                      ?? log.sessions?.start_at
                      ?? log.created_at;
                    return (
                  <div key={log.id} className="flex items-center justify-between px-4 py-2.5 bg-slate-50/50">
                    <div className="flex items-center gap-3 min-w-0">
                      <span className="text-[10px] font-black text-slate-400 shrink-0">
                        {new Date(resolvedDateIso).toLocaleDateString('ko-KR', {
                          month: 'numeric',
                          day: 'numeric',
                          timeZone: 'Asia/Seoul',
                        })}
                      </span>
                      <span className="text-[11px] font-bold text-slate-700 truncate">
                        {formatSessionWithDate(log.session_title, resolvedDateIso)}
                      </span>
                    </div>
                    <span className="text-[10px] font-black text-emerald-500 shrink-0 ml-2">+{log.count_change}</span>
                  </div>
                    );
                  })()
                ))}
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

export default function MileageDetailModal({
  teacher,
  supabase,
  onClose,
  onSaved,
  hideAppliedFeePreview = false,
}: MileageDetailModalProps) {
  const [modalTab, setModalTab] = useState<'mileage' | 'sessions'>('mileage');
  const [teacherLogs, setTeacherLogs] = useState<MileageLog[]>([]);
  const [mileageSessionStartById, setMileageSessionStartById] = useState<Record<string, string>>({});
  const [mileageOptionBySessionId, setMileageOptionBySessionId] = useState<Record<string, string>>({});
  const [countSessionStartById, setCountSessionStartById] = useState<Record<string, string>>({});
  const [teacherCountLogs, setTeacherCountLogs] = useState<SessionCountLog[]>([]);
  const [pointDeltaInput, setPointDeltaInput] = useState('');
  const [displayPoints, setDisplayPoints] = useState(teacher.points || 0);
  const [editSessionCount, setEditSessionCount] = useState<number>(teacher.session_count || 0);
  const [selectedAdditional, setSelectedAdditional] = useState<string>('');
  const [editReason, setEditReason] = useState<string>('');
  const [lastAdditionalLog, setLastAdditionalLog] = useState<MileageLog | null>(null);
  const [tierFeeMap, setTierFeeMap] = useState<TierFeeMap>(() => cloneTierFeeMap(HARD_CODED_TIER_FEES));
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
  }, []);

  const tierFeePreview = useMemo(() => {
    if (hideAppliedFeePreview) return null;
    const tier = computeTier(totalLessonsFromCounts(teacher.session_count, teacher.logCount));
    return effectiveFees(tier, {
      ...teacher,
      fee_private: teacher.fee_private ?? null,
      fee_group: teacher.fee_group ?? null,
      fee_center_main: teacher.fee_center_main ?? null,
      fee_center_assist: teacher.fee_center_assist ?? null,
    }, tierFeeMap);
  }, [
    hideAppliedFeePreview,
    teacher.name,
    teacher.session_count,
    teacher.logCount,
    teacher.fee_private,
    teacher.fee_group,
    teacher.fee_center_main,
    teacher.fee_center_assist,
    tierFeeMap,
  ]);

  useEffect(() => {
    if (hideAppliedFeePreview) return;
    let mounted = true;
    const run = async () => {
      const { map: next } = await fetchTeacherTierFeeMap(supabase);
      if (!mounted) return;
      setTierFeeMap(next);
    };
    void run();
    return () => {
      mounted = false;
    };
  }, [supabase, hideAppliedFeePreview]);

  const loadLogs = useCallback(async () => {
    if (!supabase || !teacher?.id) return;
    const { data: mData } = await supabase
      .from('mileage_logs')
      .select('*')
      .eq('teacher_id', teacher.id)
      .order('created_at', { ascending: false });
    if (mData) {
      const logs = mData as MileageLog[];
      setTeacherLogs(logs);
      const ids = Array.from(
        new Set(
          logs
            .map((l) => l.session_id)
            .filter((v): v is string => typeof v === 'string' && v.trim().length > 0)
        )
      );
      if (ids.length > 0) {
        const { data: sessions } = await supabase
          .from('sessions')
          .select('id, start_at, mileage_option')
          .in('id', ids);
        const map: Record<string, string> = {};
        const optionMap: Record<string, string> = {};
        (sessions || []).forEach((s) => {
          if (s.id && s.start_at) map[s.id] = s.start_at;
          if (s.id) optionMap[s.id] = s.mileage_option ?? '';
        });
        setMileageSessionStartById(map);
        setMileageOptionBySessionId(optionMap);
      } else {
        setMileageSessionStartById({});
        setMileageOptionBySessionId({});
      }
    }

    const { data: cData } = await supabase
      .from('session_count_logs')
      .select('*, sessions(start_at)')
      .eq('teacher_id', teacher.id)
      .order('created_at', { ascending: false });
    if (cData) {
      const logs = cData as SessionCountLog[];
      setTeacherCountLogs(logs);
      const ids = Array.from(
        new Set(
          logs
            .map((l) => l.session_id)
            .filter((v): v is string => typeof v === 'string' && v.trim().length > 0)
        )
      );
      if (ids.length > 0) {
        const { data: sessions } = await supabase
          .from('sessions')
          .select('id, start_at')
          .in('id', ids);
        const map: Record<string, string> = {};
        (sessions || []).forEach((s) => {
          if (s.id && s.start_at) map[s.id] = s.start_at;
        });
        setCountSessionStartById(map);
      } else {
        setCountSessionStartById({});
      }
    }
  }, [supabase, teacher?.id]);

  useEffect(() => {
    setDisplayPoints(teacher.points || 0);
    setPointDeltaInput('');
    setEditSessionCount(teacher.session_count || 0);
    setSelectedAdditional('');
    setEditReason('');
    setTeacherLogs([]);
    setMileageSessionStartById({});
    setMileageOptionBySessionId({});
    setCountSessionStartById({});
    setTeacherCountLogs([]);
    setLastAdditionalLog(null);
    loadLogs();
  }, [teacher, loadLogs]);

  const parsedPointDelta = useMemo(() => {
    const trimmed = pointDeltaInput.trim();
    if (!trimmed || trimmed === '-' || trimmed === '+') return 0;
    const n = Number(trimmed);
    return Number.isFinite(n) ? n : NaN;
  }, [pointDeltaInput]);

  const handleApplyMileageDelta = async () => {
    if (!supabase || !teacher) return;
    if (!Number.isFinite(parsedPointDelta) || parsedPointDelta === 0) {
      toast.error('변동 포인트를 입력하세요. (예: 1000, -1000)');
      return;
    }
    if (!editReason.trim()) {
      toast.error('마일리지 변경 사유를 입력하세요.');
      return;
    }

    try {
      const result = await postMileageAdjustment({
        operation: 'apply',
        teacherId: teacher.id,
        pointDelta: parsedPointDelta,
        reason: editReason.trim(),
      });
      if (!result.ok || typeof result.points !== 'number') throw new Error(result.code ?? result.error);
      setDisplayPoints(result.points);
      toast.success('마일리지가 반영되었습니다.');
      setPointDeltaInput('');
      setEditReason('');
      onSaved?.();
      loadLogs();
    } catch (error: unknown) {
      toast.error('실패: ' + (error instanceof Error ? error.message : String(error)));
    }
  };

  const handleSaveSessionCount = async () => {
    if (!supabase || !teacher) return;
    const prevSessionCount = teacher.session_count || 0;
    const nextSessionCount = editSessionCount;

    if (prevSessionCount === nextSessionCount) {
      toast.error('변경된 내용이 없습니다.');
      return;
    }

    try {
      const { error: uError } = await supabase.from('users').update({ session_count: nextSessionCount }).eq('id', teacher.id);
      if (uError) throw uError;

      toast.success('기존 수업 수가 반영되었습니다.');
      onSaved?.();
      onClose();
    } catch (error: unknown) {
      toast.error('실패: ' + (error instanceof Error ? error.message : String(error)));
    }
  };

  const handleCancelSessionSettlement = async (log: MileageLog) => {
    if (!supabase || !teacher || !log.session_id) return;
    const sessionId = log.session_id;
    const expectedOption = mileageOptionBySessionId[sessionId] ?? '';
    const { data: linkedRows } = await supabase
      .from('mileage_logs')
      .select('id, teacher_id, amount, reason, users(name)')
      .eq('session_id', sessionId);
    const linkedOnSession = (linkedRows ?? []).filter((row) =>
      isSessionLinkedMileageReason(row.reason),
    );
    if (linkedOnSession.length === 0) return;

    const lines = linkedOnSession
      .map((row) => {
        const name = (row.users as { name?: string } | null)?.name ?? row.teacher_id;
        return `- ${name}: ${Number(row.amount).toLocaleString()}P (${row.reason})`;
      })
      .join('\n');
    if (
      !confirm(
        `수업 연동 정산 전체 취소\n세션: ${sessionId}\n정산 옵션: ${expectedOption || '(없음)'}\n\n대상 ${linkedOnSession.length}건:\n${lines}\n\n모든 강사 포인트를 위 금액만큼 되돌립니다. 계속할까요?`,
      )
    ) {
      return;
    }

    try {
      const result = await postMileageCancelSessionSettlement({
        sessionId,
        expectedMileageOption: expectedOption,
      });
      if (!result.ok) throw new Error(result.code ?? result.error);
      setTeacherLogs((prev) =>
        prev.filter(
          (row) => row.session_id !== sessionId || !isSessionLinkedMileageReason(row.reason),
        ),
      );
      onSaved?.();
      loadLogs();
      toast.success('수업 연동 정산이 전체 취소되었습니다.');
    } catch (error: unknown) {
      toast.error('정산 취소 실패: ' + (error instanceof Error ? error.message : String(error)));
    }
  };

  const handleDeleteLog = async (logId: string) => {
    if (!supabase || !teacher) return;
    const logToDelete = teacherLogs.find(l => l.id === logId);
    if (!logToDelete) return;
    const pointDelta = getMileageLogPointDelta(logToDelete, MILEAGE_ACTIONS);
    const linked = isSessionLinkedMileageReason(logToDelete.reason);
    const reverseDelta = linked ? Number(logToDelete.amount) : pointDelta;
    if (
      !confirm(
        linked
          ? `이 강사의 수업 연동 기록 1건만 취소합니다 (다른 강사 로그는 유지).\n${Math.abs(reverseDelta).toLocaleString()}P를 ${reverseDelta > 0 ? '차감' : '복구'}합니다. 계속할까요?`
          : `이 기록을 삭제하고 마일리지 ${pointDelta > 0 ? '-' : '+'}${Math.abs(pointDelta).toLocaleString()}P를 복구하시겠습니까?`,
      )
    ) {
      return;
    }

    try {
      const result = linked
        ? await postMileageCancelSingle({
            teacherId: teacher.id,
            logId,
            expectedLogAmount: logToDelete.amount,
            expectedLogReason: logToDelete.reason,
          })
        : await postMileageAdjustment({
            operation: 'reverse',
            teacherId: teacher.id,
            pointDelta: -pointDelta,
            logId,
            expectedLogAmount: logToDelete.amount,
            expectedLogReason: logToDelete.reason,
          });
      if (!result.ok || typeof result.points !== 'number') throw new Error(result.code ?? result.error);
      setTeacherLogs((prev) => prev.filter((l) => l.id !== logId));
      setDisplayPoints(result.points);
      onSaved?.();
      toast.success('마일리지가 복구되었습니다.');
    } catch (error: unknown) {
      toast.error("취소 실패: " + (error instanceof Error ? error.message : String(error)));
    }
  };

  const handleQuickAdditional = async () => {
    if (!supabase || !teacher || !selectedAdditional) return;
    const item = ADDITIONAL_POINT_OPTIONS.find((p) => p.label === selectedAdditional);
    if (!item) return;
    if (!confirm(`${teacher.name} 강사에게 ${item.label} (+${item.value.toLocaleString()}P)를 지급하시겠습니까?`)) return;

    try {
      const result = await postMileageAdjustment({
        operation: 'apply',
        teacherId: teacher.id,
        pointDelta: item.value,
        reason: `[추가] ${item.label}`,
      });
      if (!result.ok || typeof result.points !== 'number' || !result.logId) throw new Error(result.code ?? result.error);
      const newLog: MileageLog = {
        id: result.logId,
        teacher_id: teacher.id,
        amount: item.value,
        reason: `[추가] ${item.label}`,
        session_title: '운영진 조치',
        created_at: new Date().toISOString(),
      };
      setLastAdditionalLog(newLog);
      setDisplayPoints(result.points);
      toast.success('지급이 완료되었습니다.');
      onSaved?.();
      loadLogs();
    } catch (error: unknown) {
      toast.error('지급 실패: ' + (error instanceof Error ? error.message : String(error)));
    }
  };

  const handleUndoAdditional = async () => {
    if (!supabase || !teacher || !lastAdditionalLog) return;
    if (!confirm(`최근 추가 항목 (${lastAdditionalLog.amount.toLocaleString()}P) 지급을 취소하시겠습니까?`)) return;

    try {
      const result = await postMileageAdjustment({
        operation: 'reverse',
        teacherId: teacher.id,
        pointDelta: -lastAdditionalLog.amount,
        logId: lastAdditionalLog.id,
        expectedLogAmount: lastAdditionalLog.amount,
        expectedLogReason: lastAdditionalLog.reason,
      });
      if (!result.ok || typeof result.points !== 'number') throw new Error(result.code ?? result.error);
      setLastAdditionalLog(null);
      setDisplayPoints(result.points);
      toast.success('추가 지급이 취소되었습니다.');
      onSaved?.();
      loadLogs();
    } catch (error: unknown) {
      toast.error('취소 실패: ' + (error instanceof Error ? error.message : String(error)));
    }
  };

  const mileageLogDateIso = (log: MileageLog) =>
    (log.session_id ? mileageSessionStartById[log.session_id] : undefined)
      ?? log.session_started_at
      ?? log.created_at;

  if (!mounted) return null;

  return createPortal(
    <div className="fixed inset-0 bg-slate-950/40 backdrop-blur-sm z-[400] flex items-end sm:items-center justify-center p-0 sm:p-4 cursor-default" onClick={onClose}>
      <div className="bg-white w-full max-w-xl rounded-t-[32px] sm:rounded-[32px] shadow-2xl overflow-hidden flex flex-col max-h-[90vh]" onClick={e => e.stopPropagation()}>
        <div className="p-6 sm:p-8 overflow-y-auto">
          <div className="flex justify-between items-start mb-6">
            <div>
              <div className="flex flex-wrap items-center gap-2 mb-1">
                <h2 className="text-xl font-black text-slate-950 italic uppercase tracking-tighter">{teacher.name} T</h2>
                <TeacherTierBadge sessionCount={teacher.session_count} logCount={teacher.logCount} />
              </div>
              <p className="text-blue-600 font-black text-2xl mt-1">{displayPoints.toLocaleString()} <span className="text-xs">P</span></p>
              <p className="text-slate-400 font-bold text-sm mt-1 flex items-center gap-1 flex-wrap">
                <BookOpen size={14} /> {((teacher.session_count || 0) + (teacher.logCount || 0)).toLocaleString()}회 수업 완료
                {teacher.logCount !== undefined && teacher.logCount > 0 && (
                  <span className="text-[10px] text-slate-300 ml-1">(기존 {(teacher.session_count || 0)} + 신규 {teacher.logCount})</span>
                )}
              </p>
              {!hideAppliedFeePreview && tierFeePreview && (
                <div className="mt-3 rounded-xl border border-slate-100 bg-slate-50 px-3 py-2 text-[10px] font-bold text-slate-600">
                  <span className="text-slate-400 font-black uppercase tracking-wider">적용 기본 수업료</span>
                  <div className="mt-1 grid grid-cols-2 gap-x-2 gap-y-0.5">
                    <span className="text-slate-400">개인</span>
                    <span>{tierFeePreview.fee_private.toLocaleString()}원</span>
                    <span className="text-slate-400">그룹</span>
                    <span>{tierFeePreview.fee_group.toLocaleString()}원</span>
                    <span className="text-slate-400">센터 메인</span>
                    <span>{tierFeePreview.fee_center_main.toLocaleString()}원</span>
                    <span className="text-slate-400">센터 보조</span>
                    <span>{tierFeePreview.fee_center_assist.toLocaleString()}원</span>
                  </div>
                </div>
              )}
            </div>
            <button onClick={onClose} className="min-h-[44px] min-w-[44px] hover:bg-slate-100 p-2 rounded-full transition-colors cursor-pointer text-slate-400 flex items-center justify-center touch-manipulation"><X size={20}/></button>
          </div>

          <div className="mb-4 space-y-3">
            <div>
              <div className="p-1.5 bg-slate-50 rounded-2xl border border-slate-100 flex items-center gap-2">
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-3 shrink-0">변동 포인트</span>
                <input
                  type="number"
                  value={pointDeltaInput}
                  onChange={(e) => setPointDeltaInput(e.target.value)}
                  placeholder="예: 1000 또는 -1000"
                  className="flex-1 bg-transparent px-4 py-2 font-black text-blue-600 text-lg outline-none cursor-text placeholder:text-blue-200 placeholder:font-bold placeholder:text-sm"
                />
                <span className="text-[10px] font-black text-slate-300 pr-3 shrink-0">P</span>
              </div>
              {Number.isFinite(parsedPointDelta) && parsedPointDelta !== 0 && (
                <p className="mt-1.5 px-3 text-[10px] font-bold text-slate-400">
                  반영 후 예상:{' '}
                  <span className="text-blue-600 font-black">
                    {((displayPoints) + parsedPointDelta).toLocaleString()}P
                  </span>
                </p>
              )}
              <div className="mt-2 p-1.5 bg-blue-50 rounded-xl border border-blue-100 flex items-center gap-2">
                <span className="text-[9px] font-bold text-blue-600 uppercase tracking-wider px-3 shrink-0">변경 사유</span>
                <input
                  type="text"
                  value={editReason}
                  onChange={(e) => setEditReason(e.target.value)}
                  placeholder="예: 베스트 수업안 보너스, 보고 누락 차감 등"
                  className="flex-1 bg-transparent px-4 py-2 font-bold text-blue-700 text-sm outline-none cursor-text"
                />
              </div>
              <button
                onClick={() => void handleApplyMileageDelta()}
                className="mt-2 w-full bg-slate-900 text-white px-5 py-3 rounded-xl font-black text-xs flex items-center justify-center gap-2 hover:bg-blue-600 transition-all shadow-md cursor-pointer"
              >
                <Save size={14}/> 마일리지 반영
              </button>
            </div>
            <div className="p-1.5 bg-slate-50 rounded-2xl border border-slate-100 flex items-center gap-2">
              <div className="px-3">
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">기존 수업 수</span>
                {(teacher.logCount ?? 0) > 0 && (
                  <p className="text-[9px] text-slate-300 mt-0.5">신규 {teacher.logCount}회 별도 합산</p>
                )}
              </div>
              <input
                type="number"
                value={editSessionCount}
                onChange={(e) => setEditSessionCount(Number(e.target.value))}
                className="flex-1 bg-transparent px-4 py-2 font-black text-emerald-600 text-lg outline-none cursor-text"
              />
            </div>
            <button
              onClick={() => void handleSaveSessionCount()}
              className="w-full bg-emerald-600 text-white px-5 py-3 rounded-xl font-black text-xs flex items-center justify-center gap-2 hover:bg-emerald-700 transition-all shadow-md cursor-pointer"
            >
              <Save size={14}/> 기존 수업 수 저장
            </button>
          </div>

          <div className="border-t border-slate-100 pt-6 mb-8">
            <h4 className="text-[10px] font-black text-emerald-600 uppercase tracking-widest mb-3">추가 항목</h4>
            <div className="space-y-2">
              <select
                value={selectedAdditional}
                onChange={(e) => setSelectedAdditional(e.target.value)}
                className="w-full bg-emerald-50 border-2 border-emerald-100 rounded-xl px-4 py-3 text-sm font-bold outline-none focus:border-emerald-600 cursor-pointer"
              >
                <option value="">추가 항목 선택</option>
                {ADDITIONAL_POINT_OPTIONS.map((option) => (
                  <option key={option.label} value={option.label}>
                    {option.label} (+{option.value.toLocaleString()}P)
                  </option>
                ))}
              </select>
              <div className="flex gap-2">
                <button
                  onClick={handleQuickAdditional}
                  disabled={!selectedAdditional}
                  className="flex-1 bg-emerald-600 text-white px-5 py-3.5 rounded-xl font-black text-xs flex items-center justify-center gap-2 hover:bg-emerald-700 transition-all shadow-md cursor-pointer disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  지급 실행
                </button>
                <button
                  onClick={handleUndoAdditional}
                  disabled={!lastAdditionalLog}
                  className="px-5 py-3.5 bg-amber-100 text-amber-800 rounded-xl font-black text-xs hover:bg-amber-200 transition-all cursor-pointer disabled:opacity-30 disabled:cursor-not-allowed"
                  title="최근 추가 항목 지급 취소"
                >
                  롤백
                </button>
              </div>
            </div>
          </div>

          <div className="space-y-4">
            <div className="flex items-center gap-2 px-1">
              <Calendar size={14} className="text-slate-300"/>
              <h3 className="text-[9px] font-black text-slate-300 uppercase tracking-widest">Activity History</h3>
            </div>

            <div className="flex gap-2 bg-slate-50 rounded-xl p-1">
              <button
                onClick={() => setModalTab('mileage')}
                className={`flex-1 py-2 px-3 rounded-lg text-[10px] font-black uppercase tracking-wider transition-all cursor-pointer ${
                  modalTab === 'mileage' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'
                }`}
              >
                마일리지
              </button>
              <button
                onClick={() => setModalTab('sessions')}
                className={`flex-1 py-2 px-3 rounded-lg text-[10px] font-black uppercase tracking-wider transition-all cursor-pointer ${
                  modalTab === 'sessions' ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'
                }`}
              >
                수업 카운팅
              </button>
            </div>

            {modalTab === 'mileage' && (
              (() => {
                const visibleLogs = teacherLogs.filter((log) => !log.reason?.includes('[취소]'));
                return visibleLogs.length > 0 ? (
                visibleLogs.map((log) => {
                  const displayAmount = getMileageLogDisplayAmount(log, MILEAGE_ACTIONS);
                  const dateIso = mileageLogDateIso(log);
                  const { primary, secondary } = resolveMileageLogDisplayText(
                    log,
                    formatSessionWithDate(log.session_title, dateIso),
                  );
                  return (
                  <div key={log.id} className="flex items-center justify-between p-4 rounded-2xl border border-slate-50 bg-white shadow-sm hover:border-blue-100 transition-all">
                    <div className="flex items-center gap-4 sm:gap-6 min-w-0">
                      <div className={`text-sm font-black w-20 sm:w-24 shrink-0 ${displayAmount >= 0 ? 'text-blue-600' : 'text-red-500'}`}>
                        {displayAmount > 0 ? '+' : ''}{displayAmount.toLocaleString()}P
                      </div>
                      <div className="hidden xs:block h-6 w-[1px] bg-slate-100 shrink-0"></div>
                      <div className="min-w-0">
                        <p className="text-[12px] sm:text-[13px] font-black text-slate-800 leading-snug break-words">
                          {primary}
                        </p>
                        {secondary && (
                          <p className="text-[9px] font-bold text-slate-400 mt-0.5">{secondary}</p>
                        )}
                      </div>
                    </div>
                    <div className="flex items-center gap-2">
                      <span className="text-[9px] font-bold text-slate-300 tabular-nums whitespace-nowrap">{new Date(log.created_at).toLocaleDateString()}</span>
                      {log.session_id && isSessionLinkedMileageReason(log.reason) && (
                        <button
                          type="button"
                          onClick={() => void handleCancelSessionSettlement(log)}
                          className="text-[9px] font-black text-amber-600 hover:text-amber-800 px-1.5 py-0.5 rounded border border-amber-200"
                          title="이 수업의 연동 정산 전체 취소"
                        >
                          정산 전체
                        </button>
                      )}
                      <button onClick={() => void handleDeleteLog(log.id)} className="text-slate-200 hover:text-red-500 transition-colors p-1 cursor-pointer" title="이 강사 로그 1건만 취소">
                        <Trash2 size={14}/>
                      </button>
                    </div>
                  </div>
                  );
                })
              ) : (
                <div className="py-16 text-center text-slate-200 font-black italic text-sm tracking-tighter uppercase">No mileage logs found</div>
              );
              })()
            )}

            {modalTab === 'sessions' && (
              <SessionCountByMonth logs={teacherCountLogs} sessionStartById={countSessionStartById} />
            )}
          </div>
        </div>
        <div className="p-6 pt-0">
          <button onClick={onClose} className="w-full py-4 bg-slate-100 text-slate-900 rounded-2xl font-black text-xs hover:bg-slate-200 transition-all cursor-pointer">CLOSE</button>
        </div>
      </div>
    </div>,
    document.body,
  );
}

'use client';

import type { ReactNode } from 'react';
import { SiteFooter, SiteHeader } from './site-chrome';
import { usePathname } from 'next/navigation';
import { useEffect } from 'react';
import { captureAcquisitionFromLocation } from '../lib/acquisition';
import { scrollSpokeduToTopOrHash } from '../lib/scroll';
import './website-chrome.css';

/** Shared public chrome approved in Phase D. Unverified address remains withheld. */
export function WebsiteChrome({ children }: { children: ReactNode }) {
  const pathname = usePathname();
  useEffect(() => { captureAcquisitionFromLocation(); }, []);
  useEffect(() => {
    const frame = window.requestAnimationFrame(scrollSpokeduToTopOrHash);
    return () => window.cancelAnimationFrame(frame);
  }, [pathname]);
  return (
    <div className="phase-d-preview" data-spokedu-website-chrome="true">
      <link rel="stylesheet" href="https://cdn.jsdelivr.net/gh/orioncactus/pretendard@v1.3.9/dist/web/variable/pretendardvariable-dynamic-subset.min.css" />
      <link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;600;700;800;900&display=swap" />
      <a href="#main-content" className="sr-only focus:not-sr-only focus:absolute focus:top-4 focus:left-4 focus:z-[100] focus:bg-white focus:p-4">본문 바로가기</a>
      <SiteHeader />
      <div className="website-content">{children}</div>
      <SiteFooter omitUnverifiedAddress />
    </div>
  );
}

