  mat: { src: '/images/spokedu/spomat-layout.png', alt: 'SPOMAT 실제 제품 — 위 빨강·노랑, 아래 초록·파랑의 2×2 매트' },
};

const steps = [
  { label: 'SEE', title: '시각정보 인지', Icon: Eye },
  { label: 'THINK', title: '규칙 이해·반응 선택', Icon: Brain },
  { label: 'MOVE', title: '신체 움직임 수행', Icon: MoveUpRight },
