    {home ? <SpomoveProcessingFlow /> : <figcaption>화면 자극을 확인하고, 규칙에 따라 4색 매트 위에서 움직이는 실제 수업 현장</figcaption>}
  </figure>;
}

export function SpomatProductPhoto() {
  return <figure className="web-spomat-product"><div><img src={spomovePhotos.mat.src} alt={spomovePhotos.mat.alt} loading="lazy" width={322} height={337} /></div><figcaption><strong>SPOMAT · 4색 2×2 매트</strong><span>위 빨강·노랑 / 아래 초록·파랑</span></figcaption></figure>;
}

import Link from 'next/link';
import { educationHubPage as education } from '../../data/education-hub';
import { aboutPage } from '../../data/about-page';
import { aboutFounder } from '../../data/about-founder';
import { privatePage } from '../../data/private-page';
import { educationPrograms } from '../data/education';
import { PUBLIC_METRICS, PUBLIC_OPERATING_METRICS } from '../../data/marketing-public-metrics';
