function docker(args) {
  return execFileSync('docker', ['exec', n8nContainer, ...args], { encoding: 'utf8' });
}

function shell(cmd, args, opts = {}) {
  return execFileSync(cmd, args, { encoding: 'utf8', cwd: root, ...opts });
